// Soal tambahan Kurikulum Merdeka - IPA. Ditambahkan di AKHIR tiap topik supaya nomor soal lama (review guru) tidak berubah.
(() => {
  const TAMBAHAN = {
    "ipa-k3-0": [
      {lv:1,q:"Bagian bunga yang menghasilkan serbuk sari adalah...",o:["Benang sari","Putik","Kelopak bunga","Tangkai bunga"],a:0,p:"Benang sari adalah alat kelamin jantan pada bunga. Di ujungnya terdapat kepala sari yang berisi serbuk sari."},
      {lv:1,q:"Bagian tumbuhan yang di dalamnya biasanya terdapat biji adalah...",o:["Akar","Daun","Buah","Batang"],a:2,p:"Setelah bunga diserbuki, bunga berkembang menjadi buah. Biji tumbuh di dalam buah dan kelak bisa menjadi tanaman baru."},
      {lv:1,q:"Lubang-lubang sangat kecil pada daun tempat keluar masuknya udara disebut...",o:["Klorofil","Tulang daun","Rambut akar","Stomata (mulut daun)"],a:3,p:"Stomata adalah mulut daun. Melalui lubang kecil ini udara keluar masuk dan uap air dilepaskan."},
      {lv:1,q:"Wortel yang biasa dimasak menjadi sayur sop sebenarnya adalah bagian tumbuhan berupa...",o:["Batang","Akar","Daun","Bunga"],a:1,p:"Wortel adalah akar tunggang yang membesar karena menyimpan cadangan makanan."},
      {lv:1,q:"Akar yang bentuknya seperti serabut dan ukurannya hampir sama besar, misalnya pada padi dan jagung, disebut akar...",o:["Tunggang","Napas","Serabut","Gantung"],a:2,p:"Akar serabut terdiri dari banyak akar kecil yang sama besar dan tumbuh dari pangkal batang, seperti pada padi dan jagung."},
      {lv:1,q:"Bagian bunga yang berwarna cerah dan berfungsi menarik perhatian serangga adalah...",o:["Mahkota bunga","Kelopak bunga","Tangkai bunga","Kepala putik"],a:0,p:"Mahkota bunga biasanya berwarna cerah dan harum sehingga menarik serangga untuk datang dan membantu penyerbukan."},
      {lv:2,q:"Kentang yang kita makan memiliki mata tunas dan merupakan tempat penyimpanan makanan. Kentang adalah bagian tumbuhan berupa...",o:["Akar","Batang (umbi batang)","Daun","Buah"],a:1,p:"Kentang adalah umbi batang. Buktinya, kentang memiliki mata tunas yang dapat tumbuh menjadi tanaman baru, ciri yang dimiliki batang."},
      {lv:2,q:"Bayam, kangkung, dan sawi sering dimasak menjadi sayur. Bagian tumbuhan yang terutama kita makan dari tanaman tersebut adalah...",o:["Akar","Bunga","Biji","Daun"],a:3,p:"Pada bayam, kangkung, dan sawi, bagian yang paling banyak dimakan adalah daunnya yang lunak dan bergizi."},
      {lv:2,q:"Tanaman di depan rumah Dayu mendapat cahaya matahari setiap hari. Cahaya matahari terutama dibutuhkan daun untuk...",o:["Menyerap air dari tanah","Menahan tanah agar tidak longsor","Menghasilkan serbuk sari","Membuat makanan"],a:3,p:"Daun membuat makanan melalui fotosintesis. Proses ini membutuhkan cahaya matahari, air, dan udara."},
      {lv:2,q:"Tumbuhan yang memiliki akar tunggang (satu akar besar yang tumbuh lurus ke bawah) contohnya adalah...",o:["Padi","Pohon mangga","Jagung","Rumput teki"],a:1,p:"Pohon mangga memiliki akar tunggang. Padi, jagung, dan rumput memiliki akar serabut."},
      {lv:2,q:"Saat bunga masih kuncup, ada bagian berwarna hijau yang membungkusnya. Bagian ini adalah kelopak bunga yang berfungsi untuk...",o:["Melindungi bunga saat masih kuncup","Menghasilkan serbuk sari","Menyerap air dari tanah","Membuat buah terasa manis"],a:0,p:"Kelopak bunga membungkus dan melindungi bagian dalam bunga ketika bunga masih kuncup."},
      {lv:2,q:"Batang tebu terasa manis ketika digigit. Hal ini karena batang tebu juga berfungsi sebagai...",o:["Tempat menyerap air dari tanah","Tempat tumbuhnya biji","Tempat menyimpan cadangan makanan berupa gula","Alat untuk menarik serangga"],a:2,p:"Selain menegakkan tumbuhan, batang tebu menyimpan cadangan makanan dalam bentuk gula. Itulah sebabnya tebu terasa manis."},
      {lv:3,q:"Yohanes memasukkan tangkai bunga putih ke dalam gelas berisi air yang diberi pewarna merah. Esok harinya kelopak bunga tampak kemerahan. Percobaan ini menunjukkan bahwa...",o:["Bunga menyerap warna merah dari udara","Tangkai (batang) mengangkut air dari bawah ke bagian atas tumbuhan","Daun membuat pewarna merah sendiri","Bunga putih selalu berubah menjadi merah"],a:1,p:"Air berwarna naik melalui saluran di dalam tangkai sampai ke kelopak bunga. Ini membuktikan batang berfungsi mengangkut air."},
      {lv:3,q:"Mengapa menanam pohon di lereng bukit dapat membantu mencegah tanah longsor?",o:["Daun pohon menahan air hujan agar tidak turun sama sekali","Bunga pohon membuat tanah menjadi keras","Batang pohon menyerap seluruh air hujan","Akar pohon mengikat butiran tanah sehingga tanah tidak mudah terbawa air"],a:3,p:"Akar menyebar dan mencengkeram tanah. Tanah yang terikat akar tidak mudah hanyut atau longsor saat hujan deras."},
      {lv:3,q:"Kaktus hidup di gurun yang sangat kering. Daunnya berubah bentuk menjadi duri. Apa keuntungan daun berbentuk duri bagi kaktus?",o:["Membuat kaktus menghasilkan makanan lebih banyak","Membuat akar kaktus lebih panjang","Mengurangi penguapan air dari tubuh kaktus","Membuat bunga kaktus cepat mekar"],a:2,p:"Duri sangat kecil sehingga sedikit sekali air yang menguap. Kaktus pun bisa menghemat air di tempat kering."},
      {lv:3,q:"Sebuah tanaman pot disimpan di kamar gelap selama dua minggu. Daunnya menjadi pucat kekuningan. Penyebab yang paling tepat adalah...",o:["Daun tidak mendapat cahaya sehingga tidak dapat membuat makanan dengan baik","Akar menyerap terlalu banyak cahaya","Batang tanaman menjadi terlalu keras","Bunga tanaman menghabiskan semua air"],a:0,p:"Tanpa cahaya, daun tidak dapat berfotosintesis dan zat hijau daun tidak terbentuk dengan baik, sehingga daun menguning."},
      {lv:3,q:"Seekor lebah hinggap di bunga untuk mengambil madu. Serbuk sari menempel di tubuhnya, lalu jatuh di kepala putik bunga lain. Apa akibatnya bagi tumbuhan?",o:["Bunga dapat terserbuki lalu membentuk buah dan biji","Bunga menjadi layu dan mati","Daun berubah warna menjadi merah","Akar tumbuhan berhenti tumbuh"],a:0,p:"Serbuk sari yang jatuh ke kepala putik menyebabkan penyerbukan. Setelah itu bunga dapat berkembang menjadi buah yang berisi biji."},
      {lv:3,q:"Rina mengamati dua tanaman. Tanaman A berakar serabut, sedangkan tanaman B berakar tunggang. Pasangan tanaman yang tepat adalah...",o:["A = pohon jambu, B = padi","A = pohon mangga, B = jagung","A = pohon rambutan, B = rumput","A = padi, B = pohon jambu"],a:3,p:"Padi berakar serabut. Pohon jambu berakar tunggang. Pilihan lain menukar jenis akarnya."},
      {lv:3,q:"Biji kacang hijau diletakkan di atas kapas basah. Beberapa hari kemudian biji berkecambah. Bagian yang pertama kali keluar dari biji dan tumbuh ke arah bawah adalah...",o:["Daun","Akar","Bunga","Buah"],a:1,p:"Saat berkecambah, akar tumbuh lebih dulu ke arah bawah agar tumbuhan dapat segera menyerap air dan berdiri kokoh."},
      {lv:3,q:"Mengapa akar tumbuhan memiliki banyak rambut akar yang sangat halus?",o:["Agar akar terlihat lebih indah","Agar tumbuhan dapat bernapas melalui bunga","Agar permukaan untuk menyerap air dan zat hara menjadi lebih luas","Agar batang tumbuhan berwarna hijau"],a:2,p:"Semakin banyak rambut akar, semakin luas bagian akar yang menyentuh tanah. Akibatnya air dan zat hara lebih banyak terserap."}
    ],
    "ipa-k3-1": [
      {lv:1,q:"Berikut ini yang termasuk benda padat adalah...",o:["Batu","Minyak goreng","Asap","Sirup"],a:0,p:"Batu memiliki bentuk dan ukuran yang tetap, ciri benda padat. Minyak dan sirup adalah benda cair, asap adalah gas."},
      {lv:1,q:"Contoh benda cair adalah...",o:["Kayu","Udara","Susu","Pensil"],a:2,p:"Susu dapat dituang dan bentuknya mengikuti wadah, ciri benda cair."},
      {lv:1,q:"Benda yang bentuknya selalu mengikuti tempatnya dan akan menyebar memenuhi seluruh ruangan adalah benda...",o:["Padat","Cair","Keras","Gas"],a:3,p:"Gas tidak memiliki bentuk tetap dan selalu menyebar memenuhi ruangan, misalnya bau minyak wangi yang menyebar ke seluruh kamar."},
      {lv:1,q:"Perubahan wujud dari padat menjadi cair disebut...",o:["Membeku","Mencair (meleleh)","Menguap","Mengembun"],a:1,p:"Mencair adalah perubahan wujud padat menjadi cair, misalnya es batu menjadi air."},
      {lv:1,q:"Perubahan wujud dari cair menjadi gas disebut...",o:["Mencair","Membeku","Menguap","Mengembun"],a:2,p:"Menguap adalah perubahan wujud cair menjadi gas, misalnya air yang dipanaskan menjadi uap."},
      {lv:1,q:"Ketika air didiamkan di dalam baskom, permukaan air akan tampak...",o:["Datar","Miring ke kanan","Bergelombang terus-menerus","Berbentuk bulat"],a:0,p:"Salah satu sifat benda cair adalah permukaannya selalu datar ketika didiamkan."},
      {lv:2,q:"Mentega yang dipanaskan di atas wajan berubah menjadi cair. Peristiwa ini disebut...",o:["Membeku","Mencair","Menyublim","Mengembun"],a:1,p:"Mentega padat menerima panas lalu berubah menjadi cair. Perubahan padat ke cair disebut mencair."},
      {lv:2,q:"Rambut basah yang dikeringkan di bawah sinar matahari lama-lama menjadi kering. Hal ini terjadi karena air di rambut...",o:["Membeku","Mengembun","Mengkristal","Menguap"],a:3,p:"Panas matahari membuat air di rambut berubah menjadi uap air dan pergi ke udara. Peristiwa ini disebut menguap."},
      {lv:2,q:"Lelehan lilin yang menetes dari lilin menyala lama-kelamaan menjadi keras kembali. Peristiwa ini disebut...",o:["Mencair","Menguap","Menyublim","Membeku"],a:3,p:"Lelehan lilin yang cair melepaskan panas lalu berubah menjadi padat. Perubahan cair ke padat disebut membeku."},
      {lv:2,q:"Kacamata Pak Joko tiba-tiba buram berembun saat ia keluar dari ruangan ber-AC ke luar ruangan yang hangat. Perubahan wujud yang terjadi adalah...",o:["Menguap (cair menjadi gas)","Mengembun (gas menjadi cair)","Membeku (cair menjadi padat)","Mencair (padat menjadi cair)"],a:1,p:"Kacamata yang dingin membuat uap air di udara hangat berubah menjadi titik-titik air. Perubahan gas menjadi cair disebut mengembun."},
      {lv:2,q:"Sebuah batu dipindahkan dari ember ke dalam kardus. Bagaimana bentuk batu tersebut sekarang?",o:["Tetap sama seperti semula","Berubah mengikuti bentuk kardus","Berubah menjadi cair","Berubah menjadi gas"],a:0,p:"Batu adalah benda padat. Bentuk benda padat tetap walaupun dipindahkan ke wadah lain."},
      {lv:2,q:"Perubahan wujud berikut yang memerlukan panas (kalor) adalah...",o:["Membeku dan mengembun","Membeku dan mengkristal","Mencair dan menguap","Mengembun dan mengkristal"],a:2,p:"Mencair dan menguap terjadi ketika benda menerima panas. Membeku, mengembun, dan mengkristal justru terjadi ketika benda melepaskan panas."},
      {lv:3,q:"Es krim yang dibiarkan di meja mencair. Jika es krim cair itu dimasukkan lagi ke dalam freezer, apa yang akan terjadi?",o:["Es krim menguap habis","Es krim membeku lagi karena panasnya dilepaskan ke freezer yang dingin","Es krim berubah menjadi gas","Es krim tetap cair selamanya"],a:1,p:"Di dalam freezer, es krim cair melepaskan panas sehingga berubah lagi menjadi padat. Perubahan wujud ini dapat berbalik."},
      {lv:3,q:"Kak Lina menjemur dua handuk basah yang sama. Handuk A dijemur di bawah terik matahari, handuk B di tempat teduh. Handuk mana yang lebih cepat kering dan mengapa?",o:["Handuk B, karena tempat teduh lebih sejuk","Keduanya kering bersamaan karena handuknya sama","Handuk B, karena air lebih cepat mengembun","Handuk A, karena panas matahari mempercepat penguapan air"],a:3,p:"Penguapan berlangsung lebih cepat bila ada panas. Handuk A mendapat panas matahari sehingga airnya lebih cepat menguap."},
      {lv:3,q:"Ibu menaruh botol minuman dingin dari kulkas di atas meja. Tidak lama kemudian bagian luar botol menjadi basah. Dari mana asal air tersebut?",o:["Dari minuman yang merembes keluar menembus botol","Dari botol yang mencair","Dari uap air di udara yang mengembun di permukaan botol yang dingin","Dari udara yang membeku di dalam botol"],a:2,p:"Udara mengandung uap air. Saat menyentuh permukaan botol yang dingin, uap air berubah menjadi titik-titik air (mengembun)."},
      {lv:3,q:"Ahmad menuang satu gelas air ke dalam mangkuk. Bagaimana bentuk dan banyaknya (volume) air sekarang?",o:["Bentuknya berubah mengikuti mangkuk, tetapi banyaknya tetap","Bentuknya tetap, tetapi banyaknya berkurang","Bentuk dan banyaknya sama-sama berubah","Bentuk dan banyaknya sama-sama tetap seperti gelas"],a:0,p:"Benda cair bentuknya mengikuti wadah, tetapi volumenya tetap. Air tetap satu gelas meski bentuknya seperti mangkuk."},
      {lv:3,q:"Cokelat batang dipanaskan sampai cair, lalu dituang ke cetakan dan didinginkan di kulkas hingga keras. Urutan perubahan wujud yang terjadi adalah...",o:["Mencair, lalu membeku","Membeku, lalu mencair","Menguap, lalu mengembun","Menyublim, lalu mengkristal"],a:0,p:"Saat dipanaskan, cokelat padat menjadi cair (mencair). Saat didinginkan, cokelat cair menjadi padat lagi (membeku)."},
      {lv:3,q:"Mengapa pakaian yang dijemur lebih cepat kering pada hari yang berangin?",o:["Angin membuat air di pakaian membeku","Angin menambah air ke pakaian","Angin mengubah air menjadi padat","Angin membawa pergi uap air sehingga penguapan berlangsung lebih cepat"],a:3,p:"Angin memindahkan uap air dari sekitar pakaian, sehingga air di pakaian lebih mudah menguap dan pakaian cepat kering."},
      {lv:3,q:"Balon yang ditiup mengembang dan udaranya mengikuti bentuk balon. Saat balon ditusuk jarum, udaranya keluar dan menyebar ke seluruh ruangan. Sifat gas yang ditunjukkan adalah...",o:["Gas memiliki bentuk yang tetap","Bentuk dan volume gas selalu mengikuti tempatnya","Gas memiliki volume yang tetap","Gas tidak memerlukan ruang"],a:1,p:"Gas tidak memiliki bentuk dan volume tetap. Gas mengisi bentuk balon, lalu menyebar memenuhi ruangan setelah keluar."},
      {lv:3,q:"Perhatikan peristiwa berikut: (1) es mencair, (2) air dimasak hingga mendidih, (3) embun di daun pada pagi hari, (4) air dimasukkan ke freezer. Peristiwa yang menyerap panas ditunjukkan oleh nomor...",o:["(3) dan (4)","(1) dan (4)","(1) dan (2)","(2) dan (3)"],a:2,p:"Mencair (1) dan menguap saat mendidih (2) membutuhkan panas. Mengembun (3) dan membeku (4) justru melepaskan panas."}
    ],
    "ipa-k3-2": [
      {lv:1,q:"Contoh kegiatan yang menggunakan gaya tarik adalah...",o:["Menimba air dari sumur","Menendang bola","Menutup laci","Mendorong gerobak"],a:0,p:"Saat menimba, kita menarik tali ke arah tubuh kita. Itu adalah gaya tarik."},
      {lv:1,q:"Contoh kegiatan yang menggunakan gaya dorong adalah...",o:["Menarik tali layang-layang","Mencabut rumput","Mendorong gerobak sampah","Membuka laci"],a:2,p:"Mendorong berarti memberi gaya menjauhi tubuh kita, seperti mendorong gerobak ke depan."},
      {lv:1,q:"Gaya yang berasal dari tenaga otot tubuh kita disebut gaya...",o:["Magnet","Listrik","Gravitasi","Otot"],a:3,p:"Saat mengangkat tas atau mendorong kursi, kita memakai tenaga otot. Gaya ini disebut gaya otot."},
      {lv:1,q:"Buah yang terlepas dari tangkainya akan jatuh ke bawah. Hal ini disebabkan oleh gaya...",o:["Otot","Gravitasi (tarikan bumi)","Magnet","Pegas"],a:1,p:"Bumi menarik semua benda ke arah bawah. Tarikan ini disebut gaya gravitasi."},
      {lv:1,q:"Magnet dapat menarik benda yang terbuat dari...",o:["Kertas","Kayu","Besi","Plastik"],a:2,p:"Magnet menarik benda dari besi dan baja. Kertas, kayu, dan plastik tidak ditarik magnet."},
      {lv:1,q:"Salah satu pengaruh gaya adalah dapat mengubah bentuk benda. Contohnya adalah...",o:["Plastisin yang ditekan menjadi pipih","Lampu yang menyala","Air yang mendidih","Matahari yang terbit"],a:0,p:"Plastisin berubah bentuk karena mendapat tekanan dari tangan. Itu menunjukkan gaya dapat mengubah bentuk benda."},
      {lv:2,q:"Saat bermain ayunan, Dinda didorong temannya dari belakang. Ayunan bergerak ke depan karena...",o:["Mendapat gaya magnet","Mendapat gaya dorong","Tidak mendapat gaya apa pun","Mendapat gaya tarik dari depan"],a:1,p:"Teman Dinda mendorong ayunan dari belakang. Gaya dorong itu membuat ayunan bergerak ke depan."},
      {lv:2,q:"Bola yang menggelinding di rumput cepat berhenti, sedangkan di lantai licin menggelinding lebih jauh. Hal ini karena...",o:["Rumput mendorong bola maju","Gaya gesek di lantai licin lebih besar","Bola menjadi lebih ringan di lantai","Gaya gesek di rumput lebih besar"],a:3,p:"Permukaan rumput kasar sehingga gaya geseknya besar dan cepat menghentikan bola. Lantai licin gaya geseknya kecil."},
      {lv:2,q:"Raka menekan bola karet dengan kedua tangannya sehingga bola menjadi pipih. Peristiwa ini menunjukkan bahwa gaya dapat...",o:["Mengubah warna benda","Mengubah benda menjadi cair","Membuat benda menghilang","Mengubah bentuk benda"],a:3,p:"Bola karet berubah bentuk karena ditekan. Jadi, gaya dapat mengubah bentuk benda."},
      {lv:2,q:"Perhatikan kegiatan berikut: (1) menarik tali timba, (2) menendang bola, (3) mencabut singkong, (4) memukul bedug. Kegiatan yang memakai gaya tarik ditunjukkan oleh nomor...",o:["(2) dan (4)","(1) dan (3)","(1) dan (2)","(3) dan (4)"],a:1,p:"Menarik tali timba dan mencabut singkong sama-sama menarik benda ke arah kita. Menendang dan memukul termasuk gaya dorong."},
      {lv:2,q:"Tali busur ditarik lalu dilepas sehingga anak panah melesat. Gaya yang membuat busur kembali ke bentuk semula dan mendorong anak panah adalah gaya...",o:["Pegas (lenting)","Magnet","Gesek","Listrik"],a:0,p:"Busur yang ditarik akan berusaha kembali ke bentuk semula. Gaya ini disebut gaya pegas atau gaya lenting."},
      {lv:2,q:"Mobil mainan yang didorong pelan bergerak lambat. Jika mobil mainan yang sama didorong lebih kuat, mobil itu akan bergerak...",o:["Lebih lambat","Tetap diam","Lebih cepat","Mundur ke belakang"],a:2,p:"Semakin besar gaya dorong yang diberikan, semakin cepat benda bergerak."},
      {lv:3,q:"Doni mendorong lemari besar, tetapi lemari tidak bergerak. Lalu Doni dan ayahnya mendorong bersama ke arah yang sama, dan lemari bergeser. Mengapa hal ini terjadi?",o:["Lemari menjadi lebih ringan","Gaya dorong mereka berdua bergabung sehingga menjadi lebih besar","Gaya dorong mereka menjadi lebih kecil","Lantai tiba-tiba menjadi licin"],a:1,p:"Dua gaya yang searah akan saling menambah. Gaya gabungan yang lebih besar mampu menggeser lemari."},
      {lv:3,q:"Pemain bulu tangkis memukul kok yang datang ke arahnya sehingga kok berbalik arah dan melaju cepat. Gaya pukulan raket menyebabkan kok...",o:["Berubah warna","Berubah menjadi benda cair","Berhenti dan diam di udara","Berubah arah dan kecepatan geraknya"],a:3,p:"Kok yang semula datang berbalik arah dan bergerak lebih cepat. Jadi gaya dapat mengubah arah sekaligus kecepatan benda."},
      {lv:3,q:"Sepeda lebih mudah dikayuh di jalan aspal yang mulus daripada di jalan berpasir. Penyebabnya adalah...",o:["Jalan aspal mendorong sepeda ke depan","Pasir menarik sepeda ke depan","Gaya gesek di jalan berpasir lebih besar sehingga lebih menghambat gerak","Sepeda lebih ringan di jalan berpasir"],a:2,p:"Pasir membuat permukaan lebih kasar dan menahan roda. Gaya gesek yang besar ini menghambat gerak sepeda."},
      {lv:3,q:"Mengapa telapak sandal dan ban sepeda dibuat beralur atau bergerigi?",o:["Agar gaya gesek bertambah sehingga tidak mudah tergelincir","Agar menjadi lebih licin","Agar menjadi lebih ringan","Agar cepat rusak"],a:0,p:"Alur memperbesar gesekan dengan tanah. Gesekan ini membuat sandal dan ban mencengkeram jalan sehingga kita tidak mudah terpeleset."},
      {lv:3,q:"Paku-paku kecil terjatuh dan bercampur dengan pasir. Cara paling mudah untuk memisahkan paku dari pasir adalah...",o:["Menggunakan magnet","Menyiramnya dengan air","Meniupnya dengan kipas angin","Menyapunya dengan sapu basah"],a:0,p:"Magnet menarik paku yang terbuat dari besi, tetapi tidak menarik pasir. Paku pun terpisah dengan mudah."},
      {lv:3,q:"Buah kelapa tua jatuh dari pohonnya ke tanah. Gaya yang menyebabkan kelapa jatuh dan arah gayanya adalah...",o:["Gaya magnet, arahnya ke atas","Gaya otot, arahnya ke samping","Gaya pegas, arahnya ke atas","Gaya gravitasi, arahnya ke bawah"],a:3,p:"Bumi menarik kelapa ke arah bawah. Tarikan bumi ini disebut gaya gravitasi."},
      {lv:3,q:"Dua magnet batang didekatkan, ternyata keduanya saling menjauh. Kesimpulan yang tepat adalah...",o:["Kutub magnet yang berdekatan adalah kutub yang berbeda","Kutub magnet yang berdekatan adalah kutub yang sejenis","Salah satu benda bukan magnet","Magnet kehilangan gaya tariknya"],a:1,p:"Kutub magnet yang sejenis saling tolak-menolak, sedangkan kutub yang berbeda saling tarik-menarik."},
      {lv:3,q:"Pada lomba tarik tambang, regu merah menarik lebih kuat daripada regu biru. Tali tambang akan bergerak...",o:["Ke arah regu biru","Tidak bergerak sama sekali","Ke arah regu merah","Ke atas"],a:2,p:"Jika gaya tarik tidak seimbang, benda bergerak ke arah gaya yang lebih besar, yaitu ke arah regu merah."}
    ],
    "ipa-k4-0": [
      {lv:1,q:"Tahap pertama dalam siklus hidup kupu-kupu adalah...",o:["Telur","Ulat","Kepompong","Kupu-kupu dewasa"],a:0,p:"Kupu-kupu betina bertelur di daun. Siklus hidupnya dimulai dari telur, lalu ulat, kepompong, dan kupu-kupu dewasa."},
      {lv:1,q:"Larva nyamuk yang hidup di air sering disebut...",o:["Berudu","Nimfa","Jentik-jentik","Belatung"],a:2,p:"Larva nyamuk disebut jentik-jentik. Jentik hidup di air yang tergenang."},
      {lv:1,q:"Hewan berikut yang mengalami metamorfosis tidak sempurna adalah...",o:["Kupu-kupu","Nyamuk","Lalat","Belalang"],a:3,p:"Belalang melalui tahap telur, nimfa, dan dewasa tanpa kepompong. Itulah metamorfosis tidak sempurna."},
      {lv:1,q:"Tahapan metamorfosis tidak sempurna adalah...",o:["Telur - larva - pupa - dewasa","Telur - nimfa - dewasa","Telur - kepompong - dewasa","Larva - pupa - dewasa"],a:1,p:"Metamorfosis tidak sempurna hanya memiliki tiga tahap: telur, nimfa, dan dewasa."},
      {lv:1,q:"Perubahan bentuk tubuh hewan secara bertahap dari kecil hingga dewasa disebut...",o:["Fotosintesis","Respirasi","Metamorfosis","Penyerbukan"],a:2,p:"Metamorfosis adalah perubahan bentuk tubuh hewan secara bertahap selama hidupnya."},
      {lv:1,q:"Hewan yang tidak mengalami metamorfosis karena anaknya sudah mirip induknya sejak lahir adalah...",o:["Kucing","Katak","Kupu-kupu","Nyamuk"],a:0,p:"Anak kucing sudah mirip induknya sejak lahir dan hanya bertambah besar. Kucing tidak mengalami metamorfosis."},
      {lv:2,q:"Urutan siklus hidup katak yang benar adalah...",o:["Telur - katak muda - berudu - katak dewasa","Telur - berudu - katak muda - katak dewasa","Berudu - telur - katak dewasa - katak muda","Telur - nimfa - katak dewasa - berudu"],a:1,p:"Telur katak menetas menjadi berudu, lalu tumbuh kaki menjadi katak muda, kemudian menjadi katak dewasa."},
      {lv:2,q:"Kupu-kupu dapat merugikan petani sayur karena memakan daun tanaman. Pada tahap apakah hal itu terjadi?",o:["Telur","Pupa (kepompong)","Kupu-kupu dewasa","Larva (ulat)"],a:3,p:"Pada tahap ulat, kupu-kupu sangat banyak makan daun. Kupu-kupu dewasa hanya mengisap nektar bunga."},
      {lv:2,q:"Lalat mengalami metamorfosis sempurna. Larva lalat yang biasa ditemukan pada sampah atau makanan busuk disebut...",o:["Jentik","Nimfa","Berudu","Belatung"],a:3,p:"Larva lalat disebut belatung. Belatung kemudian menjadi pupa sebelum menjadi lalat dewasa."},
      {lv:2,q:"Selama berada di tahap pupa (kepompong), calon kupu-kupu...",o:["Makan daun sebanyak-banyaknya","Tidak makan dan tidak banyak bergerak","Bertelur di daun","Terbang mencari nektar"],a:1,p:"Pada tahap pupa, hewan tidak makan dan hampir tidak bergerak. Di dalamnya terjadi pembentukan tubuh baru."},
      {lv:2,q:"Kelompok hewan berikut yang semuanya mengalami metamorfosis tidak sempurna adalah...",o:["Belalang, jangkrik, capung","Kupu-kupu, nyamuk, lalat","Katak, kupu-kupu, belalang","Nyamuk, jangkrik, lalat"],a:0,p:"Belalang, jangkrik, dan capung tidak memiliki tahap kepompong. Kupu-kupu, nyamuk, dan lalat mengalami metamorfosis sempurna."},
      {lv:2,q:"Pada siklus hidup nyamuk, setelah tahap jentik (larva), nyamuk akan memasuki tahap...",o:["Telur","Nimfa","Pupa","Berudu"],a:2,p:"Urutan siklus hidup nyamuk adalah telur, jentik (larva), pupa, lalu nyamuk dewasa."},
      {lv:3,q:"Untuk mencegah demam berdarah, warga menguras bak mandi seminggu sekali. Mengapa cara ini efektif?",o:["Membunuh semua nyamuk dewasa yang sedang terbang","Memutus siklus hidup nyamuk dengan membuang telur dan jentik sebelum menjadi dewasa","Membuat air bak menjadi lebih dingin","Mengusir kupu-kupu dari rumah"],a:1,p:"Telur dan jentik nyamuk hidup di air. Jika air dikuras secara rutin, jentik tidak sempat menjadi nyamuk dewasa."},
      {lv:3,q:"Dimas mengamati hewan muda yang bentuknya mirip induknya, sayapnya belum sempurna, dan beberapa kali berganti kulit. Hewan muda tersebut berada pada tahap...",o:["Larva","Pupa","Telur","Nimfa"],a:3,p:"Hewan muda yang mirip induk dengan sayap belum sempurna adalah nimfa, tahap pada metamorfosis tidak sempurna."},
      {lv:3,q:"Perbedaan utama antara metamorfosis sempurna dan metamorfosis tidak sempurna adalah...",o:["Metamorfosis tidak sempurna memiliki tahap pupa, sedangkan metamorfosis sempurna tidak","Keduanya sama-sama memiliki tahap nimfa","Metamorfosis sempurna memiliki tahap pupa, sedangkan metamorfosis tidak sempurna tidak","Metamorfosis sempurna tidak dimulai dari telur"],a:2,p:"Metamorfosis sempurna: telur, larva, pupa, dewasa. Metamorfosis tidak sempurna: telur, nimfa, dewasa tanpa pupa."},
      {lv:3,q:"Berudu bernapas dengan insang, sedangkan katak dewasa bernapas dengan paru-paru dan kulit. Perubahan alat pernapasan ini berhubungan dengan...",o:["Berudu hidup di air, sedangkan katak dewasa dapat hidup di darat","Berudu hidup di darat, sedangkan katak dewasa hidup di udara","Katak dewasa hanya dapat hidup di dalam air","Insang berudu berubah menjadi sayap"],a:0,p:"Insang cocok untuk mengambil oksigen di air. Paru-paru dan kulit memungkinkan katak dewasa bernapas di darat."},
      {lv:3,q:"Nimfa belalang beberapa kali berganti kulit sebelum menjadi dewasa. Mengapa hal ini perlu terjadi?",o:["Kulit luarnya keras dan tidak ikut membesar ketika tubuhnya tumbuh","Agar warnanya berubah menjadi merah","Agar dapat bernapas di dalam air","Karena kulitnya dimakan semut"],a:0,p:"Kulit luar serangga keras dan kaku. Supaya tubuhnya bisa bertambah besar, nimfa harus melepas kulit lama dan membentuk kulit baru."},
      {lv:3,q:"Ulat sutra membuat kokon (kepompong) dari benang yang sangat halus. Manusia memanfaatkan tahap ini dalam siklus hidup ulat sutra untuk...",o:["Mengambil madu dari kokon","Mengambil telur untuk makanan","Membuat pupuk kompos","Mengambil benang sutra dari kokon"],a:3,p:"Kokon ulat sutra tersusun dari benang halus. Benang ini dipintal menjadi kain sutra."},
      {lv:3,q:"Pak Wayan menemukan banyak ulat di kebun kubisnya. Tanpa memakai racun, ia membiarkan burung pemakan ulat datang ke kebun. Cara ini bekerja karena...",o:["Burung mengubah ulat menjadi belalang","Burung memakan ulat sehingga lebih sedikit ulat yang tumbuh menjadi kupu-kupu dan bertelur lagi","Burung membuat ulat langsung menjadi kupu-kupu","Burung memakan daun kubis yang rusak"],a:1,p:"Jika ulat dimakan burung, jumlah ulat yang sempat menjadi kupu-kupu dan bertelur berkurang. Jumlah ulat pun terkendali secara alami."},
      {lv:3,q:"Pada suatu kolam, telur-telur katak rusak sehingga tidak ada yang menetas. Apa akibatnya bagi kolam tersebut di musim itu?",o:["Telur langsung berubah menjadi katak dewasa","Telur berubah menjadi ikan","Tidak akan ada berudu dan katak muda baru dari telur-telur tersebut","Jumlah katak dewasa bertambah banyak"],a:2,p:"Setiap tahap siklus hidup bergantung pada tahap sebelumnya. Jika telur tidak menetas, tidak akan muncul berudu maupun katak baru."}
    ],
    "ipa-k4-1": [
      {lv:1,q:"Energi yang dimiliki oleh benda yang sedang bergerak disebut energi...",o:["Gerak (kinetik)","Kimia","Cahaya","Bunyi"],a:0,p:"Benda yang bergerak, seperti bola menggelinding, memiliki energi gerak atau energi kinetik."},
      {lv:1,q:"Lampu yang menyala mengubah energi listrik terutama menjadi energi...",o:["Bunyi","Gerak","Cahaya","Kimia"],a:2,p:"Lampu menerima energi listrik lalu mengubahnya menjadi cahaya agar ruangan terang."},
      {lv:1,q:"Contoh sumber energi yang tidak dapat diperbarui adalah...",o:["Sinar matahari","Angin","Air sungai","Minyak bumi"],a:3,p:"Minyak bumi terbentuk selama jutaan tahun dan bisa habis. Sinar matahari, angin, dan air dapat diperbarui."},
      {lv:1,q:"Baterai menyimpan energi dalam bentuk energi...",o:["Bunyi","Kimia","Cahaya","Gerak"],a:1,p:"Di dalam baterai terdapat zat kimia yang menyimpan energi. Energi ini diubah menjadi listrik saat baterai dipakai."},
      {lv:1,q:"Bel listrik sekolah yang ditekan mengubah energi listrik terutama menjadi energi...",o:["Kimia","Cahaya","Bunyi","Gerak"],a:2,p:"Bel listrik berbunyi saat dialiri listrik. Jadi energi listrik berubah menjadi energi bunyi."},
      {lv:1,q:"Energi tidak dapat diciptakan dan tidak dapat dimusnahkan. Energi hanya dapat...",o:["Berubah bentuk","Hilang begitu saja","Bertambah dengan sendirinya","Dibuat dari tidak ada"],a:0,p:"Energi selalu berubah dari satu bentuk ke bentuk lain, misalnya listrik menjadi cahaya, tetapi jumlahnya tidak hilang."},
      {lv:2,q:"Saat kedua telapak tangan digosok-gosokkan dengan cepat, tangan terasa hangat. Perubahan energi yang terjadi adalah...",o:["Energi panas menjadi energi gerak","Energi gerak menjadi energi panas","Energi cahaya menjadi energi bunyi","Energi listrik menjadi energi kimia"],a:1,p:"Gerakan menggosok menimbulkan gesekan. Gesekan mengubah energi gerak menjadi energi panas."},
      {lv:2,q:"Kompor gas yang menyala mengubah energi kimia dalam gas menjadi energi...",o:["Listrik","Gerak","Bunyi","Panas"],a:3,p:"Gas yang terbakar menghasilkan api. Api memberi panas untuk memasak, jadi energi kimia berubah menjadi energi panas."},
      {lv:2,q:"Ketika blender dinyalakan, pisau di dalamnya berputar. Energi listrik berubah menjadi energi...",o:["Kimia","Cahaya","Bunyi saja","Gerak"],a:3,p:"Putaran pisau blender menunjukkan energi listrik berubah menjadi energi gerak."},
      {lv:2,q:"Kelompok sumber energi yang dapat diperbarui adalah...",o:["Batu bara dan minyak bumi","Sinar matahari dan angin","Gas alam dan batu bara","Minyak bumi dan gas alam"],a:1,p:"Sinar matahari dan angin selalu tersedia di alam dan tidak habis. Batu bara, minyak bumi, dan gas alam dapat habis."},
      {lv:2,q:"Televisi yang sedang menyala mengubah energi listrik menjadi energi...",o:["Cahaya dan bunyi","Kimia dan gerak","Gerak saja","Kimia saja"],a:0,p:"Televisi menampilkan gambar (cahaya) dan mengeluarkan suara (bunyi)."},
      {lv:2,q:"Tumbuhan hijau mengubah energi cahaya matahari menjadi energi yang tersimpan di dalam makanan. Energi tersebut berbentuk energi...",o:["Listrik","Bunyi","Kimia","Gerak"],a:2,p:"Melalui fotosintesis, energi cahaya disimpan dalam makanan (gula dan zat tepung) sebagai energi kimia."},
      {lv:3,q:"Mengapa kita sebaiknya menghemat penggunaan bahan bakar minyak?",o:["Minyak bumi dapat diperbarui setiap hari","Minyak bumi tidak dapat diperbarui dan membutuhkan jutaan tahun untuk terbentuk","Minyak bumi berasal langsung dari sinar matahari","Minyak bumi tidak menghasilkan energi"],a:1,p:"Minyak bumi terbentuk dari sisa makhluk hidup selama jutaan tahun. Jika dipakai boros, persediaannya akan habis."},
      {lv:3,q:"Pada pembangkit listrik tenaga angin, urutan perubahan energi yang terjadi adalah...",o:["Energi listrik - energi gerak kincir - energi angin","Energi kimia - energi listrik - energi angin","Energi cahaya - energi bunyi - energi listrik","Energi gerak angin - energi gerak kincir - energi listrik"],a:3,p:"Angin yang bergerak memutar kincir. Putaran kincir menggerakkan generator yang menghasilkan listrik."},
      {lv:3,q:"Rizki makan pagi, lalu bersepeda ke sekolah. Urutan perubahan energi yang paling tepat adalah...",o:["Energi gerak - energi kimia dari makanan","Energi listrik - energi gerak sepeda","Energi kimia dari makanan - energi gerak otot dan sepeda","Energi cahaya - energi kimia sepeda"],a:2,p:"Makanan menyimpan energi kimia. Tubuh mengubahnya menjadi energi gerak otot untuk mengayuh sepeda."},
      {lv:3,q:"Lampu pijar terasa panas jika disentuh setelah menyala lama. Hal ini menunjukkan bahwa...",o:["Sebagian energi listrik berubah menjadi panas, tidak semuanya menjadi cahaya","Lampu menghasilkan energi dari udara","Energi cahaya berubah menjadi energi listrik","Lampu menyerap panas dari tangan kita"],a:0,p:"Lampu pijar mengubah energi listrik menjadi cahaya dan juga panas. Panas inilah yang terasa saat lampu disentuh."},
      {lv:3,q:"Di rumah, ibu menyalakan kipas angin lalu memasak nasi dengan rice cooker. Perubahan energi utama pada kedua alat itu secara berturut-turut adalah...",o:["Listrik menjadi gerak; listrik menjadi panas","Listrik menjadi panas; listrik menjadi gerak","Kimia menjadi gerak; listrik menjadi cahaya","Listrik menjadi bunyi; kimia menjadi panas"],a:0,p:"Kipas angin memutar baling-baling (gerak). Rice cooker memanaskan beras (panas). Keduanya memakai energi listrik."},
      {lv:3,q:"Mengapa karet ketapel yang ditarik lebih jauh dapat melontarkan kerikil lebih jauh?",o:["Kerikil menjadi lebih ringan","Karet menjadi lebih pendek","Udara di sekitar mendorong kerikil","Karet yang ditarik lebih jauh menyimpan energi lebih besar yang kemudian berubah menjadi energi gerak kerikil"],a:3,p:"Karet yang diregangkan menyimpan energi. Semakin jauh ditarik, semakin besar energinya sehingga kerikil bergerak lebih cepat dan jauh."},
      {lv:3,q:"Cara menghemat energi listrik di rumah yang paling tepat adalah...",o:["Menyalakan televisi sambil tidur","Mematikan lampu dan alat listrik ketika tidak dipakai","Membiarkan pintu kulkas terbuka lama","Menyalakan lampu di siang hari yang terang"],a:1,p:"Alat listrik yang tidak dipakai tetapi menyala hanya membuang energi. Mematikannya berarti menghemat listrik."},
      {lv:3,q:"Air terjun yang tinggi dapat menghasilkan listrik lebih besar di PLTA daripada air terjun yang rendah. Mengapa?",o:["Air dari tempat tinggi lebih dingin","Air dari tempat tinggi lebih bersih","Air yang jatuh dari tempat lebih tinggi memiliki energi lebih besar sehingga memutar turbin lebih kuat","Air terjun tinggi airnya lebih sedikit"],a:2,p:"Semakin tinggi tempat jatuhnya air, semakin besar energi gerak air saat sampai di bawah. Turbin berputar lebih kuat dan listrik yang dihasilkan lebih besar."}
    ],
    "ipa-k4-2": [
      {lv:1,q:"Benda berikut yang merupakan sumber bunyi adalah...",o:["Gendang yang sedang dipukul","Batu yang diam","Buku di atas rak","Meja yang kosong"],a:0,p:"Bunyi berasal dari benda yang bergetar. Gendang yang dipukul bergetar sehingga menghasilkan bunyi."},
      {lv:1,q:"Bunyi dapat merambat melalui zat padat, zat cair, dan...",o:["Ruang hampa","Bayangan","Zat gas","Cahaya"],a:2,p:"Bunyi membutuhkan perantara untuk merambat, yaitu zat padat, cair, atau gas seperti udara."},
      {lv:1,q:"Alat indra yang kita gunakan untuk mendengar bunyi adalah...",o:["Mata","Hidung","Lidah","Telinga"],a:3,p:"Telinga menangkap getaran bunyi dari udara lalu mengirimkan pesan ke otak."},
      {lv:1,q:"Alat musik yang bunyinya berasal dari senar yang bergetar adalah...",o:["Seruling","Gitar","Gendang","Terompet"],a:1,p:"Gitar berbunyi karena senarnya dipetik dan bergetar. Seruling dan terompet ditiup, gendang dipukul."},
      {lv:1,q:"Saat kita berbicara atau bernyanyi, bunyi suara kita berasal dari getaran...",o:["Gigi","Rambut","Pita suara","Hidung"],a:2,p:"Udara dari paru-paru menggetarkan pita suara di tenggorokan sehingga muncul suara."},
      {lv:1,q:"Benda berikut yang dapat meredam atau menyerap bunyi adalah...",o:["Karpet tebal","Kaca","Keramik","Besi"],a:0,p:"Benda lunak dan tebal seperti karpet menyerap bunyi. Benda keras seperti kaca dan keramik memantulkan bunyi."},
      {lv:2,q:"Lala menempelkan telinganya di ujung meja, lalu temannya mengetuk ujung meja yang lain. Bunyi ketukan terdengar lebih jelas. Hal ini karena...",o:["Bunyi tidak dapat merambat melalui udara","Bunyi merambat lebih baik melalui zat padat","Meja menghasilkan bunyi sendiri","Telinga tidak bisa mendengar melalui udara"],a:1,p:"Partikel zat padat lebih rapat sehingga getaran bunyi merambat lebih baik daripada melalui udara."},
      {lv:2,q:"Seruling menghasilkan bunyi ketika ditiup. Bagian yang bergetar pada seruling adalah...",o:["Lubang-lubang seruling","Jari peniup","Tali pengikat seruling","Udara di dalam seruling"],a:3,p:"Tiupan membuat udara di dalam seruling bergetar. Getaran udara itulah yang menghasilkan bunyi."},
      {lv:2,q:"Saat hujan badai, kita melihat kilat lebih dahulu, kemudian baru mendengar suara guntur. Hal ini terjadi karena...",o:["Bunyi merambat lebih cepat daripada cahaya","Guntur terjadi lebih dahulu daripada kilat","Telinga bekerja lebih cepat daripada mata","Cahaya merambat jauh lebih cepat daripada bunyi"],a:3,p:"Kilat dan guntur terjadi bersamaan, tetapi cahaya jauh lebih cepat sampai ke mata dibanding bunyi ke telinga."},
      {lv:2,q:"Senar gitar yang dipetik berbunyi. Ketika senar langsung dipegang erat dengan jari, bunyinya berhenti. Mengapa?",o:["Senar menjadi lebih panjang","Getaran senar berhenti","Udara di sekitar gitar hilang","Jari mengeluarkan bunyi lain"],a:1,p:"Bunyi muncul karena senar bergetar. Ketika senar dipegang, getarannya berhenti sehingga bunyinya pun hilang."},
      {lv:2,q:"Hewan yang memanfaatkan pantulan bunyi untuk terbang dan mencari makan di tempat gelap adalah...",o:["Kelelawar","Kucing","Ayam","Sapi"],a:0,p:"Kelelawar mengeluarkan bunyi tinggi lalu mendengarkan pantulannya. Dari pantulan itu kelelawar tahu letak benda di sekitarnya."},
      {lv:2,q:"Ketika gendang dipukul lebih keras, bunyi yang dihasilkan menjadi...",o:["Lebih pelan","Hilang sama sekali","Lebih keras (nyaring)","Sama saja"],a:2,p:"Pukulan yang lebih keras membuat getaran gendang lebih besar, sehingga bunyinya lebih keras."},
      {lv:3,q:"Bel listrik dinyalakan di dalam toples kaca tertutup. Lalu udara di dalam toples dipompa keluar sedikit demi sedikit. Apa yang akan terdengar?",o:["Bunyi bel makin keras","Bunyi bel makin pelan hingga hampir tidak terdengar","Bunyi bel tetap sama kerasnya","Bel berhenti bergetar"],a:1,p:"Bel tetap bergetar, tetapi udara sebagai perantara bunyi makin sedikit. Akibatnya bunyi yang sampai ke telinga makin lemah."},
      {lv:3,q:"Kapal nelayan memakai alat yang memancarkan bunyi ke dalam laut lalu menangkap pantulannya untuk mengetahui letak gerombolan ikan. Prinsip yang digunakan alat tersebut adalah...",o:["Penyerapan bunyi","Perubahan bunyi menjadi cahaya","Perambatan bunyi di ruang hampa","Pemantulan bunyi"],a:3,p:"Bunyi yang mengenai gerombolan ikan akan dipantulkan kembali. Dari waktu pantulan, nelayan dapat mengetahui letak ikan."},
      {lv:3,q:"Mengapa gema mudah terdengar di gua yang sangat besar, tetapi tidak terdengar di kamar kecil?",o:["Gua tidak memiliki dinding","Kamar kecil tidak berisi udara","Dinding gua jauh sehingga pantulan bunyi terdengar terpisah setelah bunyi asli selesai","Bunyi tidak dapat dipantulkan oleh dinding gua"],a:2,p:"Di kamar kecil pantulan datang hampir bersamaan dengan bunyi asli. Di gua besar pantulan butuh waktu lebih lama sehingga terdengar sebagai gema."},
      {lv:3,q:"Telepon kaleng tidak dapat menghantarkan suara dengan baik jika benangnya kendur. Mengapa demikian?",o:["Getaran bunyi tidak dapat merambat dengan baik melalui benang yang kendur","Kaleng menjadi terlalu berat","Bunyi berubah menjadi cahaya","Benang menyerap udara di dalam kaleng"],a:0,p:"Getaran suara merambat melalui benang yang tegang. Jika benang kendur, getaran melemah sebelum sampai ke kaleng lain."},
      {lv:3,q:"Petugas rel dapat mengetahui kereta yang masih jauh dengan alat pendengar yang ditempelkan pada rel, sebelum suara kereta terdengar lewat udara. Hal ini karena...",o:["Bunyi merambat lebih cepat melalui besi rel (zat padat) daripada melalui udara","Bunyi merambat lebih cepat melalui udara","Rel besi menghasilkan bunyi sendiri","Udara tidak dapat merambatkan bunyi"],a:0,p:"Bunyi merambat paling cepat di zat padat. Getaran kereta pada rel besi sampai lebih dulu daripada bunyi yang melewati udara."},
      {lv:3,q:"Perhatikan alat musik berikut: (1) gitar dipetik, (2) bedug dipukul, (3) seruling ditiup, (4) biola digesek. Alat musik yang sumber getarannya berupa senar ditunjukkan oleh nomor...",o:["(2) dan (3)","(1) dan (2)","(3) dan (4)","(1) dan (4)"],a:3,p:"Gitar dan biola memiliki senar yang bergetar. Bedug bergetar pada kulitnya, seruling pada udara di dalamnya."},
      {lv:3,q:"Ketika kedua telinga ditutup rapat dengan telapak tangan, bunyi di sekitar terdengar lebih pelan. Penjelasan yang tepat adalah...",o:["Tangan membuat sumber bunyi berhenti bergetar","Tangan menghalangi dan meredam getaran bunyi sebelum masuk ke telinga","Tangan mengubah bunyi menjadi panas sepenuhnya","Tangan menambah udara di dalam telinga"],a:1,p:"Sumber bunyi tetap bergetar. Tangan hanya menghalangi sebagian getaran bunyi sehingga yang sampai ke telinga lebih lemah."},
      {lv:3,q:"Penjual es keliling membunyikan lonceng. Ana yang berada di dalam rumah dengan pintu tertutup tetap dapat mendengar bunyi lonceng itu. Hal ini menunjukkan bahwa bunyi dapat...",o:["Merambat hanya melalui ruang hampa","Hanya terdengar jika tidak ada penghalang","Merambat melalui udara dan benda padat seperti pintu atau dinding","Berubah menjadi cahaya agar dapat masuk rumah"],a:2,p:"Bunyi merambat melalui udara, lalu menggetarkan pintu dan dinding (zat padat), dan getaran itu diteruskan ke udara di dalam rumah."}
    ],
    "ipa-k5-0": [
      {lv:1,q:"Gas dari udara yang dibutuhkan tubuh kita ketika menghirup napas adalah...",o:["Oksigen","Karbon dioksida","Asap","Uap air"],a:0,p:"Tubuh memerlukan oksigen untuk mengolah makanan menjadi energi."},
      {lv:1,q:"Organ utama dalam sistem pernapasan manusia adalah...",o:["Lambung","Ginjal","Paru-paru","Hati"],a:2,p:"Paru-paru adalah tempat pertukaran oksigen dan karbon dioksida."},
      {lv:1,q:"Batang tenggorokan bercabang dua menuju paru-paru kanan dan paru-paru kiri. Cabang ini disebut...",o:["Alveolus","Faring","Laring","Bronkus"],a:3,p:"Ujung bawah trakea bercabang menjadi dua bronkus, masing-masing menuju satu paru-paru."},
      {lv:1,q:"Proses menghirup udara ke dalam paru-paru disebut...",o:["Ekspirasi","Inspirasi","Ekskresi","Pencernaan"],a:1,p:"Inspirasi berarti menarik napas atau memasukkan udara. Ekspirasi berarti mengembuskan napas."},
      {lv:1,q:"Pangkal tenggorokan yang di dalamnya terdapat pita suara disebut...",o:["Trakea","Bronkus","Laring","Bronkiolus"],a:2,p:"Laring terletak di antara faring dan trakea. Di dalamnya ada pita suara yang menghasilkan suara."},
      {lv:1,q:"Otot berbentuk kubah yang membatasi rongga dada dan rongga perut disebut...",o:["Diafragma","Otot lengan","Otot jantung","Otot betis"],a:0,p:"Diafragma adalah sekat otot di bawah paru-paru yang membantu proses bernapas."},
      {lv:2,q:"Mengapa kita sebaiknya bernapas melalui hidung dan bukan melalui mulut?",o:["Mulut tidak dapat dilalui udara","Hidung dapat menyaring, menghangatkan, dan melembapkan udara","Hidung menghasilkan oksigen sendiri","Mulut menyaring debu lebih baik"],a:1,p:"Di hidung ada rambut halus dan selaput lendir yang menyaring debu serta membuat udara hangat dan lembap sebelum masuk paru-paru."},
      {lv:2,q:"Pernapasan dada terjadi karena kerja otot...",o:["Diafragma","Perut","Jantung","Antartulang rusuk"],a:3,p:"Pada pernapasan dada, otot di antara tulang rusuk bergerak mengangkat dan menurunkan tulang rusuk."},
      {lv:2,q:"Ketika kita menghirup napas, keadaan rongga dada adalah...",o:["Mengecil sehingga udara masuk","Mengecil sehingga udara keluar","Tidak berubah sama sekali","Membesar sehingga udara masuk"],a:3,p:"Saat rongga dada membesar, tekanan udara di paru-paru turun sehingga udara dari luar masuk."},
      {lv:2,q:"Penyakit pernapasan yang disebabkan oleh bakteri dan dapat menular melalui percikan batuk adalah...",o:["Maag","TBC (tuberkulosis)","Diare","Sariawan"],a:1,p:"TBC disebabkan bakteri yang menyerang paru-paru dan dapat menular lewat percikan ludah saat batuk atau bersin."},
      {lv:2,q:"Asap rokok mengandung banyak zat berbahaya. Organ pernapasan yang paling dirugikan oleh asap rokok adalah...",o:["Paru-paru","Lambung","Ginjal","Usus"],a:0,p:"Asap rokok dihirup langsung ke paru-paru sehingga dapat merusak saluran napas dan alveolus."},
      {lv:2,q:"Memakai masker saat udara berdebu atau berasap bertujuan untuk...",o:["Menambah jumlah oksigen di udara","Menghangatkan seluruh tubuh","Mengurangi debu dan zat berbahaya yang terhirup","Mempercepat napas"],a:2,p:"Masker menyaring sebagian debu dan asap agar tidak masuk ke saluran pernapasan."},
      {lv:3,q:"Di puncak gunung, udara lebih tipis sehingga oksigen yang terhirup lebih sedikit. Pendaki gunung sering bernapas lebih cepat. Mengapa?",o:["Udara di gunung lebih banyak mengandung oksigen","Tubuh berusaha mendapatkan oksigen yang cukup","Paru-paru pendaki menjadi mengecil","Tubuh tidak lagi membutuhkan oksigen"],a:1,p:"Setiap tarikan napas membawa lebih sedikit oksigen, sehingga tubuh bernapas lebih cepat untuk memenuhi kebutuhannya."},
      {lv:3,q:"Rafi meniupkan napasnya ke dalam air kapur jernih menggunakan sedotan. Lama-kelamaan air kapur menjadi keruh. Hal ini membuktikan bahwa udara yang diembuskan mengandung...",o:["Oksigen murni","Gas hidrogen","Gas klorin","Karbon dioksida"],a:3,p:"Karbon dioksida bereaksi dengan air kapur membentuk endapan putih sehingga air kapur menjadi keruh."},
      {lv:3,q:"Saat makan sambil berbicara atau tertawa, kita bisa tersedak. Penyebabnya adalah...",o:["Lambung sudah terlalu penuh","Paru-paru menyedot makanan","Makanan dapat masuk ke saluran pernapasan karena katup epiglotis tidak sempat menutup","Hidung tersumbat oleh lendir"],a:2,p:"Epiglotis menutup saluran napas saat menelan. Ketika kita berbicara sambil menelan, epiglotis terbuka sehingga makanan bisa masuk ke saluran napas."},
      {lv:3,q:"Pada model paru-paru dari botol plastik, balon, dan karet, karet di bagian bawah botol ditarik ke bawah sehingga balon di dalam botol mengembang. Karet tersebut berperan seperti...",o:["Diafragma","Trakea","Hidung","Alveolus"],a:0,p:"Karet yang ditarik ke bawah meniru diafragma yang turun saat menarik napas, sehingga ruang dada membesar dan udara masuk."},
      {lv:3,q:"Penyakit asma menyebabkan saluran pernapasan menyempit. Akibatnya penderita asma akan...",o:["Sulit bernapas karena udara sulit masuk dan keluar","Bernapas lebih lega dari biasanya","Tidak membutuhkan oksigen lagi","Memiliki paru-paru yang membesar"],a:0,p:"Saluran napas yang menyempit membuat aliran udara terhambat, sehingga penderita merasa sesak."},
      {lv:3,q:"Dibandingkan dengan udara yang kita hirup, udara yang kita embuskan mengandung...",o:["Lebih banyak oksigen dan lebih sedikit karbon dioksida","Oksigen dan karbon dioksida yang sama banyak","Tidak ada oksigen sama sekali","Lebih sedikit oksigen dan lebih banyak karbon dioksida"],a:3,p:"Sebagian oksigen dipakai tubuh dan karbon dioksida hasil tubuh ikut dibuang. Namun udara embusan masih mengandung sedikit oksigen."},
      {lv:3,q:"Mengapa dinding alveolus sangat tipis dan dikelilingi banyak pembuluh darah kapiler?",o:["Agar paru-paru menjadi lebih berat","Agar oksigen mudah masuk ke darah dan karbon dioksida mudah keluar","Agar makanan dapat diserap di paru-paru","Agar udara tersimpan lama di paru-paru"],a:1,p:"Dinding tipis dan banyak kapiler memudahkan pertukaran gas antara udara di alveolus dan darah."},
      {lv:3,q:"Mengapa menanam banyak pohon di sekitar rumah baik bagi pernapasan kita?",o:["Pohon menghasilkan banyak karbon dioksida","Pohon menyerap semua oksigen di udara","Pohon menghasilkan oksigen melalui fotosintesis dan menyerap karbon dioksida","Pohon membuat udara menjadi berdebu"],a:2,p:"Saat fotosintesis, tumbuhan memakai karbon dioksida dan melepaskan oksigen, sehingga udara menjadi lebih segar."}
    ],
    "ipa-k5-1": [
      {lv:1,q:"Hewan yang hanya memakan tumbuhan disebut...",o:["Herbivor","Karnivor","Omnivor","Pengurai"],a:0,p:"Herbivor adalah pemakan tumbuhan, contohnya sapi, kambing, dan kelinci."},
      {lv:1,q:"Hewan yang memakan daging hewan lain disebut...",o:["Herbivor","Omnivor","Karnivor","Produsen"],a:2,p:"Karnivor adalah pemakan daging, contohnya harimau dan elang."},
      {lv:1,q:"Contoh hewan omnivor (pemakan segala) adalah...",o:["Sapi","Harimau","Kambing","Ayam"],a:3,p:"Ayam memakan biji-bijian dan juga cacing atau serangga, sehingga termasuk pemakan segala."},
      {lv:1,q:"Peristiwa makan dan dimakan antarmakhluk hidup dengan urutan tertentu disebut...",o:["Fotosintesis","Rantai makanan","Metamorfosis","Penyerbukan"],a:1,p:"Rantai makanan menunjukkan urutan siapa memakan siapa dalam suatu ekosistem."},
      {lv:1,q:"Gabungan dari beberapa rantai makanan yang saling berhubungan disebut...",o:["Rantai tunggal","Populasi","Jaring-jaring makanan","Habitat"],a:2,p:"Dalam ekosistem, satu hewan bisa makan dan dimakan oleh banyak makhluk. Gabungan rantainya disebut jaring-jaring makanan."},
      {lv:1,q:"Contoh pengurai yang sering tumbuh pada kayu lapuk adalah...",o:["Jamur","Belalang","Burung","Rumput"],a:0,p:"Jamur menguraikan kayu lapuk dan sisa makhluk hidup menjadi zat yang menyuburkan tanah."},
      {lv:2,q:"Perhatikan rantai makanan berikut: Padi - Tikus - Ular - Elang. Makhluk hidup yang berperan sebagai konsumen tingkat III adalah...",o:["Ular","Elang","Tikus","Padi"],a:1,p:"Padi produsen, tikus konsumen I, ular konsumen II, dan elang konsumen III."},
      {lv:2,q:"Perhatikan rantai makanan di kolam: Fitoplankton - Zooplankton - Ikan kecil - Ikan besar. Makhluk hidup yang berperan sebagai konsumen tingkat I adalah...",o:["Fitoplankton","Ikan kecil","Ikan besar","Zooplankton"],a:3,p:"Fitoplankton adalah produsen. Zooplankton memakan fitoplankton sehingga menjadi konsumen tingkat I."},
      {lv:2,q:"Contoh komponen tak hidup (abiotik) dalam ekosistem adalah...",o:["Rumput dan cacing","Jamur dan bakteri","Belalang dan burung","Air, tanah, dan cahaya matahari"],a:3,p:"Komponen abiotik adalah benda tak hidup yang memengaruhi makhluk hidup, misalnya air, tanah, udara, dan cahaya."},
      {lv:2,q:"Daun-daun yang gugur di hutan lama-kelamaan hancur dan menyatu dengan tanah. Hal ini terjadi karena kerja...",o:["Produsen","Pengurai","Konsumen puncak","Herbivor"],a:1,p:"Pengurai seperti jamur dan bakteri menghancurkan daun gugur menjadi zat hara di tanah."},
      {lv:2,q:"Contoh ekosistem buatan yang dibuat oleh manusia adalah...",o:["Sawah","Hutan hujan","Laut","Gua alami"],a:0,p:"Sawah sengaja dibuat dan dirawat manusia untuk menanam padi, sehingga termasuk ekosistem buatan."},
      {lv:2,q:"Dalam rantai makanan, energi berpindah dari...",o:["Makhluk hidup yang memakan ke makhluk hidup yang dimakan","Pengurai ke matahari","Makhluk hidup yang dimakan ke makhluk hidup yang memakan","Konsumen ke produsen"],a:2,p:"Saat dimakan, energi dari makanan pindah ke tubuh pemakannya. Karena itu panah rantai makanan mengarah ke pemakan."},
      {lv:3,q:"Di sebuah sawah terdapat rantai makanan: Padi - Belalang - Katak - Ular. Petani menyemprot pestisida berlebihan sehingga hampir semua belalang mati. Dampak yang paling mungkin terjadi adalah...",o:["Katak bertambah banyak","Katak kekurangan makanan sehingga jumlahnya berkurang, lalu ular juga berkurang","Ular bertambah banyak","Padi menjadi rusak parah"],a:1,p:"Belalang adalah makanan katak. Tanpa belalang, katak berkurang, dan ular yang memakan katak ikut berkurang."},
      {lv:3,q:"Apa yang akan terjadi jika semua pengurai di sebuah hutan menghilang?",o:["Tumbuhan tumbuh jauh lebih subur","Hewan tidak lagi membutuhkan makanan","Matahari berhenti bersinar","Sisa makhluk hidup yang mati menumpuk dan tanah kekurangan zat hara"],a:3,p:"Tanpa pengurai, bangkai dan daun mati tidak terurai. Zat hara tidak kembali ke tanah sehingga tumbuhan kekurangan nutrisi."},
      {lv:3,q:"Ular sawah sering diburu manusia. Akibatnya jumlah tikus meningkat dan banyak padi rusak. Upaya terbaik untuk menjaga keseimbangan ekosistem sawah adalah...",o:["Memburu lebih banyak ular","Menanam padi lebih sedikit","Tidak memburu ular agar jumlah tikus terkendali secara alami","Membakar seluruh sawah"],a:2,p:"Ular adalah pemangsa alami tikus. Jika ular dibiarkan hidup, jumlah tikus tetap terkendali."},
      {lv:3,q:"Mengapa jumlah produsen dalam suatu ekosistem harus lebih banyak daripada konsumen?",o:["Karena energi berkurang pada setiap tingkat sehingga konsumen membutuhkan banyak produsen","Karena produsen berukuran lebih kecil","Karena konsumen tidak perlu makan","Karena produsen tidak membutuhkan matahari"],a:0,p:"Sebagian besar energi dipakai untuk hidup dan hilang sebagai panas. Agar cukup, konsumen membutuhkan banyak produsen."},
      {lv:3,q:"Dalam suatu jaring-jaring makanan, rumput dimakan belalang dan kelinci. Belalang dimakan burung, kelinci dimakan ular, sedangkan burung dan ular dimakan elang. Makhluk hidup yang berperan sebagai konsumen tingkat I adalah...",o:["Belalang dan kelinci","Burung dan ular","Elang dan ular","Rumput dan belalang"],a:0,p:"Konsumen tingkat I memakan produsen. Yang memakan rumput adalah belalang dan kelinci."},
      {lv:3,q:"Dalam suatu jaring-jaring makanan, rumput dimakan belalang dan kelinci. Belalang dimakan burung, kelinci dimakan ular, sedangkan burung dan ular dimakan elang. Jika kelinci menghilang, hewan yang paling kehilangan sumber makanannya adalah...",o:["Burung","Belalang","Elang","Ular"],a:3,p:"Pada jaring-jaring itu ular hanya memakan kelinci. Elang masih bisa memakan burung, jadi ular paling terdampak."},
      {lv:3,q:"Cacing tanah dianggap membantu petani. Alasan yang paling tepat adalah...",o:["Cacing memakan akar padi","Cacing menggemburkan tanah dan membantu menguraikan sisa tumbuhan","Cacing menghasilkan oksigen untuk tanaman","Cacing memakan hama tikus"],a:1,p:"Lubang cacing membuat tanah gembur dan berudara. Kotoran cacing dari sisa tumbuhan juga menyuburkan tanah."},
      {lv:3,q:"Di sebuah danau, eceng gondok tumbuh sangat banyak hingga menutupi permukaan air. Dampaknya bagi ikan di danau adalah...",o:["Ikan mendapat lebih banyak oksigen","Air danau menjadi lebih jernih","Cahaya dan oksigen di dalam air berkurang sehingga kehidupan ikan terganggu","Ikan bertambah besar dengan cepat"],a:2,p:"Eceng gondok menghalangi cahaya masuk sehingga tumbuhan air di bawahnya sulit berfotosintesis. Oksigen di air berkurang dan ikan terganggu."}
    ],
    "ipa-k5-2": [
      {lv:1,q:"Bahan yang mudah menghantarkan panas disebut...",o:["Konduktor","Isolator","Pelarut","Magnet"],a:0,p:"Konduktor adalah bahan yang mudah dilalui panas, misalnya logam."},
      {lv:1,q:"Contoh bahan yang merupakan konduktor panas adalah...",o:["Kayu","Plastik","Besi","Kain"],a:2,p:"Besi adalah logam sehingga mudah menghantarkan panas."},
      {lv:1,q:"Contoh bahan yang merupakan isolator panas adalah...",o:["Tembaga","Aluminium","Besi","Kayu"],a:3,p:"Kayu sulit menghantarkan panas sehingga termasuk isolator. Tembaga, aluminium, dan besi adalah konduktor."},
      {lv:1,q:"Satuan suhu yang biasa digunakan sehari-hari di Indonesia adalah...",o:["Meter","Derajat Celsius","Kilogram","Liter"],a:1,p:"Suhu sehari-hari di Indonesia dinyatakan dalam derajat Celsius (°C)."},
      {lv:1,q:"Alat yang digunakan untuk mengukur suhu adalah...",o:["Penggaris","Timbangan","Termometer","Stopwatch"],a:2,p:"Termometer digunakan untuk mengukur suhu benda atau tubuh."},
      {lv:1,q:"Panas selalu berpindah dari benda yang suhunya...",o:["Lebih tinggi ke benda yang suhunya lebih rendah","Lebih rendah ke benda yang suhunya lebih tinggi","Sama ke benda yang suhunya sama","Rendah dan tidak pernah berpindah"],a:0,p:"Panas mengalir dari benda yang lebih panas ke benda yang lebih dingin, sampai suhunya sama."},
      {lv:2,q:"Mengapa kita memakai jaket tebal saat cuaca dingin?",o:["Jaket menghasilkan panas sendiri","Jaket menghambat panas tubuh agar tidak cepat keluar","Jaket menyerap udara dingin","Jaket menghantarkan panas tubuh ke luar"],a:1,p:"Jaket tebal bersifat isolator. Panas tubuh tertahan sehingga badan tetap hangat."},
      {lv:2,q:"Es batu dimasukkan ke dalam segelas teh hangat sehingga teh menjadi dingin. Hal ini terjadi karena...",o:["Dingin dari es berpindah ke teh","Es menghasilkan panas","Teh menyerap es tanpa ada perpindahan panas","Panas dari teh berpindah ke es"],a:3,p:"Panas berpindah dari teh yang lebih hangat ke es yang lebih dingin. Teh kehilangan panas sehingga menjadi dingin."},
      {lv:2,q:"Pakaian berwarna hitam terasa lebih panas dipakai di bawah terik matahari. Hal ini karena...",o:["Warna hitam memantulkan semua panas","Warna hitam menghantarkan udara dingin","Warna hitam lebih berat","Warna hitam lebih banyak menyerap panas dari matahari"],a:3,p:"Benda berwarna gelap menyerap lebih banyak radiasi panas matahari dibandingkan benda berwarna terang."},
      {lv:2,q:"Asap dari tungku pembakaran bergerak naik ke atas. Perpindahan panas yang menyebabkan peristiwa ini adalah...",o:["Konduksi","Konveksi","Radiasi","Isolasi"],a:1,p:"Udara panas dan asap menjadi lebih ringan lalu naik membawa panas. Perpindahan panas bersama gerakan zat disebut konveksi."},
      {lv:2,q:"Tangan yang didekatkan ke setrika panas tanpa menyentuhnya tetap terasa hangat. Perpindahan panas ini disebut...",o:["Radiasi","Konduksi","Konveksi","Isolasi"],a:0,p:"Panas sampai ke tangan tanpa sentuhan, dalam bentuk pancaran. Perpindahan seperti ini disebut radiasi."},
      {lv:2,q:"Saat mengangkat tutup panci yang panas, ibu memakai kain lap tebal. Kain lap tebal berfungsi sebagai...",o:["Konduktor yang mempercepat panas ke tangan","Sumber panas tambahan","Isolator yang menghambat perpindahan panas ke tangan","Alat pengukur suhu"],a:2,p:"Kain tebal sulit dilalui panas, sehingga tangan ibu tidak kepanasan."},
      {lv:3,q:"Rumah di daerah panas sering dibuat dengan lubang ventilasi di bagian atas dinding. Apa tujuannya?",o:["Udara dingin naik dan keluar melalui ventilasi","Udara panas naik dan keluar melalui ventilasi atas, lalu digantikan udara yang lebih sejuk","Ventilasi atas menyerap panas matahari","Ventilasi atas menghantarkan panas melalui dinding"],a:1,p:"Udara panas lebih ringan sehingga naik. Ventilasi di atas memberi jalan keluar bagi udara panas (konveksi)."},
      {lv:3,q:"Andi menuang air panas ke dalam gelas kaca tebal dan gelas logam tipis secara bersamaan. Gelas mana yang lebih cepat terasa panas di tangan dan mengapa?",o:["Gelas kaca, karena kaca adalah konduktor panas yang paling baik","Keduanya sama karena airnya sama panas","Gelas kaca, karena kaca lebih tebal","Gelas logam, karena logam adalah konduktor panas yang baik"],a:3,p:"Logam menghantarkan panas jauh lebih cepat daripada kaca. Panas air lebih cepat sampai ke tangan melalui gelas logam."},
      {lv:3,q:"Saat memasak air, api diletakkan di bawah panci, bukan di atasnya. Mengapa cara ini membuat seluruh air cepat panas?",o:["Air panas selalu tetap di bagian bawah","Panas hanya bisa berpindah ke bawah","Air yang panas di bagian bawah naik dan air dingin turun, sehingga terjadi aliran yang meratakan panas","Air dingin naik ke atas lalu menguap"],a:2,p:"Air yang dipanaskan di bawah menjadi ringan dan naik, lalu air dingin turun dan ikut dipanaskan. Aliran konveksi ini meratakan panas."},
      {lv:3,q:"Pada banyak kulkas, bagian pembeku (freezer) diletakkan di bagian atas. Mengapa letak ini membantu mendinginkan seluruh isi kulkas?",o:["Udara dingin dari bagian atas turun ke bawah sehingga bagian bawah ikut dingin","Udara dingin selalu naik ke atas","Panas berpindah dari freezer ke makanan","Udara dingin tidak dapat bergerak"],a:0,p:"Udara dingin lebih berat sehingga turun, dan udara yang lebih hangat naik ke freezer untuk didinginkan. Inilah aliran konveksi."},
      {lv:3,q:"Perhatikan peristiwa berikut: (1) sendok di dalam kuah panas ikut menjadi panas, (2) air yang mendidih bergerak naik turun, (3) badan terasa hangat di dekat api unggun. Jenis perpindahan panas pada peristiwa tersebut secara berturut-turut adalah...",o:["Konduksi, konveksi, radiasi","Konveksi, konduksi, radiasi","Radiasi, konveksi, konduksi","Konduksi, radiasi, konveksi"],a:0,p:"Sendok: panas merambat melalui benda (konduksi). Air: panas pindah bersama aliran air (konveksi). Api unggun: panas memancar (radiasi)."},
      {lv:3,q:"Mengapa atap atau dinding luar rumah di daerah panas sering dicat dengan warna terang?",o:["Warna terang menyerap lebih banyak panas","Warna terang menghantarkan panas ke dalam rumah","Warna terang membuat angin bertiup lebih kencang","Warna terang memantulkan lebih banyak panas matahari sehingga rumah tidak terlalu panas"],a:3,p:"Benda berwarna terang memantulkan sebagian besar radiasi matahari, sehingga panas yang masuk ke rumah lebih sedikit."},
      {lv:3,q:"Ketika memegang gelas berisi es, tangan kita terasa dingin. Penjelasan yang benar adalah...",o:["Dingin dari es berpindah ke tangan","Panas dari tangan berpindah ke gelas es sehingga tangan kehilangan panas","Es mengeluarkan panas ke tangan","Tidak ada perpindahan panas sama sekali"],a:1,p:"Yang berpindah adalah panas, dari tangan yang lebih hangat ke gelas yang lebih dingin. Tangan kehilangan panas sehingga terasa dingin."},
      {lv:3,q:"Ibu harus mengaduk sup yang mendidih cukup lama. Sendok yang paling tepat dipilih adalah...",o:["Sendok besi, karena besi isolator panas","Sendok aluminium, karena aluminium tidak menghantarkan panas","Sendok kayu, karena kayu isolator sehingga panas tidak cepat sampai ke tangan","Sendok tembaga, karena tembaga menahan panas"],a:2,p:"Kayu sulit menghantarkan panas. Besi, aluminium, dan tembaga adalah logam konduktor yang cepat menjadi panas."}
    ],
    "ipa-k6-0": [
      {lv:1,q:"Planet tempat kita tinggal adalah...",o:["Bumi","Mars","Venus","Jupiter"],a:0,p:"Kita tinggal di planet Bumi, planet ketiga dari Matahari."},
      {lv:1,q:"Satelit alami yang mengelilingi Bumi adalah...",o:["Phobos","Titan","Bulan","Matahari"],a:2,p:"Bulan adalah satu-satunya satelit alami Bumi. Phobos milik Mars, Titan milik Saturnus."},
      {lv:1,q:"Jumlah planet dalam tata surya kita saat ini adalah...",o:["9","7","10","8"],a:3,p:"Sejak 2006, Pluto digolongkan sebagai planet kerdil, sehingga planet dalam tata surya berjumlah 8."},
      {lv:1,q:"Planet yang letaknya paling jauh dari Matahari adalah...",o:["Uranus","Neptunus","Saturnus","Merkurius"],a:1,p:"Urutan planet: Merkurius, Venus, Bumi, Mars, Jupiter, Saturnus, Uranus, Neptunus. Neptunus paling jauh."},
      {lv:1,q:"Matahari termasuk jenis benda langit berupa...",o:["Planet","Satelit","Bintang","Komet"],a:2,p:"Matahari menghasilkan cahaya dan panas sendiri, sehingga termasuk bintang."},
      {lv:1,q:"Perputaran Bumi pada porosnya disebut...",o:["Rotasi","Revolusi","Gerhana","Orbit"],a:0,p:"Rotasi adalah perputaran pada poros. Revolusi adalah gerak mengelilingi Matahari."},
      {lv:2,q:"Akibat dari rotasi Bumi adalah...",o:["Terjadinya pergantian musim","Terjadinya siang dan malam","Terjadinya pergantian tahun","Terjadinya gerhana setiap hari"],a:1,p:"Saat berotasi, sebagian Bumi menghadap Matahari (siang) dan sebagian lain membelakanginya (malam)."},
      {lv:2,q:"Lintasan yang dilalui planet ketika mengelilingi Matahari disebut...",o:["Poros","Atmosfer","Kawah","Orbit"],a:3,p:"Orbit adalah jalur atau lintasan benda langit ketika mengelilingi benda langit lain."},
      {lv:2,q:"Urutan empat planet dalam dimulai dari yang paling dekat dengan Matahari adalah...",o:["Venus, Merkurius, Bumi, Mars","Merkurius, Bumi, Venus, Mars","Mars, Bumi, Venus, Merkurius","Merkurius, Venus, Bumi, Mars"],a:3,p:"Planet dalam adalah planet di dalam sabuk asteroid, berurutan Merkurius, Venus, Bumi, dan Mars."},
      {lv:2,q:"Benda langit yang memiliki ekor panjang bercahaya ketika mendekati Matahari adalah...",o:["Asteroid","Komet","Satelit","Planet"],a:1,p:"Komet tersusun dari es dan debu. Saat dekat Matahari, es menguap membentuk ekor yang tampak bercahaya."},
      {lv:2,q:"Bulan tampak bersinar pada malam hari karena...",o:["Memantulkan cahaya Matahari","Menghasilkan cahaya sendiri","Permukaannya terbakar","Memiliki lampu alami"],a:0,p:"Bulan tidak menghasilkan cahaya. Cahaya Bulan adalah cahaya Matahari yang dipantulkan permukaannya."},
      {lv:2,q:"Setiap hari Matahari tampak terbit di timur dan terbenam di barat. Hal ini terjadi karena...",o:["Matahari mengelilingi Bumi setiap hari","Bumi berevolusi mengelilingi Matahari","Bumi berotasi dari barat ke timur","Bulan mengelilingi Bumi"],a:2,p:"Bumi berputar dari barat ke timur, sehingga Matahari seolah-olah bergerak dari timur ke barat. Ini disebut gerak semu harian."},
      {lv:3,q:"Gerhana Matahari terjadi ketika posisi benda langit berada pada urutan...",o:["Bumi berada di antara Matahari dan Bulan","Bulan berada di antara Matahari dan Bumi","Matahari berada di antara Bumi dan Bulan","Bulan berada di belakang Matahari"],a:1,p:"Saat Bulan berada di antara Matahari dan Bumi, bayangan Bulan jatuh ke Bumi dan menutupi cahaya Matahari."},
      {lv:3,q:"Gerhana Bulan terjadi ketika...",o:["Bulan berada di antara Matahari dan Bumi","Matahari berada di antara Bumi dan Bulan","Bulan berhenti memantulkan cahaya dengan sendirinya","Bumi berada di antara Matahari dan Bulan sehingga bayangan Bumi menutupi Bulan"],a:3,p:"Pada gerhana Bulan, Bumi menghalangi cahaya Matahari yang menuju Bulan, sehingga Bulan masuk ke bayangan Bumi."},
      {lv:3,q:"Mengapa Bumi menjadi satu-satunya planet yang diketahui dapat dihuni makhluk hidup?",o:["Bumi adalah planet terbesar","Bumi adalah planet terdekat dengan Matahari","Bumi memiliki air dalam wujud cair, udara yang mengandung oksigen, dan suhu yang sesuai","Bumi tidak memiliki atmosfer"],a:2,p:"Kehidupan membutuhkan air cair, oksigen, dan suhu yang tidak terlalu panas atau dingin. Kondisi ini dimiliki Bumi."},
      {lv:3,q:"Merkurius lebih dekat ke Matahari daripada Venus, tetapi suhu permukaan Venus justru lebih panas. Penyebab utamanya adalah...",o:["Atmosfer Venus sangat tebal dan kaya karbon dioksida sehingga panas terperangkap","Venus sebenarnya lebih dekat ke Matahari","Merkurius memiliki atmosfer yang lebih tebal","Venus berotasi jauh lebih cepat daripada planet lain"],a:0,p:"Atmosfer tebal Venus menahan panas seperti rumah kaca. Merkurius hampir tidak punya atmosfer sehingga panasnya mudah lepas."},
      {lv:3,q:"Ketika di Jakarta sedang siang hari, di Brasil yang letaknya di sisi Bumi yang berlawanan sedang malam hari. Penyebabnya adalah...",o:["Rotasi Bumi membuat hanya sebagian permukaan Bumi yang menghadap Matahari","Revolusi Bumi mengelilingi Matahari","Bulan menutupi Matahari di Brasil","Matahari padam sementara di Brasil"],a:0,p:"Bumi berbentuk bulat dan berotasi. Sisi yang menghadap Matahari mengalami siang, sisi sebaliknya mengalami malam."},
      {lv:3,q:"Planet yang memiliki kala revolusi (waktu satu kali mengelilingi Matahari) paling singkat adalah...",o:["Neptunus, karena letaknya paling jauh","Jupiter, karena ukurannya paling besar","Bumi, karena memiliki satelit","Merkurius, karena orbitnya paling dekat dan paling pendek"],a:3,p:"Semakin dekat ke Matahari, semakin pendek lintasan dan semakin cepat geraknya. Merkurius hanya butuh sekitar 88 hari."},
      {lv:3,q:"Seandainya Bumi berhenti berotasi tetapi tetap berevolusi mengelilingi Matahari, akibat yang paling mungkin terjadi adalah...",o:["Tidak ada lagi pergantian tahun","Siang dan malam berlangsung sangat lama, masing-masing sekitar setengah tahun","Bumi menjadi lebih dekat ke Matahari","Bulan berhenti mengelilingi Bumi"],a:1,p:"Tanpa rotasi, suatu tempat hanya berganti menghadap Matahari karena revolusi. Satu siang dan satu malam akan memakan waktu sekitar satu tahun."},
      {lv:3,q:"Tahun kabisat yang berjumlah 366 hari diadakan setiap empat tahun sekali. Alasannya adalah...",o:["Rotasi Bumi melambat satu hari setiap empat tahun","Bulan mengelilingi Bumi 366 kali setiap empat tahun","Revolusi Bumi memerlukan sekitar 365,25 hari, sehingga sisa 0,25 hari setiap tahun dikumpulkan menjadi 1 hari setiap 4 tahun","Matahari berputar lebih lama setiap empat tahun"],a:2,p:"Kalender biasa hanya 365 hari. Kelebihan 0,25 hari x 4 tahun = 1 hari, yang ditambahkan pada bulan Februari."}
    ],
    "ipa-k6-1": [
      {lv:1,q:"Komponen yang mengubah energi listrik menjadi cahaya pada rangkaian listrik sederhana adalah...",o:["Lampu","Sakelar","Kabel","Baterai"],a:0,p:"Lampu menyala karena dialiri arus listrik, sehingga energi listrik berubah menjadi cahaya."},
      {lv:1,q:"Kutub baterai yang ditandai dengan tanda (+) disebut kutub...",o:["Negatif","Netral","Positif","Utara"],a:2,p:"Tanda (+) menunjukkan kutub positif dan tanda (-) menunjukkan kutub negatif."},
      {lv:1,q:"Bahan yang dapat menghantarkan arus listrik dengan baik disebut...",o:["Isolator","Pelarut","Pengurai","Konduktor"],a:3,p:"Konduktor listrik adalah bahan yang mudah dilalui arus listrik, misalnya logam."},
      {lv:1,q:"Rangkaian yang memiliki cabang sehingga arus listrik dapat mengalir melalui lebih dari satu jalur disebut rangkaian...",o:["Seri","Paralel","Terbuka","Tunggal"],a:1,p:"Rangkaian paralel bercabang. Arus dari sumber terbagi ke beberapa jalur."},
      {lv:1,q:"Rangkaian listrik yang jalurnya terputus sehingga arus tidak dapat mengalir disebut rangkaian...",o:["Tertutup","Paralel","Terbuka","Seri"],a:2,p:"Jika ada bagian yang terputus, misalnya sakelar dimatikan, rangkaian menjadi terbuka dan lampu padam."},
      {lv:1,q:"Fungsi kabel dalam rangkaian listrik adalah...",o:["Menghubungkan komponen agar arus listrik dapat mengalir","Menyimpan energi listrik","Mengubah listrik menjadi cahaya","Memutus aliran arus listrik"],a:0,p:"Kabel menjadi jalan bagi arus listrik dari sumber ke lampu dan kembali ke sumber."},
      {lv:2,q:"Lampu senter menyala ketika tombolnya ditekan. Hal ini terjadi karena...",o:["Rangkaian menjadi terbuka","Rangkaian menjadi tertutup sehingga arus dapat mengalir","Baterai terlepas dari senter","Kabel di dalam senter terputus"],a:1,p:"Tombol senter adalah sakelar. Saat ditekan, sakelar menyambung jalur sehingga rangkaian tertutup dan arus mengalir ke lampu."},
      {lv:2,q:"Benda berikut yang termasuk konduktor listrik adalah...",o:["Penghapus karet","Penggaris plastik","Kertas","Paku besi"],a:3,p:"Paku terbuat dari logam besi yang dapat menghantarkan listrik. Karet, plastik, dan kertas adalah isolator."},
      {lv:2,q:"Ketika sakelar lampu kamar dimatikan, lampu kamar padam tetapi lampu ruang tamu tetap menyala. Hal ini menunjukkan bahwa lampu-lampu di rumah dipasang secara...",o:["Seri","Terbuka","Tunggal","Paralel"],a:3,p:"Pada rangkaian paralel, setiap lampu punya jalur sendiri sehingga dapat dinyalakan dan dimatikan tanpa memengaruhi lampu lain."},
      {lv:2,q:"Dua lampu identik dipasang seri dengan sebuah baterai. Jika ditambah satu lampu identik lagi secara seri, nyala ketiga lampu menjadi...",o:["Lebih terang","Lebih redup","Tetap sama","Berkedip-kedip"],a:1,p:"Tegangan baterai harus terbagi ke lebih banyak lampu dan hambatan total bertambah, sehingga setiap lampu menyala lebih redup."},
      {lv:2,q:"Mengapa kita tidak boleh menyentuh stopkontak atau sakelar dengan tangan basah?",o:["Air yang mengandung zat terlarut dapat menghantarkan listrik sehingga kita bisa tersengat","Air bersifat isolator sehingga listrik menjadi padam","Tangan basah membuat stopkontak menjadi dingin","Air membuat listrik di rumah menjadi lebih hemat"],a:0,p:"Air sehari-hari mengandung zat terlarut sehingga dapat menghantarkan listrik. Tangan basah memudahkan arus mengalir ke tubuh."},
      {lv:2,q:"Dua baterai masing-masing 1,5 volt disusun seri dengan benar. Tegangan totalnya adalah...",o:["1,5 volt","0,75 volt","3 volt","4,5 volt"],a:2,p:"Pada susunan seri, tegangan baterai dijumlahkan: 1,5 V + 1,5 V = 3 V."},
      {lv:3,q:"Riko merangkai baterai, lampu, dan kabel. Baterai masih baru dan lampu dalam keadaan baik, tetapi lampu tidak menyala. Penyebab yang paling mungkin adalah...",o:["Baterai terlalu baru","Ada sambungan kabel yang terlepas sehingga rangkaian terbuka","Lampu terlalu terang","Kabelnya terbuat dari tembaga"],a:1,p:"Jika semua komponen baik tetapi lampu tidak menyala, kemungkinan besar jalur arus terputus di sambungan sehingga rangkaian terbuka."},
      {lv:3,q:"Sinta membuat alat penguji dari baterai, lampu, dan dua ujung kabel. Lampu menyala ketika kedua ujung kabel ditempelkan pada uang logam, tetapi tidak menyala ketika ditempelkan pada pensil kayu. Kesimpulan yang tepat adalah...",o:["Uang logam adalah isolator, sedangkan kayu adalah konduktor","Keduanya adalah konduktor","Keduanya adalah isolator","Uang logam adalah konduktor, sedangkan kayu adalah isolator"],a:3,p:"Lampu menyala berarti arus dapat melewati benda (konduktor). Lampu padam berarti benda tidak dapat dilalui arus (isolator)."},
      {lv:3,q:"Tiga baterai masing-masing 1,5 volt disusun seri untuk menyalakan lampu, tetapi satu baterai terpasang terbalik. Tegangan total yang diterima lampu adalah...",o:["4,5 volt","3 volt","1,5 volt","0 volt"],a:2,p:"Baterai yang terbalik melawan baterai lain. Tegangannya: 1,5 + 1,5 - 1,5 = 1,5 volt."},
      {lv:3,q:"Lampu A dan lampu B dipasang paralel pada sebuah baterai. Sebuah sakelar dipasang hanya pada cabang lampu B. Jika sakelar tersebut dibuka, yang terjadi adalah...",o:["Lampu A tetap menyala, lampu B padam","Lampu A dan B sama-sama padam","Lampu A padam, lampu B tetap menyala","Lampu A dan B sama-sama tetap menyala"],a:0,p:"Sakelar hanya memutus cabang B. Cabang A masih tersambung ke baterai, sehingga lampu A tetap menyala."},
      {lv:3,q:"Dua lampu identik disusun seri dan dihubungkan dengan dua baterai 1,5 volt yang juga disusun seri. Tegangan pada setiap lampu adalah...",o:["1,5 volt","3 volt","0,75 volt","6 volt"],a:0,p:"Tegangan total 1,5 + 1,5 = 3 V. Karena lampunya identik dan seri, tegangan terbagi rata: 3 V : 2 = 1,5 V."},
      {lv:3,q:"Ketika setrika, rice cooker, dan pompa air dinyalakan bersamaan, listrik di rumah tiba-tiba padam karena pengaman (MCB) turun. Hal ini terjadi karena...",o:["Arus listrik terlalu kecil","Tegangan listrik PLN berubah menjadi nol karena alat terlalu sedikit","Alat-alat tersebut tidak memerlukan listrik","Arus total terlalu besar sehingga pengaman memutus arus agar kabel tidak terlalu panas"],a:3,p:"Pada rangkaian paralel, arus total bertambah setiap ada alat yang menyala. Jika terlalu besar, pengaman memutus arus untuk mencegah kebakaran."},
      {lv:3,q:"Tukang listrik memakai sepatu karet dan obeng bergagang plastik ketika bekerja. Alasan pemilihan bahan tersebut adalah...",o:["Karet dan plastik adalah konduktor yang mempercepat pekerjaan","Karet dan plastik adalah isolator sehingga melindungi tubuh dari sengatan listrik","Karet dan plastik membuat arus listrik lebih besar","Karet dan plastik lebih berat sehingga obeng stabil"],a:1,p:"Isolator tidak menghantarkan listrik. Dengan begitu arus tidak mudah mengalir melalui tubuh tukang listrik."},
      {lv:3,q:"Dua lampu identik dipasang seri pada sebuah baterai. Dua lampu identik lain dipasang paralel pada baterai baru yang sama jenisnya. Baterai pada rangkaian manakah yang lebih cepat habis dan mengapa?",o:["Rangkaian seri, karena arus total yang ditarik dari baterai lebih besar","Keduanya habis bersamaan karena lampunya sama","Rangkaian paralel, karena arus total yang ditarik dari baterai lebih besar","Rangkaian seri, karena lampunya lebih terang"],a:2,p:"Pada paralel, setiap lampu mendapat tegangan penuh dan arus total lebih besar. Energi baterai terpakai lebih cepat."}
    ],
    "ipa-k6-2": [
      {lv:1,q:"Contoh hewan yang berkembang biak dengan cara bertelur (ovipar) adalah...",o:["Ayam","Kucing","Sapi","Kambing"],a:0,p:"Ayam bertelur, lalu telurnya dierami hingga menetas. Kucing, sapi, dan kambing melahirkan."},
      {lv:1,q:"Contoh hewan yang berkembang biak dengan cara melahirkan (vivipar) adalah...",o:["Ayam","Penyu","Kambing","Cicak"],a:2,p:"Kambing melahirkan anaknya. Ayam, penyu, dan cicak bertelur."},
      {lv:1,q:"Tanaman singkong biasanya diperbanyak dengan cara...",o:["Menanam biji","Menyebar spora","Umbi lapis","Stek batang"],a:3,p:"Petani menanam potongan batang singkong. Potongan itu akan tumbuh akar dan tunas baru."},
      {lv:1,q:"Tumbuhan paku dan jamur berkembang biak dengan menggunakan...",o:["Biji","Spora","Umbi lapis","Geragih"],a:1,p:"Paku dan jamur tidak menghasilkan biji. Keduanya berkembang biak dengan spora yang sangat kecil."},
      {lv:1,q:"Tanaman stroberi berkembang biak secara vegetatif alami dengan batang yang menjalar di atas tanah. Batang ini disebut...",o:["Umbi lapis","Rimpang","Geragih (stolon)","Tunas daun"],a:2,p:"Geragih adalah batang yang tumbuh menjalar di permukaan tanah dan dapat membentuk tanaman baru."},
      {lv:1,q:"Peleburan antara sel kelamin jantan dan sel kelamin betina disebut...",o:["Pembuahan (fertilisasi)","Penyerbukan","Pembentukan spora","Pertunasan"],a:0,p:"Pembuahan adalah peleburan sel kelamin jantan dan betina yang akan berkembang menjadi individu baru."},
      {lv:2,q:"Bakteri berkembang biak dengan cara...",o:["Bertelur","Membelah diri","Melahirkan","Stek"],a:1,p:"Bakteri bersel satu. Satu sel bakteri membelah menjadi dua sel baru yang sama."},
      {lv:2,q:"Hydra adalah hewan air kecil. Pada tubuhnya dapat tumbuh tonjolan yang lama-kelamaan lepas menjadi individu baru. Cara berkembang biak ini disebut...",o:["Spora","Bertelur","Fragmentasi","Tunas"],a:3,p:"Tonjolan kecil yang tumbuh dari tubuh induk lalu menjadi individu baru disebut tunas."},
      {lv:2,q:"Penyerbukan dengan bantuan angin biasanya terjadi pada bunga yang memiliki ciri...",o:["Mahkotanya berwarna cerah dan berbau harum","Menghasilkan banyak madu","Kelopaknya besar dan berwarna-warni","Bunganya kecil, tidak mencolok, dan serbuk sarinya banyak serta ringan"],a:3,p:"Bunga yang diserbuki angin tidak perlu menarik serangga. Serbuk sari yang ringan dan banyak mudah terbawa angin, misalnya pada padi dan jagung."},
      {lv:2,q:"Di sekitar pohon pisang sering tumbuh anakan pisang baru. Pisang berkembang biak secara vegetatif alami dengan...",o:["Spora","Tunas","Geragih","Umbi lapis"],a:1,p:"Anakan pisang adalah tunas yang tumbuh dari batang di dalam tanah (bonggol) pohon induknya."},
      {lv:2,q:"Tanaman mawar dapat diperbanyak dengan memotong batangnya lalu menancapkannya ke tanah. Cara ini disebut...",o:["Stek","Cangkok","Okulasi","Merunduk"],a:0,p:"Stek adalah perbanyakan dengan menanam potongan bagian tumbuhan, seperti batang, agar tumbuh menjadi tanaman baru."},
      {lv:2,q:"Pembuahan pada katak terjadi di...",o:["Dalam tubuh induk betina","Dalam kepompong","Luar tubuh, yaitu di dalam air","Dalam tanah kering"],a:2,p:"Katak betina mengeluarkan telur ke air, lalu katak jantan mengeluarkan sperma di atasnya. Pembuahan terjadi di luar tubuh."},
      {lv:3,q:"Mengapa tanaman hasil cangkok memiliki sifat yang sama persis dengan induknya?",o:["Karena berasal dari biji hasil penyerbukan silang","Karena berasal dari bagian tubuh induk sendiri tanpa peleburan sel kelamin","Karena mendapat sifat dari dua induk yang berbeda","Karena ditanam di tanah yang sama dengan induknya"],a:1,p:"Cangkok termasuk perbanyakan vegetatif. Tanpa peleburan sel kelamin, sifat yang diturunkan hanya dari satu induk."},
      {lv:3,q:"Salah satu kekurangan tanaman hasil cangkok dibandingkan tanaman yang tumbuh dari biji adalah...",o:["Sifatnya berbeda dengan induknya","Lebih lama berbuah","Tidak dapat menghasilkan buah sama sekali","Tidak memiliki akar tunggang sehingga lebih mudah roboh"],a:3,p:"Tanaman cangkok hanya memiliki akar serabut. Akar ini tidak sekuat akar tunggang dari tanaman biji, sehingga mudah tumbang."},
      {lv:3,q:"Pada okulasi jeruk, mata tunas dari pohon jeruk yang buahnya manis ditempelkan pada batang pohon jeruk lain yang akarnya kuat. Tujuan cara ini adalah...",o:["Mendapatkan tanaman yang tidak berbuah","Mengubah jeruk menjadi jenis buah lain","Mendapatkan tanaman yang buahnya manis sekaligus berakar kuat","Membuat tanaman berkembang biak dengan spora"],a:2,p:"Okulasi menggabungkan dua sifat unggul: bagian atas menghasilkan buah manis dan bagian bawah memberi akar yang kuat."},
      {lv:3,q:"Kelelawar dapat terbang seperti burung, tetapi digolongkan sebagai mamalia. Alasan yang berkaitan dengan cara berkembang biaknya adalah...",o:["Kelelawar melahirkan anak dan menyusuinya","Kelelawar bertelur dan mengerami telurnya","Kelelawar berkembang biak dengan tunas","Kelelawar bertelur di dalam air"],a:0,p:"Mamalia adalah hewan yang melahirkan dan menyusui anaknya. Kelelawar melakukan keduanya."},
      {lv:3,q:"Seekor ikan dapat menghasilkan ribuan telur sekali bertelur, sedangkan kucing hanya melahirkan beberapa anak. Mengapa ikan perlu menghasilkan telur sebanyak itu?",o:["Banyak telur ikan tidak dibuahi atau dimakan pemangsa, sehingga jumlah besar menjamin sebagian dapat bertahan hidup","Ikan tidak membutuhkan keturunan","Semua telur ikan pasti menjadi ikan dewasa","Telur ikan dibuahi di dalam tubuh induk"],a:0,p:"Telur ikan dibuahi di luar tubuh dan tidak dijaga ketat. Banyak yang gagal, jadi jumlah yang besar membantu kelangsungan jenisnya."},
      {lv:3,q:"Roti berjamur yang diletakkan di dekat roti lain membuat roti lain juga ikut berjamur. Penjelasan yang paling tepat adalah...",o:["Roti lain berubah menjadi jamur dengan sendirinya","Jamur berpindah dengan cara berjalan","Jamur berkembang biak dengan biji yang jatuh","Spora jamur yang sangat ringan beterbangan lalu tumbuh di roti lain yang lembap"],a:3,p:"Jamur menghasilkan spora yang sangat kecil dan ringan. Spora terbawa udara dan tumbuh jika menemukan tempat lembap yang berisi makanan."},
      {lv:3,q:"Pada tanaman salak, bunga jantan dan bunga betina tumbuh pada pohon yang berbeda. Petani menaburkan serbuk sari dari pohon jantan ke bunga pohon betina. Penyerbukan ini termasuk...",o:["Penyerbukan sendiri dengan bantuan angin","Penyerbukan silang dengan bantuan manusia","Pembentukan spora","Perkembangbiakan vegetatif buatan"],a:1,p:"Serbuk sari berasal dari pohon lain yang sejenis, jadi termasuk penyerbukan silang. Petani menjadi perantaranya."},
      {lv:3,q:"Seorang pembudidaya ingin memperoleh ribuan bibit pisang yang seragam dan bebas penyakit dalam waktu singkat dari sedikit bagian tanaman. Teknik yang paling tepat adalah...",o:["Menanam biji pisang","Mencangkok batang pisang","Kultur jaringan","Menunggu tunas alami tumbuh"],a:2,p:"Kultur jaringan menumbuhkan potongan kecil jaringan di tempat steril. Dari sedikit bahan dapat dihasilkan banyak bibit yang seragam dan sehat."}
    ],
    "ipa-k7-0": [
      {lv:1,q:"Satuan Sistem Internasional (SI) untuk besaran panjang adalah...",o:["Meter","Sentimeter","Kaki","Inci"],a:0,p:"Satuan SI untuk panjang adalah meter (m). Sentimeter hanya turunan dari meter, sedangkan kaki dan inci bukan satuan SI."},
      {lv:1,q:"Satuan SI untuk besaran waktu adalah...",o:["Menit","Jam","Sekon","Hari"],a:2,p:"Satuan SI untuk waktu adalah sekon atau detik (s)."},
      {lv:1,q:"Jumlah besaran pokok dalam Sistem Internasional adalah...",o:["5","6","9","7"],a:3,p:"Ada 7 besaran pokok: panjang, massa, waktu, suhu, kuat arus listrik, intensitas cahaya, dan jumlah zat."},
      {lv:1,q:"Satuan SI untuk besaran kuat arus listrik adalah...",o:["Volt","Ampere","Ohm","Watt"],a:1,p:"Kuat arus listrik adalah besaran pokok dengan satuan ampere (A)."},
      {lv:1,q:"Alat yang digunakan untuk mengukur massa benda adalah...",o:["Termometer","Mistar","Neraca (timbangan)","Stopwatch"],a:2,p:"Massa diukur dengan neraca. Termometer untuk suhu, mistar untuk panjang, stopwatch untuk waktu."},
      {lv:1,q:"Berikut ini yang termasuk besaran turunan adalah...",o:["Kecepatan","Panjang","Massa","Waktu"],a:0,p:"Kecepatan diturunkan dari panjang dibagi waktu, sehingga termasuk besaran turunan."},
      {lv:2,q:"Waktu 3 jam sama dengan ... sekon.",o:["1.080","10.800","180","3.600"],a:1,p:"1 jam = 3.600 sekon, sehingga 3 jam = 3 x 3.600 = 10.800 sekon."},
      {lv:2,q:"Massa 500 gram sama dengan ... kilogram.",o:["5","50","0,05","0,5"],a:3,p:"1 kg = 1.000 g, sehingga 500 g = 500 : 1.000 = 0,5 kg."},
      {lv:2,q:"Satuan SI untuk besaran luas adalah...",o:["m","m³","kg","m²"],a:3,p:"Luas = panjang x lebar, sehingga satuannya meter x meter = m²."},
      {lv:2,q:"Ketelitian mistar (penggaris) yang biasa digunakan di sekolah adalah...",o:["0,1 mm","1 mm atau 0,1 cm","0,01 mm","1 cm"],a:1,p:"Skala terkecil mistar adalah 1 mm. Jangka sorong 0,1 mm dan mikrometer sekrup 0,01 mm."},
      {lv:2,q:"Suhu 25 °C jika dinyatakan dalam kelvin adalah...",o:["298 K","248 K","273 K","325 K"],a:0,p:"Suhu kelvin = suhu Celsius + 273, jadi 25 + 273 = 298 K."},
      {lv:2,q:"Volume air 2 liter sama dengan ... cm³.",o:["200","20","2.000","20.000"],a:2,p:"1 liter = 1 dm³ = 1.000 cm³, sehingga 2 liter = 2.000 cm³."},
      {lv:3,q:"Satuan gaya newton (N) jika dinyatakan dalam satuan besaran pokok adalah...",o:["kg·m/s","kg·m/s²","kg/m³","m/s²"],a:1,p:"Gaya = massa x percepatan. Satuannya kg x m/s² = kg·m/s²."},
      {lv:3,q:"Sebuah balok memiliki panjang 2 m, lebar 50 cm, dan tinggi 20 cm. Volume balok dalam satuan m³ adalah...",o:["2 m³","20 m³","0,02 m³","0,2 m³"],a:3,p:"Ubah ke meter: 50 cm = 0,5 m dan 20 cm = 0,2 m. Volume = 2 x 0,5 x 0,2 = 0,2 m³."},
      {lv:3,q:"Pada pengukuran dengan jangka sorong berketelitian 0,01 cm, skala utama menunjukkan 2,3 cm dan garis nonius ke-6 berimpit dengan skala utama. Hasil pengukurannya adalah...",o:["2,30 cm","2,9 cm","2,36 cm","2,306 cm"],a:2,p:"Hasil = skala utama + (nonius x ketelitian) = 2,3 + (6 x 0,01) = 2,3 + 0,06 = 2,36 cm."},
      {lv:3,q:"Sebuah benda bermassa 600 gram dan volumenya 200 cm³. Massa jenis benda tersebut dalam satuan SI adalah...",o:["3.000 kg/m³","3 kg/m³","300 kg/m³","30.000 kg/m³"],a:0,p:"Massa jenis = 600 g : 200 cm³ = 3 g/cm³. Karena 1 g/cm³ = 1.000 kg/m³, hasilnya 3.000 kg/m³."},
      {lv:3,q:"Sebuah sepeda motor melaju dengan kecepatan 15 m/s. Kecepatan tersebut sama dengan...",o:["54 km/jam","15 km/jam","4,17 km/jam","540 km/jam"],a:0,p:"15 m/s = 15 x 3.600 m per jam = 54.000 m/jam = 54 km/jam (atau 15 x 3,6 = 54)."},
      {lv:3,q:"Seorang siswa mengukur panjang pensil sebanyak lima kali dan memperoleh hasil 12,1 cm; 12,3 cm; 12,2 cm; 12,2 cm; dan 12,2 cm. Nilai rata-rata hasil pengukurannya adalah...",o:["12,1 cm","12,3 cm","61,0 cm","12,2 cm"],a:3,p:"Jumlahkan: 12,1 + 12,3 + 12,2 + 12,2 + 12,2 = 61,0. Rata-rata = 61,0 : 5 = 12,2 cm."},
      {lv:3,q:"Perhatikan pasangan besaran dan satuan berikut: (1) suhu - kelvin, (2) massa - newton, (3) waktu - sekon, (4) intensitas cahaya - kandela. Pasangan yang benar menurut SI adalah...",o:["(1), (2), dan (3)","(1), (3), dan (4)","(2) dan (4)","(1), (2), (3), dan (4)"],a:1,p:"Satuan SI massa adalah kilogram, bukan newton. Newton adalah satuan gaya. Pasangan lainnya benar."},
      {lv:3,q:"Gelas ukur berisi 50 mL air. Setelah sebuah batu dimasukkan dan tenggelam seluruhnya, permukaan air naik menjadi 72 mL. Volume batu tersebut adalah...",o:["72 cm³","50 cm³","22 cm³","122 cm³"],a:2,p:"Volume batu = volume akhir - volume awal = 72 - 50 = 22 mL. Karena 1 mL = 1 cm³, volume batu 22 cm³."}
    ],
    "ipa-k7-1": [
      {lv:1,q:"Tingkat takson yang paling rendah dan paling khusus adalah...",o:["Spesies","Kingdom","Kelas","Ordo"],a:0,p:"Spesies adalah takson terendah. Anggota satu spesies memiliki persamaan ciri paling banyak."},
      {lv:1,q:"Ciri makhluk hidup berupa pertambahan ukuran tubuh, seperti menjadi lebih tinggi dan lebih besar, disebut...",o:["Bernapas","Iritabilitas","Tumbuh","Ekskresi"],a:2,p:"Tumbuh adalah bertambahnya ukuran tubuh makhluk hidup yang tidak dapat kembali seperti semula."},
      {lv:1,q:"Kelompok hewan yang memiliki tulang belakang disebut...",o:["Invertebrata","Protista","Monera","Vertebrata"],a:3,p:"Vertebrata berarti hewan bertulang belakang, misalnya ikan, katak, kadal, burung, dan kucing."},
      {lv:1,q:"Tumbuhan berbiji yang bijinya terlindung di dalam daging buah disebut...",o:["Gymnospermae (berbiji terbuka)","Angiospermae (berbiji tertutup)","Pteridophyta (paku)","Bryophyta (lumut)"],a:1,p:"Pada Angiospermae, bakal biji terlindung di dalam bakal buah, misalnya mangga dan jeruk."},
      {lv:1,q:"Jumlah kaki pada hewan serangga (Insecta) adalah...",o:["8 kaki","4 kaki","6 kaki (tiga pasang)","10 kaki"],a:2,p:"Serangga seperti semut, kupu-kupu, dan belalang memiliki tiga pasang atau enam kaki."},
      {lv:1,q:"Tujuan utama klasifikasi makhluk hidup adalah...",o:["Memudahkan mengenali dan mempelajari makhluk hidup yang sangat beragam","Membuat semua makhluk hidup menjadi sama","Mengurangi jumlah makhluk hidup","Menentukan makhluk hidup yang harus dimusnahkan"],a:0,p:"Dengan mengelompokkan makhluk hidup berdasarkan persamaan ciri, kita lebih mudah mengenali dan mempelajarinya."},
      {lv:2,q:"Laba-laba tidak termasuk serangga karena...",o:["Memiliki sayap","Memiliki 8 kaki dan tubuhnya terbagi menjadi 2 bagian","Memiliki 6 kaki","Memiliki tulang belakang"],a:1,p:"Serangga berkaki 6 dengan tubuh 3 bagian. Laba-laba berkaki 8 dengan tubuh 2 bagian, sehingga termasuk kelompok Arachnida."},
      {lv:2,q:"Kelompok hewan yang berdarah dingin, kulitnya bersisik kering, bernapas dengan paru-paru, dan umumnya bertelur di darat adalah...",o:["Amfibi","Mamalia","Aves (burung)","Reptil"],a:3,p:"Ciri tersebut dimiliki reptil, misalnya kadal, ular, dan penyu."},
      {lv:2,q:"Ciri tumbuhan monokotil (berkeping satu) adalah...",o:["Berakar tunggang, tulang daun menyirip, dan bijinya berkeping dua","Tidak memiliki akar, batang, dan daun sejati","Berkembang biak hanya dengan spora","Berakar serabut, tulang daun sejajar atau melengkung, dan bijinya berkeping satu"],a:3,p:"Monokotil seperti padi, jagung, dan kelapa berakar serabut dengan tulang daun sejajar atau melengkung."},
      {lv:2,q:"Pohon pinus dan melinjo termasuk kelompok tumbuhan...",o:["Angiospermae (berbiji tertutup)","Gymnospermae (berbiji terbuka)","Paku-pakuan","Lumut"],a:1,p:"Biji pinus dan melinjo tidak terbungkus daging buah sejati, sehingga termasuk tumbuhan berbiji terbuka."},
      {lv:2,q:"Nama ilmiah padi adalah Oryza sativa. Kata Oryza pada nama tersebut menunjukkan tingkat takson...",o:["Genus","Spesies","Famili","Kelas"],a:0,p:"Dalam tata nama ganda, kata pertama adalah nama genus dan kata kedua adalah penunjuk spesies."},
      {lv:2,q:"Katak digolongkan ke dalam kelompok amfibi karena...",o:["Tubuhnya bersisik keras","Menyusui anaknya","Dapat hidup di dua alam: saat berudu di air dan saat dewasa dapat hidup di darat","Tubuhnya ditutupi bulu"],a:2,p:"Amfibi berarti hidup di dua alam. Berudu bernapas dengan insang di air, katak dewasa bernapas dengan paru-paru dan kulit."},
      {lv:3,q:"Semakin rendah tingkat takson suatu kelompok makhluk hidup, maka...",o:["Jumlah anggotanya semakin banyak dan persamaan cirinya semakin banyak","Jumlah anggotanya semakin sedikit dan persamaan cirinya semakin banyak","Jumlah anggotanya semakin banyak dan persamaan cirinya semakin sedikit","Jumlah anggota dan persamaan cirinya tidak berubah"],a:1,p:"Takson rendah seperti genus dan spesies berisi makhluk yang sangat mirip, sehingga anggotanya sedikit tetapi persamaannya banyak."},
      {lv:3,q:"Paus hidup di laut dan bentuknya mirip ikan, tetapi digolongkan sebagai mamalia. Alasan yang tepat adalah...",o:["Paus memiliki sirip","Paus hidup di dalam air","Paus bertelur di laut","Paus bernapas dengan paru-paru, melahirkan, dan menyusui anaknya"],a:3,p:"Ciri utama mamalia adalah menyusui, melahirkan, dan bernapas dengan paru-paru. Paus memiliki semua ciri itu."},
      {lv:3,q:"Perhatikan kunci determinasi berikut. 1a. Memiliki sayap ... ke nomor 2. 1b. Tidak memiliki sayap ... kucing. 2a. Bertelur dan tubuh berbulu ... ayam. 2b. Melahirkan dan menyusui ... kelelawar. Hewan dengan kode 1a - 2b adalah...",o:["Ayam","Kucing","Kelelawar","Burung merpati"],a:2,p:"Kode 1a berarti bersayap, lalu lanjut ke nomor 2. Kode 2b berarti melahirkan dan menyusui, yaitu kelelawar."},
      {lv:3,q:"Kucing rumah memiliki nama ilmiah Felis catus, sedangkan harimau Panthera tigris. Keduanya termasuk famili Felidae. Tingkat takson terendah yang sama-sama dimiliki keduanya adalah...",o:["Famili","Genus","Spesies","Ordo"],a:0,p:"Nama genus keduanya berbeda (Felis dan Panthera), jadi takson terendah yang sama adalah famili Felidae."},
      {lv:3,q:"Ali menemukan tumbuhan yang tidak berbunga, sudah memiliki akar, batang, dan daun sejati, serta terdapat bintik-bintik cokelat di bagian bawah daunnya. Tumbuhan tersebut termasuk...",o:["Tumbuhan paku","Tumbuhan lumut","Tumbuhan berbiji tertutup","Jamur"],a:0,p:"Bintik cokelat di bawah daun adalah kumpulan kotak spora. Ditambah akar, batang, dan daun sejati, ini ciri tumbuhan paku."},
      {lv:3,q:"Mengapa virus tidak dimasukkan ke dalam salah satu kingdom makhluk hidup?",o:["Virus tersusun atas banyak sel","Virus dapat berfotosintesis","Ukuran virus lebih besar daripada bakteri","Virus tidak tersusun atas sel dan hanya dapat berkembang biak di dalam sel makhluk hidup lain"],a:3,p:"Klasifikasi kingdom didasarkan pada sel. Virus tidak memiliki sel dan tidak dapat memperbanyak diri tanpa sel inang."},
      {lv:3,q:"Dari hewan laut berikut: lumba-lumba, hiu, penyu, dan penguin, yang termasuk kelompok ikan (Pisces) adalah...",o:["Lumba-lumba, karena hidup di laut","Hiu, karena bernapas dengan insang dan bergerak dengan sirip","Penyu, karena pandai berenang","Penguin, karena hidup di air dingin"],a:1,p:"Hiu bernapas dengan insang seperti ikan lain. Lumba-lumba mamalia, penyu reptil, dan penguin burung."},
      {lv:3,q:"Euglena memiliki klorofil sehingga dapat berfotosintesis seperti tumbuhan, tetapi juga dapat bergerak aktif dengan bulu cambuk seperti hewan. Euglena dikelompokkan ke dalam kingdom...",o:["Plantae","Animalia","Protista","Fungi"],a:2,p:"Euglena bersel satu, memiliki inti sel, dan memiliki ciri tumbuhan sekaligus hewan. Makhluk seperti ini dimasukkan ke Protista."}
    ],
    "ipa-k7-2": [
      {lv:1,q:"Contoh peristiwa yang termasuk perubahan fisika adalah...",o:["Es mencair","Kayu terbakar","Besi berkarat","Nasi menjadi basi"],a:0,p:"Es mencair hanya berubah wujud menjadi air, tidak terbentuk zat baru."},
      {lv:1,q:"Contoh peristiwa yang termasuk perubahan kimia adalah...",o:["Kertas dirobek","Air membeku","Kayu terbakar menjadi arang","Garam larut dalam air"],a:2,p:"Pembakaran kayu menghasilkan zat baru seperti arang, abu, dan asap."},
      {lv:1,q:"Zat tunggal yang tidak dapat diuraikan lagi menjadi zat lain yang lebih sederhana dengan reaksi kimia biasa disebut...",o:["Senyawa","Campuran","Larutan","Unsur"],a:3,p:"Unsur adalah zat paling sederhana, misalnya besi, emas, dan oksigen."},
      {lv:1,q:"Air murni (H₂O) termasuk golongan...",o:["Unsur","Senyawa","Campuran","Larutan"],a:1,p:"Air tersusun atas unsur hidrogen dan oksigen yang bergabung secara kimia dengan perbandingan tetap, sehingga termasuk senyawa."},
      {lv:1,q:"Contoh zat yang termasuk campuran adalah...",o:["Air murni","Emas murni","Udara","Gas oksigen"],a:2,p:"Udara adalah campuran berbagai gas seperti nitrogen, oksigen, dan karbon dioksida."},
      {lv:1,q:"Sifat zat yang dapat diamati tanpa mengubah jenis zat, misalnya warna, bau, dan titik didih, disebut...",o:["Sifat fisika","Sifat kimia","Reaksi kimia","Perubahan kimia"],a:0,p:"Sifat fisika dapat diamati atau diukur tanpa membentuk zat baru."},
      {lv:2,q:"Ketika cuka dicampur dengan soda kue, muncul banyak buih. Buih tersebut merupakan tanda terjadinya reaksi kimia berupa...",o:["Terbentuknya cahaya","Terbentuknya gas","Perubahan wujud cair menjadi padat","Hilangnya massa zat"],a:1,p:"Cuka bereaksi dengan soda kue menghasilkan gas karbon dioksida yang tampak sebagai gelembung."},
      {lv:2,q:"Cara paling sederhana untuk memisahkan pasir dari air keruh sehingga pasir tertahan dan air lewat adalah...",o:["Penyulingan (distilasi)","Kromatografi","Sublimasi","Penyaringan (filtrasi)"],a:3,p:"Penyaringan memisahkan zat padat yang tidak larut, seperti pasir, dari zat cair dengan kertas saring atau kain."},
      {lv:2,q:"Air garam dipanaskan, lalu uapnya didinginkan sehingga diperoleh air tawar murni. Cara pemisahan ini disebut...",o:["Penyaringan (filtrasi)","Kromatografi","Sublimasi","Penyulingan (distilasi)"],a:3,p:"Distilasi memisahkan zat berdasarkan perbedaan titik didih. Air menguap, lalu diembunkan kembali, sedangkan garam tertinggal."},
      {lv:2,q:"Perkaratan besi paling cepat terjadi jika besi berada di tempat...",o:["Kering dan tertutup rapat","Lembap yang mengandung air dan oksigen","Yang dilapisi cat","Yang direndam dalam minyak"],a:1,p:"Karat terbentuk ketika besi bereaksi dengan oksigen dengan bantuan air. Tempat lembap mempercepat proses ini."},
      {lv:2,q:"Singkong yang difermentasi menjadi tape rasanya berubah menjadi manis dan sedikit beralkohol. Peristiwa ini termasuk...",o:["Perubahan kimia, karena terbentuk zat baru","Perubahan fisika, karena hanya bentuknya berubah","Perubahan wujud dari padat menjadi cair","Peristiwa yang tidak mengubah zat sama sekali"],a:0,p:"Ragi mengubah zat tepung singkong menjadi gula dan alkohol. Terbentuknya zat baru menunjukkan perubahan kimia."},
      {lv:2,q:"Perhatikan peristiwa berikut: (1) gula larut dalam teh, (2) telur digoreng, (3) gelas kaca pecah, (4) kembang api meledak. Peristiwa yang termasuk perubahan kimia ditunjukkan oleh nomor...",o:["(1) dan (3)","(1) dan (2)","(2) dan (4)","(3) dan (4)"],a:2,p:"Telur goreng dan kembang api membentuk zat baru. Gula larut dan kaca pecah hanya perubahan fisika."},
      {lv:3,q:"Pak Budi ingin pagar besinya tidak mudah berkarat. Tindakan yang paling tepat adalah...",o:["Menyiram pagar dengan air setiap hari","Mengecat pagar agar besi tidak bersentuhan langsung dengan air dan udara","Menyimpan pagar di tempat yang lembap","Menggosok pagar dengan garam"],a:1,p:"Cat menjadi lapisan pelindung yang menghalangi oksigen dan air mencapai besi, sehingga reaksi perkaratan terhambat."},
      {lv:3,q:"Soda kue dan cuka dimasukkan ke dalam botol, lalu mulut botol segera ditutup dengan balon. Beberapa saat kemudian balon mengembang. Kesimpulan yang paling tepat adalah...",o:["Udara di dalam botol memuai karena dipanaskan","Hanya terjadi perubahan wujud cuka menjadi gas","Balon menarik udara dari luar botol","Terjadi reaksi kimia yang menghasilkan gas karbon dioksida"],a:3,p:"Reaksi soda kue dan cuka menghasilkan gas baru. Gas inilah yang mengisi dan mengembangkan balon."},
      {lv:3,q:"Seorang siswa ingin mengetahui warna-warna penyusun tinta spidol hitam. Cara pemisahan yang paling tepat adalah...",o:["Penyaringan","Distilasi","Kromatografi kertas","Sublimasi"],a:2,p:"Pada kromatografi, zat warna terbawa pelarut dengan kecepatan berbeda sehingga terpisah menjadi beberapa warna di kertas."},
      {lv:3,q:"Campuran kapur barus dan pasir dapat dipisahkan dengan cara...",o:["Sublimasi, karena kapur barus menyublim jika dipanaskan sedangkan pasir tidak","Penyaringan, karena kapur barus larut dalam pasir","Distilasi, karena pasir mudah mendidih","Menggunakan magnet, karena kapur barus tertarik magnet"],a:0,p:"Saat dipanaskan, kapur barus langsung berubah menjadi gas lalu dapat dikumpulkan kembali sebagai padatan. Pasir tertinggal."},
      {lv:3,q:"Selembar kertas dibakar dan sisa abunya jauh lebih ringan daripada kertas semula. Penjelasan yang paling tepat adalah...",o:["Sebagian zat berubah menjadi gas seperti karbon dioksida dan uap air yang lepas ke udara","Massa kertas hilang lenyap begitu saja","Abu selalu lebih ringan karena tidak memiliki massa","Kertas hanya menguap tanpa terjadi reaksi kimia"],a:0,p:"Massa tidak hilang. Pembakaran menghasilkan gas yang terlepas ke udara, sehingga yang tertinggal hanya abu yang ringan."},
      {lv:3,q:"Natrium adalah logam yang sangat reaktif dan klorin adalah gas beracun. Namun, keduanya bergabung membentuk garam dapur (NaCl) yang aman dimakan. Hal ini menunjukkan bahwa...",o:["Sifat senyawa selalu sama dengan sifat unsur penyusunnya","Garam dapur adalah campuran biasa","Natrium dan klorin tetap memiliki sifat aslinya di dalam garam","Sifat senyawa berbeda dengan sifat unsur-unsur penyusunnya"],a:3,p:"Ketika unsur bergabung secara kimia membentuk senyawa, terbentuk zat baru dengan sifat yang berbeda."},
      {lv:3,q:"Air laut digolongkan sebagai campuran, bukan senyawa. Alasan yang tepat adalah...",o:["Air laut memiliki rumus kimia yang tetap","Komponennya masih memiliki sifat aslinya dan dapat dipisahkan secara fisika, misalnya dengan penguapan","Komponen air laut tidak dapat dipisahkan sama sekali","Air laut hanya tersusun atas satu jenis atom"],a:1,p:"Air laut tetap terasa asin (sifat garam) dan garamnya bisa diperoleh dengan menguapkan air. Ini ciri campuran."},
      {lv:3,q:"Telur yang sudah direbus tidak dapat dikembalikan menjadi telur mentah. Hal ini menunjukkan bahwa perubahan kimia umumnya...",o:["Dapat balik dengan mudah jika didinginkan","Hanya merupakan perubahan wujud","Tidak dapat balik karena susunan zatnya sudah berubah","Tidak menghasilkan zat baru"],a:2,p:"Panas mengubah susunan protein telur menjadi zat baru yang padat. Zat baru ini tidak dapat kembali seperti semula."}
    ],
    "ipa-k8-0": [
      {lv:1,q:"Gaya yang arahnya selalu berlawanan dengan arah gerak benda ketika dua permukaan bersentuhan disebut gaya...",o:["Gesek","Normal","Berat","Pegas"],a:0,p:"Gaya gesek muncul antara dua permukaan yang bersentuhan dan selalu melawan arah gerak."},
      {lv:1,q:"Berat suatu benda adalah gaya yang timbul akibat...",o:["Besarnya volume benda","Gesekan benda dengan lantai","Tarikan gravitasi bumi pada massa benda","Dorongan udara pada benda"],a:2,p:"Berat adalah gaya gravitasi yang bekerja pada benda. Karena itu berat dinyatakan dalam newton."},
      {lv:1,q:"Rumus untuk menghitung berat benda (w) jika massanya m dan percepatan gravitasinya g adalah...",o:["w = m : g","w = g : m","w = m + g","w = m x g"],a:3,p:"Berat sama dengan massa dikali percepatan gravitasi."},
      {lv:1,q:"Menurut Hukum III Newton, gaya aksi dan gaya reaksi memiliki besar yang ... dan arah yang ...",o:["Berbeda; sama","Sama; berlawanan","Sama; sama","Berbeda; berlawanan"],a:1,p:"Pasangan aksi-reaksi selalu sama besar, berlawanan arah, dan bekerja pada dua benda yang berbeda."},
      {lv:1,q:"Alat yang digunakan untuk mengukur besar gaya adalah...",o:["Termometer","Barometer","Neraca pegas (dinamometer)","Amperemeter"],a:2,p:"Neraca pegas menunjukkan besar gaya dari pertambahan panjang pegasnya, dalam satuan newton."},
      {lv:1,q:"Gaya yang diberikan oleh permukaan bidang dan arahnya tegak lurus terhadap bidang tersebut disebut gaya...",o:["Normal","Gesek","Berat","Tarik"],a:0,p:"Gaya normal adalah gaya dorong dari permukaan tempat benda berada, arahnya tegak lurus bidang."},
      {lv:2,q:"Sebuah tas bermassa 5 kg. Jika percepatan gravitasi 10 m/s², berat tas tersebut adalah...",o:["5 N","50 N","0,5 N","500 N"],a:1,p:"w = m x g = 5 kg x 10 m/s² = 50 N."},
      {lv:2,q:"Sebuah kotak ditarik dengan gaya 20 N ke kanan dan 8 N ke kiri. Resultan gaya pada kotak adalah...",o:["28 N ke kanan","12 N ke kiri","28 N ke kiri","12 N ke kanan"],a:3,p:"Gaya berlawanan arah dikurangkan: 20 - 8 = 12 N, arahnya mengikuti gaya yang lebih besar, yaitu ke kanan."},
      {lv:2,q:"Gaya sebesar 60 N bekerja pada benda bermassa 12 kg di atas lantai licin. Percepatan benda adalah...",o:["720 m/s²","0,2 m/s²","48 m/s²","5 m/s²"],a:3,p:"a = F : m = 60 N : 12 kg = 5 m/s²."},
      {lv:2,q:"Jalan menanjak yang licin sering ditaburi pasir atau kerikil. Tujuannya adalah...",o:["Memperkecil gaya gesek agar kendaraan lebih cepat","Memperbesar gaya gesek agar ban kendaraan tidak selip","Menambah berat kendaraan","Menghilangkan gaya gravitasi"],a:1,p:"Pasir membuat permukaan jalan lebih kasar. Gaya gesek yang lebih besar membantu ban mencengkeram jalan."},
      {lv:2,q:"Contoh peristiwa yang paling sesuai dengan Hukum II Newton adalah...",o:["Gerobak kosong lebih mudah dipercepat daripada gerobak penuh jika didorong dengan gaya yang sama","Penumpang terdorong ke depan saat bus mengerem mendadak","Senapan terdorong ke belakang saat peluru ditembakkan","Buku tetap diam di atas meja"],a:0,p:"Hukum II: percepatan berbanding terbalik dengan massa. Gerobak kosong bermassa kecil sehingga percepatannya lebih besar."},
      {lv:2,q:"Seorang astronaut bermassa 60 kg berada di Bulan yang percepatan gravitasinya 1,6 m/s². Massa dan berat astronaut di Bulan adalah...",o:["Massa 96 kg, berat 60 N","Massa 10 kg, berat 96 N","Massa 60 kg, berat 96 N","Massa 60 kg, berat 600 N"],a:2,p:"Massa tidak berubah di mana pun, tetap 60 kg. Berat = 60 x 1,6 = 96 N."},
      {lv:3,q:"Sebuah balok bermassa 4 kg ditarik dengan gaya 30 N di atas lantai kasar. Gaya gesek yang melawan gerak balok sebesar 10 N. Percepatan balok adalah...",o:["7,5 m/s²","5 m/s²","10 m/s²","2,5 m/s²"],a:1,p:"Resultan gaya = 30 - 10 = 20 N. a = 20 N : 4 kg = 5 m/s²."},
      {lv:3,q:"Seseorang bermassa 50 kg berdiri di dalam lift yang bergerak naik dengan percepatan 2 m/s² (g = 10 m/s²). Gaya normal lantai lift pada orang tersebut adalah...",o:["500 N","400 N","100 N","600 N"],a:3,p:"Saat lift dipercepat ke atas: N - w = m x a, sehingga N = m(g + a) = 50 x (10 + 2) = 600 N."},
      {lv:3,q:"Mobil bermassa 1.200 kg melaju 20 m/s, lalu direm hingga berhenti dalam 4 sekon. Besar gaya pengereman rata-rata adalah...",o:["4.800 N","24.000 N","6.000 N","3.000 N"],a:2,p:"Perlambatan a = (0 - 20) : 4 = -5 m/s². Besar gaya F = m x a = 1.200 x 5 = 6.000 N."},
      {lv:3,q:"Gaya F yang bekerja pada benda bermassa m menghasilkan percepatan a. Jika gayanya diubah menjadi 3F dan massanya menjadi setengah m, percepatan benda menjadi...",o:["6a","1,5a","3a","2/3 a"],a:0,p:"a = F/m. Percepatan baru = 3F : (m/2) = 6F/m = 6a."},
      {lv:3,q:"Sebuah lemari bermassa 10 kg didorong dengan gaya 50 N, tetapi lemari tetap diam. Besar gaya gesek yang bekerja pada lemari saat itu adalah...",o:["50 N, berlawanan arah dengan dorongan","0 N, karena lemari diam","100 N, searah dengan dorongan","500 N, berlawanan arah dengan dorongan"],a:0,p:"Lemari diam berarti resultan gayanya nol. Gaya gesek statis harus mengimbangi dorongan, yaitu 50 N berlawanan arah."},
      {lv:3,q:"Andi (40 kg) dan Budi (50 kg) berdiri di atas lantai yang sangat licin, lalu saling mendorong. Pernyataan yang benar adalah...",o:["Budi mendapat gaya lebih besar karena massanya lebih besar","Andi mendapat gaya lebih besar karena ia lebih ringan","Percepatan keduanya sama besar","Gaya yang dialami keduanya sama besar, tetapi percepatan Andi lebih besar karena massanya lebih kecil"],a:3,p:"Menurut Hukum III, gaya aksi-reaksi sama besar. Menurut Hukum II, a = F/m, sehingga yang bermassa lebih kecil mendapat percepatan lebih besar."},
      {lv:3,q:"Sebuah benda bermassa 2 kg bergerak lurus dengan kecepatan tetap 3 m/s. Besar resultan gaya yang bekerja pada benda tersebut adalah...",o:["6 N","0 N","1,5 N","20 N"],a:1,p:"Kecepatan tetap berarti percepatan nol. Menurut Hukum I Newton, resultan gayanya juga nol."},
      {lv:3,q:"Dua balok bermassa 3 kg dan 5 kg dihubungkan dengan tali di atas lantai licin, lalu ditarik bersama dengan gaya 40 N. Percepatan kedua balok adalah...",o:["8 m/s²","13,3 m/s²","5 m/s²","3,2 m/s²"],a:2,p:"Kedua balok bergerak bersama sebagai satu sistem bermassa 3 + 5 = 8 kg. a = 40 N : 8 kg = 5 m/s²."}
    ],
    "ipa-k8-1": [
      {lv:1,q:"Enzim yang terdapat di dalam air liur adalah...",o:["Ptialin (amilase ludah)","Pepsin","Lipase","Tripsin"],a:0,p:"Kelenjar ludah menghasilkan ptialin yang mulai mencerna amilum di dalam mulut."},
      {lv:1,q:"Organ yang menghasilkan getah empedu adalah...",o:["Pankreas","Lambung","Hati","Usus besar"],a:2,p:"Empedu dibuat oleh hati, lalu disimpan sementara di kantong empedu sebelum dialirkan ke usus dua belas jari."},
      {lv:1,q:"Gigi yang berfungsi untuk memotong makanan adalah...",o:["Gigi geraham","Gigi taring","Akar gigi","Gigi seri"],a:3,p:"Gigi seri berbentuk pipih dan tajam di bagian depan sehingga cocok untuk memotong makanan."},
      {lv:1,q:"Sisa makanan yang tidak dicerna dikeluarkan dari tubuh melalui...",o:["Mulut","Anus","Lambung","Usus halus"],a:1,p:"Sisa makanan dibentuk menjadi feses di usus besar, lalu dikeluarkan melalui anus."},
      {lv:1,q:"Zat makanan yang menjadi sumber energi utama bagi tubuh adalah...",o:["Vitamin","Mineral","Karbohidrat","Air"],a:2,p:"Karbohidrat, seperti nasi dan roti, dipecah menjadi glukosa yang dipakai sel sebagai sumber energi utama."},
      {lv:1,q:"Bagian usus halus yang terutama berfungsi menyerap sari makanan adalah...",o:["Usus penyerapan (ileum)","Usus dua belas jari (duodenum)","Usus kosong (jejunum)","Usus besar (kolon)"],a:0,p:"Usus halus terdiri dari duodenum, jejunum, dan ileum. Penyerapan sari makanan terutama terjadi di ileum."},
      {lv:2,q:"Contoh pencernaan secara mekanik adalah...",o:["Ptialin mengubah amilum menjadi maltosa","Gigi mengunyah makanan menjadi potongan kecil","Pepsin mengubah protein menjadi pepton","Lipase mengubah lemak menjadi asam lemak"],a:1,p:"Pencernaan mekanik mengubah ukuran makanan tanpa enzim. Tiga pilihan lain melibatkan enzim, sehingga termasuk pencernaan kimiawi."},
      {lv:2,q:"Asam klorida (HCl) di dalam lambung berfungsi untuk...",o:["Mengemulsikan lemak","Menyerap air dari sisa makanan","Menghasilkan getah empedu","Membunuh kuman dan mengubah pepsinogen menjadi pepsin"],a:3,p:"HCl membuat lambung sangat asam sehingga kuman mati. HCl juga mengaktifkan pepsinogen menjadi enzim pepsin."},
      {lv:2,q:"Enzim tripsin yang dihasilkan pankreas berfungsi mencerna...",o:["Amilum menjadi maltosa","Lemak menjadi asam lemak dan gliserol","Vitamin menjadi mineral","Protein menjadi peptida yang lebih sederhana"],a:3,p:"Tripsin adalah enzim pemecah protein yang bekerja di usus halus."},
      {lv:2,q:"Hasil akhir pencernaan karbohidrat yang diserap oleh usus halus adalah...",o:["Asam amino","Glukosa","Asam lemak","Gliserol"],a:1,p:"Karbohidrat dipecah hingga menjadi gula sederhana, terutama glukosa. Asam amino hasil protein, asam lemak dan gliserol hasil lemak."},
      {lv:2,q:"Dinding usus halus memiliki banyak jonjot usus (vili). Fungsi jonjot usus adalah...",o:["Memperluas permukaan penyerapan sari makanan","Menghasilkan enzim pepsin","Menghancurkan makanan secara mekanik","Menyimpan feses sebelum dikeluarkan"],a:0,p:"Lipatan kecil berupa vili membuat permukaan usus sangat luas sehingga penyerapan sari makanan lebih banyak."},
      {lv:2,q:"Dalam uji makanan, sebuah bahan berubah warna menjadi biru kehitaman setelah ditetesi larutan iodin (lugol). Bahan tersebut mengandung...",o:["Protein","Lemak","Amilum","Glukosa"],a:2,p:"Iodin bereaksi dengan amilum (zat tepung) dan menghasilkan warna biru kehitaman."},
      {lv:3,q:"Seorang siswa meneteskan larutan biuret pada putih telur, lalu warnanya berubah menjadi ungu. Kesimpulan yang tepat adalah...",o:["Putih telur mengandung amilum","Putih telur mengandung protein","Putih telur mengandung glukosa","Putih telur mengandung lemak"],a:1,p:"Biuret dipakai untuk menguji protein. Warna ungu menandakan adanya protein."},
      {lv:3,q:"Larutan X ditetesi pereaksi Benedict lalu dipanaskan, dan warnanya berubah menjadi merah bata. Larutan X kemungkinan besar mengandung...",o:["Protein","Amilum","Lemak","Glukosa (gula reduksi)"],a:3,p:"Benedict yang dipanaskan bersama gula reduksi seperti glukosa akan berubah menjadi hijau, jingga, hingga merah bata."},
      {lv:3,q:"Seseorang yang kantong empedunya telah diangkat melalui operasi dianjurkan mengurangi makanan berlemak. Alasan yang tepat adalah...",o:["Lambung tidak dapat lagi menghasilkan HCl","Amilum tidak dapat dicerna di mulut","Pengemulsian lemak di usus menjadi kurang optimal sehingga lemak sulit dicerna","Protein tidak dapat diserap usus"],a:2,p:"Empedu memecah lemak menjadi butiran kecil agar mudah dicerna lipase. Tanpa kantong empedu, empedu tidak tersimpan untuk dikeluarkan sekaligus saat makan berlemak."},
      {lv:3,q:"Penderita diare dianjurkan minum oralit. Alasan yang paling tepat adalah...",o:["Mengganti air dan garam mineral yang banyak hilang bersama feses yang encer","Membunuh semua bakteri di usus","Membuat usus berhenti bekerja","Menambah enzim pencernaan di lambung"],a:0,p:"Saat diare, banyak air dan garam mineral terbuang. Oralit membantu mencegah kekurangan cairan (dehidrasi)."},
      {lv:3,q:"Sepotong roti yang ditelan akan melewati saluran pencernaan dengan urutan...",o:["Mulut - kerongkongan - lambung - usus halus - usus besar - anus","Mulut - lambung - kerongkongan - usus halus - usus besar - anus","Mulut - kerongkongan - usus halus - lambung - usus besar - anus","Mulut - kerongkongan - lambung - usus besar - usus halus - anus"],a:0,p:"Makanan dari mulut turun melalui kerongkongan ke lambung, lalu ke usus halus, usus besar, dan sisanya keluar lewat anus."},
      {lv:3,q:"Lambung menghasilkan pepsin yang mencerna protein dan asam yang sangat kuat. Mengapa dinding lambung yang juga tersusun dari protein tidak ikut tercerna?",o:["Dinding lambung tersusun atas lemak murni","Pepsin hanya bekerja di dalam mulut","Asam lambung bersifat basa","Dinding lambung dilindungi lapisan lendir (mukus) yang tebal"],a:3,p:"Lendir melapisi dinding lambung sehingga asam dan pepsin tidak langsung mengenai sel-sel dinding lambung."},
      {lv:3,q:"Makanan dari lambung yang sangat asam masuk ke usus dua belas jari, padahal enzim di usus bekerja baik pada suasana basa lemah. Zat yang menetralkan keasaman tersebut adalah...",o:["Asam klorida dari lambung","Natrium bikarbonat dalam getah pankreas","Enzim ptialin dari air liur","Air yang diserap usus besar"],a:1,p:"Getah pankreas mengandung natrium bikarbonat yang bersifat basa, sehingga dapat menetralkan asam dari lambung."},
      {lv:3,q:"Jika jonjot usus (vili) seseorang rusak akibat suatu penyakit, akibat yang paling mungkin terjadi adalah...",o:["Makanan tidak dapat dikunyah di mulut","Lambung berhenti menghasilkan asam","Penyerapan sari makanan berkurang sehingga tubuh dapat kekurangan gizi walaupun banyak makan","Feses menjadi lebih sedikit mengandung air"],a:2,p:"Vili memperluas permukaan penyerapan. Jika rusak, sari makanan yang terserap ke darah berkurang."}
    ],
    "ipa-k8-2": [
      {lv:1,q:"Rumus tekanan pada zat padat adalah...",o:["P = F : A","P = F x A","P = A : F","P = m x g"],a:0,p:"Tekanan adalah gaya tekan (F) dibagi luas bidang tekan (A)."},
      {lv:1,q:"Satuan SI untuk tekanan adalah...",o:["Newton","Joule","Pascal (N/m²)","Watt"],a:2,p:"1 pascal sama dengan gaya 1 newton yang bekerja pada luas 1 m²."},
      {lv:1,q:"Menurut Hukum Archimedes, besar gaya ke atas yang dialami benda di dalam zat cair sama dengan...",o:["Massa benda di udara","Volume wadah zat cair","Tekanan udara di atas permukaan","Berat zat cair yang dipindahkan benda"],a:3,p:"Benda yang tercelup memindahkan sejumlah zat cair. Gaya apungnya sama dengan berat zat cair yang dipindahkan itu."},
      {lv:1,q:"Dibandingkan dengan di tepi pantai, tekanan udara di puncak gunung adalah...",o:["Lebih tinggi","Lebih rendah","Sama besar","Nol"],a:1,p:"Semakin tinggi tempat, semakin sedikit udara di atasnya, sehingga tekanan udara makin kecil."},
      {lv:1,q:"Contoh alat yang bekerja berdasarkan Hukum Pascal adalah...",o:["Kapal selam","Balon udara","Rem hidrolik","Barometer"],a:2,p:"Rem hidrolik meneruskan tekanan dari pedal melalui minyak rem ke semua roda dengan sama besar."},
      {lv:1,q:"Pisau yang tajam lebih mudah memotong daripada pisau tumpul karena...",o:["Luas bidang tekannya kecil sehingga tekanannya besar","Luas bidang tekannya besar sehingga tekanannya besar","Pisau tajam lebih ringan","Pisau tajam memiliki gaya gesek lebih besar"],a:0,p:"Dengan gaya yang sama, bidang tekan yang kecil menghasilkan tekanan yang lebih besar."},
      {lv:2,q:"Sebuah peti dengan berat 120 N diletakkan di lantai. Luas alas peti 0,4 m². Tekanan peti terhadap lantai adalah...",o:["48 Pa","300 Pa","3.000 Pa","30 Pa"],a:1,p:"P = F : A = 120 N : 0,4 m² = 300 Pa."},
      {lv:2,q:"Besar tekanan hidrostatis pada kedalaman 2 m di dalam air (ρ = 1.000 kg/m³, g = 10 m/s²) adalah...",o:["2.000 Pa","200 Pa","5.000 Pa","20.000 Pa"],a:3,p:"P = ρ x g x h = 1.000 x 10 x 2 = 20.000 Pa."},
      {lv:2,q:"Dinding bendungan dibuat lebih tebal di bagian bawah daripada di bagian atas. Alasannya adalah...",o:["Tekanan air makin kecil pada tempat yang makin dalam","Bagian atas bendungan menahan tekanan terbesar","Air di bagian bawah lebih ringan","Tekanan air makin besar pada tempat yang makin dalam"],a:3,p:"Tekanan hidrostatis sebanding dengan kedalaman. Bagian bawah bendungan menahan tekanan paling besar sehingga dibuat paling tebal."},
      {lv:2,q:"Kapal laut terbuat dari besi yang massa jenisnya lebih besar daripada air, tetapi kapal dapat terapung. Hal ini karena...",o:["Besi kapal lebih ringan daripada air","Badan kapal berongga sehingga memindahkan banyak air dan gaya apungnya mampu mengimbangi berat kapal","Air mendorong kapal ke bawah","Kapal tidak memiliki berat"],a:1,p:"Bentuk berongga membuat volume air yang dipindahkan besar. Gaya apung yang besar dapat menahan berat kapal."},
      {lv:2,q:"Air dari akar dapat naik hingga ke daun yang tinggi. Hal ini dibantu oleh...",o:["Daya kapilaritas pembuluh kayu dan tekanan akar","Gaya magnet bumi","Gaya gesek antara daun dan udara","Tekanan hidrostatis air laut"],a:0,p:"Pembuluh kayu (xilem) sangat sempit sehingga air naik karena kapilaritas, dibantu tekanan akar dan penguapan di daun."},
      {lv:2,q:"Kita dapat meminum air dengan sedotan karena...",o:["Air dapat naik sendiri tanpa ada gaya","Tekanan udara di dalam sedotan bertambah saat diisap","Tekanan udara di dalam sedotan berkurang saat diisap, sehingga tekanan udara luar mendorong air naik","Sedotan menarik air dengan gaya magnet"],a:2,p:"Saat diisap, udara di sedotan berkurang. Tekanan udara luar yang lebih besar menekan permukaan air sehingga air naik."},
      {lv:3,q:"Sebuah dongkrak hidrolik memiliki luas pengisap kecil 10 cm² dan luas pengisap besar 500 cm². Gaya yang diperlukan pada pengisap kecil untuk mengangkat mobil seberat 10.000 N adalah...",o:["500.000 N","200 N","50 N","2.000 N"],a:1,p:"Menurut Pascal, F1/A1 = F2/A2. F1 = 10.000 x 10 : 500 = 200 N."},
      {lv:3,q:"Seorang penyelam turun dari kedalaman 5 m ke kedalaman 15 m di dalam air (ρ = 1.000 kg/m³, g = 10 m/s²). Pertambahan tekanan hidrostatis yang dialaminya adalah...",o:["150.000 Pa","50.000 Pa","200.000 Pa","100.000 Pa"],a:3,p:"Selisih kedalaman = 15 - 5 = 10 m. ΔP = ρ x g x Δh = 1.000 x 10 x 10 = 100.000 Pa."},
      {lv:3,q:"Sebuah balok bermassa 2 kg berukuran 20 cm x 10 cm x 5 cm diletakkan di lantai (g = 10 m/s²). Tekanan terbesar yang dapat dihasilkan balok pada lantai adalah...",o:["1.000 Pa","2.000 Pa","4.000 Pa","400 Pa"],a:2,p:"Berat = 2 x 10 = 20 N. Tekanan terbesar terjadi pada alas terkecil: 10 cm x 5 cm = 50 cm² = 0,005 m². P = 20 : 0,005 = 4.000 Pa."},
      {lv:3,q:"Sebuah benda bervolume 500 cm³ dan bermassa 400 g dimasukkan ke dalam air (massa jenis air 1 g/cm³). Keadaan benda tersebut adalah...",o:["Terapung, karena massa jenisnya 0,8 g/cm³ lebih kecil dari air","Tenggelam, karena massa jenisnya 1,25 g/cm³ lebih besar dari air","Melayang, karena massa jenisnya sama dengan air","Tenggelam, karena massanya 400 g"],a:0,p:"Massa jenis benda = 400 : 500 = 0,8 g/cm³. Karena lebih kecil dari massa jenis air, benda terapung."},
      {lv:3,q:"Sebutir telur tenggelam di dalam segelas air tawar. Setelah banyak garam dilarutkan ke dalam air, telur itu naik dan terapung. Penjelasan yang tepat adalah...",o:["Massa jenis air garam bertambah sehingga gaya apung pada telur bertambah","Massa telur berkurang karena garam","Garam mengurangi volume telur","Gaya gravitasi pada telur hilang"],a:0,p:"Gaya apung = ρ zat cair x g x V tercelup. Air garam lebih besar massa jenisnya sehingga gaya apungnya cukup untuk mengangkat telur."},
      {lv:3,q:"Sebuah balok bervolume 0,003 m³ terapung di air dengan setengah volumenya tercelup (ρ air = 1.000 kg/m³, g = 10 m/s²). Besar gaya apung yang dialami balok adalah...",o:["30 N","3 N","60 N","15 N"],a:3,p:"Volume tercelup = 0,003 : 2 = 0,0015 m³. Gaya apung = 1.000 x 10 x 0,0015 = 15 N."},
      {lv:3,q:"Gas di dalam tabung bervolume 4 liter memiliki tekanan 1 atm. Gas tersebut ditekan sehingga volumenya menjadi 2 liter pada suhu tetap. Tekanan gas sekarang adalah...",o:["0,5 atm","2 atm","4 atm","1 atm"],a:1,p:"Menurut Hukum Boyle, P1 x V1 = P2 x V2. 1 x 4 = P2 x 2, sehingga P2 = 2 atm."},
      {lv:3,q:"Kaleng susu kental manis lebih mudah dituang jika diberi dua lubang daripada satu lubang. Penjelasan yang tepat adalah...",o:["Lubang kedua membuat susu menjadi lebih encer","Lubang kedua mengurangi berat susu","Udara dapat masuk melalui lubang kedua sehingga tekanan di dalam kaleng tetap sama dengan tekanan udara luar","Lubang kedua membuat tekanan udara luar menjadi nol"],a:2,p:"Dengan satu lubang, tekanan di dalam kaleng turun saat susu keluar dan menahan aliran. Lubang kedua membuat udara masuk menggantikan susu."}
    ],
    "ipa-k9-0": [
      {lv:1,q:"Alat yang digunakan untuk mengukur kuat arus listrik adalah...",o:["Amperemeter","Voltmeter","Ohmmeter","Termometer"],a:0,p:"Amperemeter mengukur kuat arus dalam satuan ampere."},
      {lv:1,q:"Satuan SI untuk hambatan listrik adalah...",o:["Volt","Ampere","Ohm","Coulomb"],a:2,p:"Hambatan listrik dinyatakan dalam ohm (Ω)."},
      {lv:1,q:"Arus listrik mengalir dari titik yang potensialnya...",o:["Rendah ke titik yang potensialnya tinggi","Sama ke titik yang potensialnya sama","Nol ke titik yang potensialnya nol","Tinggi ke titik yang potensialnya rendah"],a:3,p:"Arus listrik mengalir karena ada beda potensial, dari potensial tinggi (kutub positif) ke potensial rendah (kutub negatif)."},
      {lv:1,q:"Cara memasang amperemeter untuk mengukur arus yang melewati sebuah lampu adalah...",o:["Paralel dengan lampu","Seri dengan lampu","Di luar rangkaian","Terbalik tanpa kabel"],a:1,p:"Amperemeter harus dilalui arus yang sama dengan lampu, sehingga dipasang seri."},
      {lv:1,q:"Satuan energi listrik yang digunakan PLN dalam rekening listrik adalah...",o:["Volt","Ampere","kWh (kilowatt jam)","Ohm"],a:2,p:"PLN menghitung pemakaian energi listrik dalam kWh, yaitu daya 1.000 watt yang dipakai selama 1 jam."},
      {lv:1,q:"Rumus daya listrik (P) jika diketahui tegangan (V) dan kuat arus (I) adalah...",o:["P = V x I","P = V : I","P = I : V","P = V + I"],a:0,p:"Daya listrik adalah hasil kali tegangan dan kuat arus, dengan satuan watt."},
      {lv:2,q:"Sebuah lampu 60 W dinyalakan selama 5 jam. Energi listrik yang digunakan adalah...",o:["300 kWh","0,3 kWh","12 kWh","3 kWh"],a:1,p:"W = P x t = 60 W x 5 jam = 300 Wh = 0,3 kWh."},
      {lv:2,q:"Hambatan sebesar 30 Ω dialiri arus 0,5 A. Tegangan pada hambatan tersebut adalah...",o:["60 V","30,5 V","0,017 V","15 V"],a:3,p:"V = I x R = 0,5 A x 30 Ω = 15 V."},
      {lv:2,q:"Sebuah alat listrik bekerja pada tegangan 220 V dan dialiri arus 2 A. Daya alat tersebut adalah...",o:["110 W","222 W","0,009 W","440 W"],a:3,p:"P = V x I = 220 x 2 = 440 W."},
      {lv:2,q:"Hambatan 20 Ω dan 30 Ω disusun paralel. Hambatan penggantinya adalah...",o:["50 Ω","12 Ω","10 Ω","25 Ω"],a:1,p:"1/R = 1/20 + 1/30 = 3/60 + 2/60 = 5/60, sehingga R = 60 : 5 = 12 Ω."},
      {lv:2,q:"Kawat penghantar dari bahan yang sama akan memiliki hambatan paling besar jika kawat tersebut...",o:["Panjang dan luas penampangnya kecil","Pendek dan luas penampangnya besar","Panjang dan luas penampangnya besar","Pendek dan luas penampangnya kecil"],a:0,p:"Hambatan kawat sebanding dengan panjang dan berbanding terbalik dengan luas penampang. Kawat panjang dan tipis paling besar hambatannya."},
      {lv:2,q:"Arus listrik 0,5 A mengalir pada sebuah kawat selama 1 menit. Besar muatan listrik yang mengalir adalah...",o:["0,5 C","120 C","30 C","3 C"],a:2,p:"Q = I x t = 0,5 A x 60 s = 30 coulomb."},
      {lv:3,q:"Sebuah rumah menyalakan 4 lampu 25 W selama 10 jam sehari dan sebuah TV 100 W selama 5 jam sehari. Jika tarif listrik Rp1.500/kWh, biaya listrik untuk 30 hari adalah...",o:["Rp45.000","Rp67.500","Rp2.250","Rp22.500"],a:1,p:"Energi per hari = (4 x 25 x 10) + (100 x 5) = 1.000 + 500 = 1.500 Wh = 1,5 kWh. 30 hari = 45 kWh. Biaya = 45 x 1.500 = Rp67.500."},
      {lv:3,q:"Hambatan 4 Ω disusun seri dengan rangkaian paralel 6 Ω dan 3 Ω, lalu dihubungkan ke sumber tegangan 12 V. Tegangan pada hambatan 4 Ω adalah...",o:["4 V","12 V","2 V","8 V"],a:3,p:"Paralel 6 Ω dan 3 Ω = (6 x 3) : (6 + 3) = 2 Ω. Total = 4 + 2 = 6 Ω. I = 12 : 6 = 2 A. Tegangan pada 4 Ω = 2 x 4 = 8 V."},
      {lv:3,q:"Sebuah lampu bertuliskan 220 V / 40 W dipasang pada tegangan 110 V. Daya yang digunakan lampu sekarang adalah...",o:["20 W","40 W","10 W","80 W"],a:2,p:"Hambatan lampu tetap. P sebanding dengan V². Karena tegangan menjadi setengahnya, daya menjadi (1/2)² x 40 = 10 W."},
      {lv:3,q:"Sebuah kawat memiliki hambatan R. Kawat itu dipotong menjadi dua bagian sama panjang, lalu kedua potongan disusun paralel. Hambatan penggantinya menjadi...",o:["R/4","R/2","R","2R"],a:0,p:"Setiap potongan berhambatan R/2. Dua hambatan R/2 yang diparalel menghasilkan (R/2) : 2 = R/4."},
      {lv:3,q:"Pada percobaan hukum Ohm, sebuah resistor dialiri arus 0,3 A saat diberi tegangan 6 V. Jika tegangan dinaikkan menjadi 9 V, kuat arusnya menjadi...",o:["0,45 A","0,2 A","0,6 A","1,5 A"],a:0,p:"R = 6 : 0,3 = 20 Ω. Pada 9 V, I = 9 : 20 = 0,45 A."},
      {lv:3,q:"Dua lampu identik, masing-masing berhambatan 6 Ω, disusun seri dan dihubungkan dengan sumber 12 V. Daya yang digunakan oleh setiap lampu adalah...",o:["12 W","24 W","3 W","6 W"],a:3,p:"Hambatan total 12 Ω, sehingga I = 12 : 12 = 1 A. Daya tiap lampu P = I² x R = 1² x 6 = 6 W."},
      {lv:3,q:"Sebuah rumah menggunakan pengaman (MCB) 5 A pada tegangan 220 V. Daya total maksimum alat listrik yang dapat dinyalakan bersamaan tanpa membuat MCB turun adalah...",o:["44 W","1.100 W","225 W","2.200 W"],a:1,p:"P maksimum = V x I = 220 x 5 = 1.100 W. Jika daya total melebihi ini, arus melebihi 5 A dan MCB memutus aliran."},
      {lv:3,q:"Lampu LED 10 W menghasilkan terang yang setara dengan lampu pijar 60 W. Jika lampu dinyalakan 6 jam sehari selama 30 hari, energi yang dihemat dengan memakai LED adalah...",o:["1,8 kWh","10,8 kWh","9 kWh","50 kWh"],a:2,p:"Selisih daya = 60 - 10 = 50 W. Energi hemat = 50 W x 6 jam x 30 hari = 9.000 Wh = 9 kWh."}
    ],
    "ipa-k9-1": [
      {lv:1,q:"Struktur di dalam inti sel yang membawa gen disebut...",o:["Kromosom","Ribosom","Mitokondria","Membran sel"],a:0,p:"Gen terletak pada kromosom yang berada di dalam inti sel."},
      {lv:1,q:"Sifat yang muncul dan menutupi sifat pasangannya disebut sifat...",o:["Resesif","Intermediet","Dominan","Heterozigot"],a:2,p:"Sifat dominan akan tampak walaupun hanya ada satu alel dominan, misalnya Aa."},
      {lv:1,q:"Pasangan alel yang sama, misalnya AA atau aa, disebut...",o:["Heterozigot","Fenotipe","Gamet","Homozigot"],a:3,p:"Homo berarti sama. Individu homozigot memiliki dua alel yang sama untuk suatu sifat."},
      {lv:1,q:"Persilangan dengan satu sifat beda disebut persilangan...",o:["Dihibrid","Monohibrid","Trihibrid","Resiprok"],a:1,p:"Mono berarti satu. Monohibrid adalah persilangan yang memperhatikan satu sifat beda, misalnya warna bunga."},
      {lv:1,q:"Sel kelamin seperti sel sperma dan sel telur disebut...",o:["Zigot","Gen","Gamet","Alel"],a:2,p:"Gamet adalah sel kelamin yang membawa setengah jumlah kromosom induknya."},
      {lv:1,q:"Hasil peleburan sel sperma dan sel telur disebut...",o:["Zigot","Gamet","Kromosom","Alel"],a:0,p:"Saat pembuahan, sperma dan sel telur melebur membentuk zigot yang akan tumbuh menjadi individu baru."},
      {lv:2,q:"Tanaman batang tinggi (T) dominan terhadap batang pendek (t). Jika tanaman Tt disilangkan dengan tt, persentase keturunan berbatang pendek adalah...",o:["25%","50%","75%","0%"],a:1,p:"Tt x tt menghasilkan Tt dan tt dengan perbandingan 1 : 1. Jadi keturunan pendek (tt) = 50%."},
      {lv:2,q:"Perbandingan genotipe keturunan dari persilangan Aa x Aa adalah...",o:["3 AA : 1 aa","1 Aa : 1 aa","9 : 3 : 3 : 1","1 AA : 2 Aa : 1 aa"],a:3,p:"Gamet A dan a dari kedua induk menghasilkan AA, Aa, Aa, aa. Jadi perbandingannya 1 : 2 : 1."},
      {lv:2,q:"Macam gamet yang dapat dibentuk oleh individu bergenotipe AaBB adalah...",o:["AB, Ab, aB, dan ab","A, a, dan B","AB saja","AB dan aB"],a:3,p:"Alel A atau a dipasangkan dengan B (karena BB). Gamet yang terbentuk hanya AB dan aB."},
      {lv:2,q:"Susunan kromosom kelamin pada laki-laki adalah...",o:["XX","XY","YY","XXY"],a:1,p:"Laki-laki memiliki satu kromosom X dan satu kromosom Y, sedangkan perempuan memiliki dua kromosom X."},
      {lv:2,q:"Bunga merah (MM) disilangkan dengan bunga putih (mm) dan menghasilkan F1 berwarna merah muda (intermediet). Jika F1 disilangkan sesamanya, perbandingan fenotipe F2 adalah...",o:["1 merah : 2 merah muda : 1 putih","3 merah : 1 putih","1 merah : 1 putih","9 merah : 7 putih"],a:0,p:"Mm x Mm menghasilkan MM : Mm : mm = 1 : 2 : 1. Pada sifat intermediet, Mm tampak merah muda."},
      {lv:2,q:"Peluang sepasang suami istri memperoleh anak laki-laki pada setiap kelahiran adalah...",o:["25%","75%","50%","100%"],a:2,p:"Ibu selalu memberi X, sedangkan ayah memberi X atau Y dengan peluang sama. Peluang XY (laki-laki) = 1/2 = 50%."},
      {lv:3,q:"Biji bulat (B) dominan terhadap kisut (b), warna kuning (K) dominan terhadap hijau (k). Persilangan BbKk x BbKk menghasilkan 320 tanaman. Jumlah tanaman berbiji bulat hijau adalah...",o:["180 tanaman","60 tanaman","20 tanaman","90 tanaman"],a:1,p:"Perbandingan fenotipe dihibrid 9 : 3 : 3 : 1. Bulat hijau (B_kk) = 3/16. Jumlahnya 3/16 x 320 = 60 tanaman."},
      {lv:3,q:"Seekor kelinci berbulu hitam (sifat dominan) yang genotipenya belum diketahui disilangkan dengan kelinci berbulu putih (homozigot resesif). Keturunannya 50% hitam dan 50% putih. Genotipe kelinci hitam tersebut adalah...",o:["Homozigot dominan (HH)","Homozigot resesif (hh)","Tidak dapat ditentukan sama sekali","Heterozigot (Hh)"],a:3,p:"Jika kelinci hitam HH, semua anak akan hitam. Munculnya anak putih (hh) berarti kelinci hitam membawa alel h, jadi genotipenya Hh."},
      {lv:3,q:"Seorang ayah bergolongan darah AB dan ibu bergolongan darah O. Kemungkinan golongan darah anak-anak mereka adalah...",o:["AB atau O","A, B, AB, atau O","A atau B","Hanya O"],a:2,p:"Ayah memberi alel IA atau IB, ibu selalu memberi i. Anak bergenotipe IAi (A) atau IBi (B)."},
      {lv:3,q:"Seorang ibu berpenglihatan normal pembawa sifat buta warna (XᶜX) menikah dengan laki-laki berpenglihatan normal (XY). Peluang lahirnya anak laki-laki buta warna dari seluruh kemungkinan anak adalah...",o:["25%","50%","0%","75%"],a:0,p:"Kemungkinan anak: XᶜX, XX, XᶜY, XY. Hanya XᶜY yang laki-laki buta warna, yaitu 1 dari 4 = 25%."},
      {lv:3,q:"Anak kembar identik memiliki sifat yang sangat mirip. Penjelasan yang tepat adalah...",o:["Keduanya berasal dari satu zigot yang membelah sehingga memiliki gen yang sama","Keduanya berasal dari dua sel telur yang dibuahi dua sperma","Keduanya dibesarkan di rumah yang sama","Keduanya lahir pada hari yang sama"],a:0,p:"Kembar identik terbentuk dari satu zigot yang kemudian terpisah menjadi dua embrio, sehingga susunan gennya sama."},
      {lv:3,q:"Bunga merah (M) dominan penuh terhadap bunga putih (m). Suatu persilangan menghasilkan keturunan 50% merah dan 50% putih. Genotipe kedua induknya adalah...",o:["MM x mm","Mm x Mm","MM x MM","Mm x mm"],a:3,p:"Mm x mm menghasilkan Mm (merah) dan mm (putih) dengan perbandingan 1 : 1. Persilangan lain tidak menghasilkan 50% putih."},
      {lv:3,q:"Petani memiliki padi A yang hasil panennya banyak tetapi tidak tahan hama, dan padi B yang tahan hama tetapi hasil panennya sedikit. Tujuan petani menyilangkan kedua padi tersebut adalah...",o:["Mendapatkan padi yang hasilnya sedikit dan tidak tahan hama","Mendapatkan varietas baru yang hasil panennya banyak sekaligus tahan hama","Membuat padi berhenti berbuah","Mengubah padi menjadi tanaman jagung"],a:1,p:"Persilangan dapat menggabungkan sifat unggul dari kedua induk dalam satu keturunan, sehingga diperoleh bibit unggul."},
      {lv:3,q:"Manakah dari ciri berikut yang BUKAN merupakan sifat yang diwariskan dari orang tua?",o:["Golongan darah","Bentuk rambut keriting","Otot lengan yang besar karena rajin berlatih angkat beban","Warna bola mata"],a:2,p:"Otot yang membesar karena latihan dipengaruhi lingkungan dan tidak tersimpan dalam gen, sehingga tidak diturunkan."}
    ],
    "ipa-k9-2": [
      {lv:1,q:"Magnet batang yang digantung bebas dan dibiarkan diam akan menunjuk ke arah...",o:["Utara dan selatan","Timur dan barat","Atas dan bawah","Arah yang selalu berubah-ubah"],a:0,p:"Magnet bebas dipengaruhi medan magnet bumi sehingga selalu menunjuk arah utara-selatan."},
      {lv:1,q:"Alat penunjuk arah yang memanfaatkan jarum magnet adalah...",o:["Termometer","Barometer","Kompas","Higrometer"],a:2,p:"Jarum magnet pada kompas selalu menunjuk utara-selatan, sehingga dapat dipakai untuk menentukan arah."},
      {lv:1,q:"Benda berikut yang tidak dapat ditarik oleh magnet adalah...",o:["Paku besi","Jarum jahit baja","Mur besi","Pensil kayu"],a:3,p:"Kayu adalah bahan nonmagnetik. Besi dan baja tertarik kuat oleh magnet."},
      {lv:1,q:"Di luar magnet, garis-garis gaya magnet keluar dari kutub...",o:["Selatan menuju kutub utara","Utara menuju kutub selatan","Tengah magnet menuju kedua kutub","Kedua kutub menuju tengah magnet"],a:1,p:"Garis gaya magnet di luar magnet digambarkan keluar dari kutub utara dan masuk ke kutub selatan."},
      {lv:1,q:"Daerah di sekitar magnet yang masih dipengaruhi oleh gaya magnet disebut...",o:["Kutub magnet","Inti magnet","Medan magnet","Garis khatulistiwa"],a:2,p:"Medan magnet adalah ruang di sekitar magnet tempat gaya magnet masih bekerja."},
      {lv:1,q:"Alat yang digunakan untuk menaikkan atau menurunkan tegangan listrik bolak-balik (AC) adalah...",o:["Transformator","Generator","Motor listrik","Baterai"],a:0,p:"Transformator (trafo) mengubah besar tegangan listrik AC berdasarkan induksi elektromagnetik."},
      {lv:2,q:"Cara yang dapat menghilangkan sifat kemagnetan sebuah magnet adalah...",o:["Menggosoknya satu arah dengan magnet lain","Memanaskan atau memukul-mukul magnet","Melilitkan kawat berarus searah di sekelilingnya","Menyimpannya berpasangan dengan kutub berlawanan"],a:1,p:"Panas dan pukulan mengacaukan susunan magnet elementer di dalamnya sehingga sifat magnetnya melemah atau hilang."},
      {lv:2,q:"Kekuatan sebuah elektromagnet dapat diperbesar dengan cara...",o:["Mengurangi jumlah lilitan","Mengganti inti besi dengan kayu","Memperkecil arus listrik","Menambah jumlah lilitan dan memperbesar arus listrik"],a:3,p:"Medan magnet kumparan makin kuat jika lilitannya makin banyak, arusnya makin besar, dan intinya dari besi lunak."},
      {lv:2,q:"Ciri transformator step-up adalah...",o:["Jumlah lilitan sekunder lebih sedikit daripada primer","Tegangan sekunder lebih kecil daripada primer","Jumlah lilitan primer dan sekunder sama","Jumlah lilitan sekunder lebih banyak dan tegangan sekunder lebih besar daripada primer"],a:3,p:"Trafo step-up menaikkan tegangan. Karena Vs/Vp = Ns/Np, lilitan sekundernya lebih banyak."},
      {lv:2,q:"Alat berikut yang bekerja dengan memanfaatkan elektromagnet adalah...",o:["Setrika listrik","Bel listrik","Lampu pijar","Kompor gas"],a:1,p:"Bel listrik memakai elektromagnet yang menarik dan melepas pemukul secara berulang sehingga bel berbunyi."},
      {lv:2,q:"Generator mengubah energi gerak menjadi energi listrik berdasarkan prinsip...",o:["Induksi elektromagnetik","Gaya Lorentz pada motor listrik","Hukum Ohm","Gaya gravitasi"],a:0,p:"Pada generator, kumparan berputar di dalam medan magnet. Perubahan medan magnet menimbulkan arus induksi."},
      {lv:2,q:"Bumi bersifat seperti magnet raksasa. Kutub utara jarum kompas menunjuk ke arah utara geografis karena di dekat kutub utara geografis terdapat...",o:["Kutub utara magnet bumi","Garis khatulistiwa magnet","Kutub selatan magnet bumi","Daerah tanpa medan magnet"],a:2,p:"Kutub yang berbeda saling tarik. Kutub utara jarum tertarik ke kutub selatan magnet bumi, yang letaknya dekat kutub utara geografis."},
      {lv:3,q:"Sebuah transformator memiliki 1.000 lilitan primer dan 50 lilitan sekunder. Jika tegangan primernya 220 V, tegangan sekundernya adalah...",o:["4.400 V","11 V","220 V","22 V"],a:1,p:"Vs = Vp x Ns/Np = 220 x 50 : 1.000 = 11 V. Ini trafo step-down."},
      {lv:3,q:"Sebuah trafo ideal menurunkan tegangan dari 220 V menjadi 11 V. Jika arus sekundernya 2 A, arus primernya adalah...",o:["40 A","2 A","0,5 A","0,1 A"],a:3,p:"Pada trafo ideal, Vp x Ip = Vs x Is. Ip = 11 x 2 : 220 = 0,1 A."},
      {lv:3,q:"Kawat sepanjang 50 cm dialiri arus 5 A dan berada tegak lurus di dalam medan magnet 0,4 T. Besar gaya Lorentz pada kawat adalah...",o:["10 N","100 N","1 N","0,1 N"],a:2,p:"F = B x I x L = 0,4 x 5 x 0,5 = 1 N. Panjang kawat harus diubah ke meter (50 cm = 0,5 m)."},
      {lv:3,q:"Sebuah transformator menerima daya primer 200 W dan menghasilkan daya sekunder 150 W. Efisiensi transformator tersebut adalah...",o:["75%","133%","50%","25%"],a:0,p:"Efisiensi = (Ps : Pp) x 100% = (150 : 200) x 100% = 75%. Sisanya hilang sebagai panas."},
      {lv:3,q:"Sebuah magnet batang digerakkan keluar-masuk kumparan yang dihubungkan ke galvanometer, dan jarum galvanometer menyimpang. Jika magnet dibiarkan diam di dalam kumparan, jarum galvanometer akan...",o:["Tidak menyimpang, karena tidak ada perubahan medan magnet pada kumparan","Terus menyimpang ke kanan","Menyimpang makin jauh","Bergetar dengan cepat"],a:0,p:"Arus induksi hanya timbul jika jumlah garis gaya magnet yang melewati kumparan berubah. Magnet yang diam tidak menimbulkan perubahan."},
      {lv:3,q:"PLN menaikkan tegangan listrik menjadi sangat tinggi sebelum menyalurkannya melalui kabel jarak jauh. Tujuan utamanya adalah...",o:["Memperbesar arus agar listrik lebih cepat sampai","Membuat kabel menjadi lebih dingin tanpa alasan","Mengubah listrik AC menjadi DC","Memperkecil arus sehingga energi yang hilang menjadi panas di kabel lebih sedikit"],a:3,p:"Untuk daya yang sama, tegangan tinggi berarti arus kecil. Energi panas yang hilang di kabel bergantung pada kuadrat arus, sehingga kerugian berkurang."},
      {lv:3,q:"Sebuah magnet batang dipotong menjadi dua bagian. Hasil yang benar adalah...",o:["Satu potongan hanya kutub utara, potongan lain hanya kutub selatan","Setiap potongan menjadi magnet baru yang memiliki kutub utara dan kutub selatan","Kedua potongan kehilangan sifat magnetnya","Kedua potongan hanya memiliki kutub utara"],a:1,p:"Magnet tersusun dari magnet-magnet elementer yang searah. Setiap potongan tetap memiliki dua kutub."},
      {lv:3,q:"Seorang siswa ingin membuat motor listrik sederhana berputar lebih cepat. Cara yang paling tepat adalah...",o:["Memperkecil arus listrik","Mengganti kumparan kawat dengan benang","Memperbesar arus listrik dan memakai magnet yang lebih kuat","Melepas magnet dari motor"],a:2,p:"Gaya Lorentz pada kumparan sebanding dengan kuat medan magnet, arus, dan panjang kawat. Gaya yang lebih besar membuat putaran lebih cepat."}
    ],
    "ipa-k10-0": [
      {lv:1,q:"Rumus jarak yang ditempuh benda yang bergerak lurus beraturan (GLB) adalah...",o:["s = v x t","s = v : t","s = t : v","s = v + t"],a:0,p:"Pada GLB kecepatannya tetap, sehingga jarak = kecepatan x waktu."},
      {lv:1,q:"Kelajuan termasuk besaran skalar, sedangkan kecepatan termasuk besaran...",o:["Skalar","Pokok","Vektor","Tak bersatuan"],a:2,p:"Kecepatan memiliki nilai dan arah, sehingga termasuk besaran vektor."},
      {lv:1,q:"Gerak buah kelapa yang jatuh bebas dari pohonnya termasuk...",o:["GLB","GLBB diperlambat","Gerak melingkar beraturan","GLBB dipercepat"],a:3,p:"Benda jatuh bebas mendapat percepatan gravitasi yang tetap, sehingga kecepatannya bertambah secara teratur."},
      {lv:1,q:"Grafik kecepatan terhadap waktu (v-t) untuk benda yang bergerak lurus beraturan berbentuk...",o:["Garis lurus miring ke atas","Garis lurus mendatar","Parabola","Lingkaran"],a:1,p:"Pada GLB kecepatan selalu sama di setiap waktu, sehingga grafik v-t berupa garis mendatar."},
      {lv:1,q:"Rumus kecepatan akhir pada gerak lurus berubah beraturan (GLBB) adalah...",o:["vt = v0 - t : a","vt = a : t","vt = v0 + a x t","vt = v0 x a"],a:2,p:"Kecepatan bertambah sebesar a setiap sekon, sehingga setelah t sekon kecepatannya v0 + a x t."},
      {lv:1,q:"Sebuah bola dilempar vertikal ke atas. Kecepatan bola tepat di titik tertinggi adalah...",o:["Nol","Maksimum","Sama dengan kecepatan awal","Sama dengan percepatan gravitasi"],a:0,p:"Bola terus diperlambat gravitasi hingga berhenti sesaat di titik tertinggi, lalu jatuh kembali."},
      {lv:2,q:"Ali berjalan 4 m ke timur, lalu 3 m ke utara. Jarak dan perpindahan Ali adalah...",o:["Jarak 5 m, perpindahan 7 m","Jarak 7 m, perpindahan 5 m","Jarak 7 m, perpindahan 7 m","Jarak 5 m, perpindahan 5 m"],a:1,p:"Jarak = 4 + 3 = 7 m. Perpindahan adalah garis lurus dari awal ke akhir: √(4² + 3²) = √25 = 5 m."},
      {lv:2,q:"Sebuah bus menempuh jarak 120 km dalam waktu 2,5 jam. Kelajuan rata-rata bus adalah...",o:["300 km/jam","60 km/jam","50 km/jam","48 km/jam"],a:3,p:"Kelajuan rata-rata = jarak : waktu = 120 : 2,5 = 48 km/jam."},
      {lv:2,q:"Sebuah batu jatuh bebas dari keadaan diam (g = 10 m/s²). Kecepatan batu setelah 2 sekon adalah...",o:["5 m/s","10 m/s","40 m/s","20 m/s"],a:3,p:"v = g x t = 10 x 2 = 20 m/s."},
      {lv:2,q:"Sebuah benda dijatuhkan bebas dari keadaan diam (g = 10 m/s²). Jarak yang ditempuh benda dalam 3 sekon pertama adalah...",o:["30 m","45 m","90 m","15 m"],a:1,p:"h = 1/2 x g x t² = 1/2 x 10 x 3² = 5 x 9 = 45 m."},
      {lv:2,q:"Sebuah mobil melaju dengan kecepatan tetap 54 km/jam. Jarak yang ditempuh mobil dalam 20 sekon adalah...",o:["300 m","1.080 m","270 m","150 m"],a:0,p:"54 km/jam = 54 : 3,6 = 15 m/s. Jarak = 15 x 20 = 300 m."},
      {lv:2,q:"Sebuah bola dilempar vertikal ke atas dengan kecepatan awal 20 m/s (g = 10 m/s²). Waktu yang diperlukan bola untuk mencapai titik tertinggi adalah...",o:["4 s","20 s","2 s","0,5 s"],a:2,p:"Di titik tertinggi v = 0. t = v0 : g = 20 : 10 = 2 s."},
      {lv:3,q:"Sebuah bola dilempar vertikal ke atas dengan kecepatan awal 20 m/s (g = 10 m/s²). Ketinggian maksimum yang dicapai bola adalah...",o:["40 m","20 m","10 m","200 m"],a:1,p:"h maks = v0² : (2g) = 400 : 20 = 20 m."},
      {lv:3,q:"Sebuah mobil dipercepat beraturan dari 10 m/s menjadi 30 m/s dalam waktu 5 sekon. Jarak yang ditempuh mobil selama itu adalah...",o:["150 m","200 m","50 m","100 m"],a:3,p:"Pada GLBB, s = (v0 + vt) : 2 x t = (10 + 30) : 2 x 5 = 20 x 5 = 100 m."},
      {lv:3,q:"Mobil A dan mobil B mula-mula berjarak 700 m dan bergerak saling mendekat pada lintasan lurus. Kecepatan tetap A 20 m/s dan B 15 m/s. Kedua mobil bertemu setelah...",o:["35 s","46,7 s","20 s","10 s"],a:2,p:"Karena saling mendekat, jarak berkurang 20 + 15 = 35 m setiap sekon. t = 700 : 35 = 20 s."},
      {lv:3,q:"Sebuah benda bergerak dari diam dan dipercepat beraturan hingga kecepatannya 12 m/s pada detik ke-4, lalu bergerak dengan kecepatan tetap 12 m/s sampai detik ke-10. Jarak total yang ditempuh benda adalah...",o:["96 m","120 m","72 m","48 m"],a:0,p:"Jarak = luas di bawah grafik v-t. Bagian segitiga: 1/2 x 4 x 12 = 24 m. Bagian persegi panjang: 6 x 12 = 72 m. Total 96 m."},
      {lv:3,q:"Sebuah batu dijatuhkan bebas dari ketinggian 80 m (g = 10 m/s²). Kecepatan batu tepat saat menyentuh tanah adalah...",o:["40 m/s","80 m/s","16 m/s","4 m/s"],a:0,p:"v² = 2 x g x h = 2 x 10 x 80 = 1.600, sehingga v = 40 m/s. (Waktunya t = √(2h/g) = 4 s.)"},
      {lv:3,q:"Seorang pengendara melaju 20 m/s dan melihat rintangan. Ia baru mulai mengerem 0,5 s kemudian (waktu reaksi), lalu mobil diperlambat 5 m/s² hingga berhenti. Jarak total dari saat melihat rintangan hingga berhenti adalah...",o:["40 m","10 m","90 m","50 m"],a:3,p:"Selama reaksi: 20 x 0,5 = 10 m. Saat mengerem: v0² : (2a) = 400 : 10 = 40 m. Total = 10 + 40 = 50 m."},
      {lv:3,q:"Sebuah bola dilempar vertikal ke atas dengan kecepatan awal 15 m/s (g = 10 m/s²). Kedudukan dan arah gerak bola pada saat t = 2 s adalah...",o:["10 m di atas titik lempar dan sedang bergerak naik","10 m di atas titik lempar dan sedang bergerak turun","30 m di atas titik lempar dan sedang bergerak naik","20 m di atas titik lempar dan sedang bergerak turun"],a:1,p:"h = 15 x 2 - 1/2 x 10 x 2² = 30 - 20 = 10 m. v = 15 - 10 x 2 = -5 m/s, tanda negatif berarti bola sedang turun."},
      {lv:3,q:"Sebuah kereta sepanjang 100 m bergerak dengan kecepatan tetap 15 m/s melewati jembatan sepanjang 200 m. Waktu sejak ujung depan kereta masuk jembatan hingga ujung belakangnya keluar dari jembatan adalah...",o:["13,3 s","6,7 s","20 s","30 s"],a:2,p:"Kereta harus menempuh panjang jembatan ditambah panjangnya sendiri: 200 + 100 = 300 m. t = 300 : 15 = 20 s."}
    ],
    "ipa-k10-1": [
      {lv:1,q:"Ilmuwan yang menemukan elektron melalui percobaan sinar katode adalah...",o:["J.J. Thomson","Ernest Rutherford","John Dalton","James Chadwick"],a:0,p:"Thomson membuktikan sinar katode tersusun dari partikel bermuatan negatif yang kemudian disebut elektron."},
      {lv:1,q:"Partikel neutron ditemukan oleh...",o:["J.J. Thomson","Niels Bohr","James Chadwick","Eugen Goldstein"],a:2,p:"Chadwick menemukan neutron pada tahun 1932, yaitu partikel tidak bermuatan di dalam inti atom."},
      {lv:1,q:"Model atom yang digambarkan seperti roti kismis, yaitu bola bermuatan positif dengan elektron tersebar di dalamnya, dikemukakan oleh...",o:["John Dalton","Ernest Rutherford","Niels Bohr","J.J. Thomson"],a:3,p:"Thomson menggambarkan atom sebagai bola positif dengan elektron yang tersebar seperti kismis dalam roti."},
      {lv:1,q:"Partikel penyusun atom yang tidak bermuatan listrik adalah...",o:["Proton","Neutron","Elektron","Ion positif"],a:1,p:"Proton bermuatan positif, elektron negatif, dan neutron netral (tidak bermuatan)."},
      {lv:1,q:"Nomor massa suatu atom menunjukkan jumlah...",o:["Proton dan elektron","Elektron saja","Proton dan neutron","Neutron saja"],a:2,p:"Nomor massa (A) = jumlah proton + jumlah neutron di dalam inti atom."},
      {lv:1,q:"Elektron valensi adalah elektron yang terdapat pada...",o:["Kulit terluar","Kulit terdalam","Inti atom","Semua kulit atom"],a:0,p:"Elektron valensi berada di kulit paling luar dan berperan dalam pembentukan ikatan kimia."},
      {lv:2,q:"Atom klorin dilambangkan ³⁵₁₇Cl. Jumlah proton, elektron, dan neutron atom netral tersebut berturut-turut adalah...",o:["17, 18, dan 17","17, 17, dan 18","18, 17, dan 17","35, 17, dan 18"],a:1,p:"Nomor atom 17 berarti proton = elektron = 17 (atom netral). Neutron = 35 - 17 = 18."},
      {lv:2,q:"Atom magnesium memiliki nomor atom 12. Jumlah elektron pada ion Mg²⁺ adalah...",o:["12","14","24","10"],a:3,p:"Ion Mg²⁺ terbentuk karena atom Mg melepas 2 elektron: 12 - 2 = 10 elektron."},
      {lv:2,q:"Konfigurasi elektron atom dengan nomor atom 17 berdasarkan kulit K, L, M adalah...",o:["2 - 8 - 5 - 2","2 - 6 - 9","2 - 8 - 8","2 - 8 - 7"],a:3,p:"Kulit K maksimal 2, L maksimal 8, sisanya 17 - 10 = 7 di kulit M."},
      {lv:2,q:"Atom-atom yang memiliki nomor massa sama tetapi nomor atomnya berbeda disebut...",o:["Isotop","Isobar","Isoton","Isoelektronik"],a:1,p:"Isobar: nomor massa sama. Isotop: nomor atom sama. Isoton: jumlah neutron sama."},
      {lv:2,q:"Menurut model atom Bohr, elektron di dalam atom...",o:["Bergerak mengelilingi inti pada lintasan tertentu dengan tingkat energi tertentu","Tersebar merata di dalam bola bermuatan positif","Tidak ada, karena atom adalah bola pejal yang tidak dapat dibagi","Berada di dalam inti bersama proton"],a:0,p:"Bohr menyatakan elektron menempati lintasan (kulit) dengan energi tertentu dan dapat berpindah kulit jika menyerap atau melepas energi."},
      {lv:2,q:"Konfigurasi elektron atom natrium (nomor atom 11) berdasarkan subkulit adalah...",o:["1s² 2s² 2p⁷","1s² 2s² 2p⁵ 3s²","1s² 2s² 2p⁶ 3s¹","1s² 2s⁸ 3s¹"],a:2,p:"Pengisian mengikuti urutan 1s, 2s, 2p, 3s. Subkulit p maksimal 6 dan s maksimal 2, sehingga sisa satu elektron masuk ke 3s."},
      {lv:3,q:"Pada percobaan hamburan sinar alfa oleh Rutherford, sebagian besar partikel alfa menembus lempeng emas tanpa dibelokkan. Kesimpulan dari pengamatan ini adalah...",o:["Atom adalah bola pejal yang padat","Sebagian besar ruang di dalam atom adalah ruang kosong","Elektron terletak di dalam inti atom","Inti atom bermuatan negatif"],a:1,p:"Partikel alfa yang lolos lurus menunjukkan tidak ada penghalang. Hanya sedikit yang dibelokkan karena mengenai inti yang sangat kecil dan bermuatan positif."},
      {lv:3,q:"Konfigurasi elektron atom besi (nomor atom 26) adalah...",o:["[Ar] 3d⁸","[Ar] 4s² 4p⁶","[Ar] 4s¹ 3d⁷","[Ar] 4s² 3d⁶"],a:3,p:"Argon memiliki 18 elektron. Sisa 8 elektron mengisi 4s (2 elektron) lebih dulu, lalu 3d (6 elektron)."},
      {lv:3,q:"Unsur dengan nomor atom 20 dalam tabel periodik terletak pada...",o:["Periode 2, golongan IVA","Periode 3, golongan VIIIA","Periode 4, golongan IIA","Periode 4, golongan IA"],a:2,p:"Konfigurasinya 2 - 8 - 8 - 2. Empat kulit berarti periode 4, dua elektron valensi berarti golongan IIA."},
      {lv:3,q:"Pasangan atom berikut yang merupakan isoton (jumlah neutronnya sama) adalah...",o:["¹⁴₆C dan ¹⁶₈O","¹²₆C dan ¹³₆C","¹⁴₆C dan ¹⁴₇N","¹⁶₈O dan ¹⁹₉F"],a:0,p:"Neutron ¹⁴C = 14 - 6 = 8 dan neutron ¹⁶O = 16 - 8 = 8. Pasangan lain berturut-turut isotop, isobar, dan neutronnya 8 dan 10."},
      {lv:3,q:"Klorin di alam terdiri atas isotop ³⁵Cl sebanyak 75% dan ³⁷Cl sebanyak 25%. Massa atom relatif klorin adalah...",o:["35,5","36,0","35,0","36,5"],a:0,p:"Ar = (75% x 35) + (25% x 37) = 26,25 + 9,25 = 35,5."},
      {lv:3,q:"Atom belerang memiliki nomor atom 16. Jumlah elektron yang tidak berpasangan pada atom belerang adalah...",o:["4","0","6","2"],a:3,p:"Konfigurasinya [Ne] 3s² 3p⁴. Empat elektron di tiga orbital 3p mengisi satu-satu dulu, lalu satu berpasangan, sehingga tersisa 2 elektron tidak berpasangan."},
      {lv:3,q:"Atom Y memiliki 2 elektron valensi yang terletak pada kulit ketiga (kulit M). Nomor atom Y adalah...",o:["10","12","14","20"],a:1,p:"Kulit K dan L penuh (2 dan 8), lalu kulit M berisi 2 elektron. Total elektron = 2 + 8 + 2 = 12."},
      {lv:3,q:"Konfigurasi elektron kalium (nomor atom 19) adalah 2 - 8 - 8 - 1, bukan 2 - 8 - 9, walaupun kulit M dapat menampung hingga 18 elektron. Penjelasan yang tepat adalah...",o:["Kulit M hanya dapat menampung 8 elektron","Kulit N memiliki energi paling rendah","Subkulit 4s memiliki energi lebih rendah daripada 3d sehingga terisi lebih dulu","Elektron ke-19 masuk ke dalam inti atom"],a:2,p:"Setelah 3s dan 3p penuh (8 elektron di kulit M), elektron berikutnya masuk ke 4s yang energinya lebih rendah daripada 3d."}
    ],
    "ipa-k10-2": [
      {lv:1,q:"Tiga tingkatan keanekaragaman hayati adalah...",o:["Gen, spesies, dan ekosistem","Sel, jaringan, dan organ","Individu, populasi, dan komunitas","Kingdom, filum, dan kelas"],a:0,p:"Keanekaragaman hayati dikelompokkan menjadi tingkat gen, tingkat spesies (jenis), dan tingkat ekosistem."},
      {lv:1,q:"Contoh upaya pelestarian keanekaragaman hayati secara ex situ adalah...",o:["Taman nasional","Cagar alam","Kebun raya","Suaka margasatwa"],a:2,p:"Ex situ berarti di luar habitat asli, seperti kebun raya, kebun binatang, dan bank biji."},
      {lv:1,q:"Hewan endemik yang hidup secara alami di Pulau Komodo dan sekitarnya adalah...",o:["Anoa","Badak bercula satu","Orangutan","Komodo (Varanus komodoensis)"],a:3,p:"Komodo hanya ditemukan secara alami di Pulau Komodo, Rinca, Flores, dan pulau kecil sekitarnya."},
      {lv:1,q:"Badak Jawa (badak bercula satu) dilindungi di habitat aslinya, yaitu di Taman Nasional...",o:["Komodo","Ujung Kulon","Lorentz","Bunaken"],a:1,p:"Taman Nasional Ujung Kulon di Banten adalah habitat terakhir badak Jawa."},
      {lv:1,q:"Spesies endemik adalah spesies yang...",o:["Dapat ditemukan di seluruh dunia","Sudah punah","Hanya ditemukan secara alami di wilayah tertentu","Merupakan hasil persilangan buatan"],a:2,p:"Endemik berarti asli dan terbatas pada daerah tertentu, misalnya anoa di Sulawesi."},
      {lv:1,q:"Bunga Rafflesia arnoldii yang sangat besar berasal dari hutan di...",o:["Sumatra","Papua","Bali","Nusa Tenggara Timur"],a:0,p:"Rafflesia arnoldii tumbuh di hutan hujan Sumatra, misalnya di Bengkulu."},
      {lv:2,q:"Bunga mawar memiliki variasi warna merah, putih, dan kuning. Variasi ini merupakan contoh keanekaragaman hayati tingkat...",o:["Spesies","Gen","Ekosistem","Kingdom"],a:1,p:"Mawar merah, putih, dan kuning masih satu spesies. Perbedaan warnanya disebabkan oleh perbedaan gen."},
      {lv:2,q:"Di pesisir Indonesia terdapat hutan mangrove, padang lamun, dan terumbu karang. Ketiganya menunjukkan keanekaragaman hayati tingkat...",o:["Gen","Spesies","Individu","Ekosistem"],a:3,p:"Mangrove, padang lamun, dan terumbu karang adalah ekosistem yang berbeda karena komponen biotik dan abiotiknya berbeda."},
      {lv:2,q:"Penyebab terbesar menurunnya keanekaragaman hayati di Indonesia adalah...",o:["Penanaman kembali hutan (reboisasi)","Penangkaran hewan langka","Pembentukan taman nasional","Kerusakan habitat akibat penebangan hutan dan alih fungsi lahan"],a:3,p:"Ketika habitat rusak, banyak spesies kehilangan tempat hidup dan sumber makanan sehingga terancam punah."},
      {lv:2,q:"Contoh fauna tipe Asiatis yang hidup di Indonesia bagian barat adalah...",o:["Kanguru pohon, kasuari, dan cendrawasih","Harimau, gajah, dan badak","Anoa, babirusa, dan maleo","Kuskus, walabi, dan kasuari"],a:1,p:"Fauna Asiatis mirip dengan fauna Asia daratan. Harimau, gajah, dan badak hidup di Sumatra, Jawa, dan Kalimantan."},
      {lv:2,q:"Contoh fauna peralihan yang hidup di Sulawesi adalah...",o:["Anoa dan babirusa","Gajah dan harimau","Kasuari dan kanguru pohon","Orangutan dan bekantan"],a:0,p:"Sulawesi terletak di antara garis Wallace dan Weber. Anoa dan babirusa adalah fauna khas daerah peralihan ini."},
      {lv:2,q:"Kulit batang pohon kina dimanfaatkan untuk membuat obat malaria. Hal ini menunjukkan manfaat keanekaragaman hayati sebagai sumber...",o:["Sandang","Papan","Obat-obatan","Bahan bakar"],a:2,p:"Banyak tumbuhan mengandung zat yang dapat dijadikan obat. Kina menghasilkan kuinin untuk mengobati malaria."},
      {lv:3,q:"Ikan sapu-sapu yang berasal dari luar Indonesia dilepas ke sungai, lalu berkembang biak pesat dan menyaingi ikan asli. Dampak yang paling mungkin terjadi adalah...",o:["Jumlah spesies ikan asli bertambah","Keanekaragaman spesies ikan asli menurun karena kalah bersaing","Sungai menjadi ekosistem yang lebih seimbang","Ikan asli berubah menjadi ikan sapu-sapu"],a:1,p:"Spesies asing invasif tidak memiliki pemangsa alami dan dapat merebut makanan serta tempat hidup spesies asli."},
      {lv:3,q:"Sebuah daerah hanya menanam satu varietas padi yang sama di seluruh sawahnya. Mengapa cara ini berisiko?",o:["Satu varietas padi selalu menghasilkan panen lebih banyak","Keanekaragaman gennya terlalu tinggi","Satu varietas padi tidak membutuhkan air","Keanekaragaman gen rendah sehingga satu jenis hama atau penyakit dapat merusak seluruh tanaman"],a:3,p:"Jika semua tanaman sama secara genetik, tidak ada tanaman yang tahan terhadap serangan hama tertentu, sehingga gagal panen bisa meluas."},
      {lv:3,q:"Bank biji (bank plasma nutfah) menyimpan biji dari berbagai varietas tanaman, termasuk varietas lokal yang jarang ditanam. Tujuan utamanya adalah...",o:["Menghabiskan varietas lokal","Mengganti semua tanaman dengan satu varietas","Menjaga keanekaragaman gen yang dapat dipakai untuk merakit varietas unggul di masa depan","Mencegah tanaman berbunga"],a:2,p:"Varietas lokal mungkin memiliki gen tahan kekeringan atau penyakit. Menyimpannya menjaga bahan untuk pemuliaan tanaman kelak."},
      {lv:3,q:"Jalak Bali ditangkarkan di penangkaran, lalu sebagian dilepasliarkan ke Taman Nasional Bali Barat. Program ini menggabungkan pelestarian...",o:["Ex situ (penangkaran) dan in situ (pelepasliaran ke habitat asli)","In situ saja","Ex situ saja","Bukan termasuk pelestarian"],a:0,p:"Penangkaran dilakukan di luar habitat asli (ex situ). Pelepasliaran ke taman nasional mengembalikan burung ke habitat aslinya (in situ)."},
      {lv:3,q:"Fauna di Sumatra, Jawa, dan Kalimantan mirip dengan fauna di Asia daratan. Penjelasan yang paling tepat adalah...",o:["Pada zaman es, Paparan Sunda menyatu dengan daratan Asia sehingga hewan dapat berpindah","Hewan-hewan itu dibawa manusia dari Asia","Iklim Sumatra sama dengan iklim kutub","Pulau-pulau tersebut dulu menyatu dengan Australia"],a:0,p:"Saat permukaan laut turun pada zaman es, pulau-pulau di Paparan Sunda terhubung dengan Asia daratan sehingga persebaran fauna terjadi."},
      {lv:3,q:"Harimau Sumatra adalah predator puncak. Jika harimau punah karena diburu, dampak yang paling mungkin terjadi pada ekosistem hutan adalah...",o:["Populasi herbivora menurun drastis","Tumbuhan di hutan menjadi lebih subur","Ekosistem tetap seimbang tanpa perubahan","Populasi herbivora seperti rusa dan babi hutan meningkat lalu merusak tumbuhan sehingga keseimbangan terganggu"],a:3,p:"Tanpa predator puncak, jumlah herbivora tidak terkendali. Tumbuhan yang dimakan berlebihan akan berkurang, sehingga rantai makanan terganggu."},
      {lv:3,q:"Populasi badak Jawa saat ini sangat kecil. Selain jumlahnya sedikit, mengapa kondisi ini membuat badak Jawa sangat rentan punah?",o:["Keanekaragaman gennya sangat tinggi","Keanekaragaman gennya rendah dan terjadi perkawinan sekerabat sehingga rentan terhadap penyakit","Badak Jawa tidak membutuhkan habitat","Badak Jawa dapat berkembang biak dengan sangat cepat"],a:1,p:"Populasi kecil memiliki variasi gen sedikit. Perkawinan sekerabat meningkatkan munculnya sifat merugikan dan menurunkan daya tahan."},
      {lv:3,q:"Masyarakat Maluku mengenal tradisi sasi, yaitu larangan mengambil hasil laut tertentu selama waktu tertentu. Manfaat tradisi ini bagi keanekaragaman hayati adalah...",o:["Menghabiskan biota laut lebih cepat","Membuat biota laut berpindah ke darat","Memberi kesempatan populasi biota laut untuk pulih sehingga dapat dimanfaatkan secara berkelanjutan","Menghentikan semua pemanfaatan laut selamanya"],a:2,p:"Selama sasi, biota laut dapat tumbuh dan berkembang biak. Setelah sasi dibuka, hasilnya tetap melimpah tanpa merusak populasi."}
    ],
    "ipa-k11-0": [
      {lv:1,q:"Zat yang dapat mengalir dan disebut fluida adalah...",o:["Zat cair dan gas","Zat padat saja","Zat padat dan zat cair","Zat padat dan gas"],a:0,p:"Fluida adalah zat yang dapat mengalir dan bentuknya mengikuti wadah, yaitu zat cair dan gas."},
      {lv:1,q:"Rumus massa jenis (ρ) suatu zat adalah...",o:["ρ = m x V","ρ = V : m","ρ = m : V","ρ = m + V"],a:2,p:"Massa jenis adalah massa per satuan volume."},
      {lv:1,q:"Besar tekanan hidrostatis di suatu titik TIDAK bergantung pada...",o:["Kedalaman titik","Massa jenis zat cair","Percepatan gravitasi","Bentuk wadah"],a:3,p:"P = ρ g h. Tekanan hanya bergantung pada massa jenis, gravitasi, dan kedalaman, bukan bentuk wadah."},
      {lv:1,q:"Satuan SI untuk massa jenis adalah...",o:["g/cm","kg/m³","N/m²","kg·m"],a:1,p:"Massa dalam kg dibagi volume dalam m³ menghasilkan satuan kg/m³."},
      {lv:1,q:"Tekanan udara normal di permukaan laut sebesar 1 atm setara dengan sekitar...",o:["1 x 10³ Pa","76 Pa","1,01 x 10⁵ Pa","1 x 10⁷ Pa"],a:2,p:"1 atm = 76 cmHg ≈ 1,01 x 10⁵ Pa."},
      {lv:1,q:"Sebuah benda akan tenggelam di dalam fluida jika...",o:["Massa jenis benda lebih besar daripada massa jenis fluida","Massa jenis benda lebih kecil daripada massa jenis fluida","Massa jenis benda sama dengan massa jenis fluida","Gaya apung lebih besar daripada berat benda"],a:0,p:"Jika ρ benda > ρ fluida, berat benda lebih besar daripada gaya apung maksimumnya, sehingga benda tenggelam."},
      {lv:2,q:"Tekanan hidrostatis yang dialami penyelam pada kedalaman 20 m di laut (ρ air laut = 1.025 kg/m³, g = 10 m/s²) adalah...",o:["20.500 Pa","205.000 Pa","200.000 Pa","2.050.000 Pa"],a:1,p:"P = ρ g h = 1.025 x 10 x 20 = 205.000 Pa."},
      {lv:2,q:"Sebuah benda bervolume 0,5 m³ tercelup seluruhnya di dalam minyak (ρ = 800 kg/m³, g = 10 m/s²). Gaya apung yang dialami benda adalah...",o:["5.000 N","400 N","1.600 N","4.000 N"],a:3,p:"FA = ρ g V = 800 x 10 x 0,5 = 4.000 N."},
      {lv:2,q:"Sebuah benda beratnya 20 N di udara dan 15 N ketika tercelup seluruhnya di dalam air. Besar gaya apung yang dialami benda adalah...",o:["35 N","15 N","20 N","5 N"],a:3,p:"Gaya apung = berat di udara - berat di air = 20 - 15 = 5 N."},
      {lv:2,q:"Kapal selam dapat menyelam ke dalam laut dengan cara...",o:["Mengosongkan tangki pemberat dengan udara bertekanan","Mengisi tangki pemberatnya dengan air laut sehingga beratnya bertambah","Memperkecil berat kapal","Mengurangi volume air yang dipindahkan menjadi nol"],a:1,p:"Air yang masuk ke tangki menambah berat kapal. Saat berat lebih besar daripada gaya apung, kapal selam turun."},
      {lv:2,q:"Hidrometer adalah alat yang bekerja berdasarkan Hukum Archimedes dan digunakan untuk mengukur...",o:["Massa jenis zat cair","Tekanan udara","Suhu zat cair","Volume gas"],a:0,p:"Hidrometer terapung di zat cair. Makin besar massa jenis zat cair, makin sedikit bagian hidrometer yang tercelup."},
      {lv:2,q:"Pipa U berisi air (ρ = 1 g/cm³). Pada salah satu kakinya dituangkan minyak (ρ = 0,8 g/cm³) setinggi 10 cm. Tinggi permukaan air di kaki lainnya diukur dari bidang batas minyak-air adalah...",o:["10 cm","12,5 cm","8 cm","2 cm"],a:2,p:"Tekanan pada bidang batas sama: ρ minyak x h minyak = ρ air x h air. 0,8 x 10 = 1 x h, sehingga h = 8 cm."},
      {lv:3,q:"Pipa U berisi raksa (ρ = 13,6 g/cm³). Pada salah satu kakinya dituangkan air (ρ = 1 g/cm³) setinggi 27,2 cm. Selisih tinggi permukaan raksa pada kedua kaki adalah...",o:["27,2 cm","2 cm","13,6 cm","0,5 cm"],a:1,p:"ρ air x h air = ρ raksa x Δh. 1 x 27,2 = 13,6 x Δh, sehingga Δh = 2 cm."},
      {lv:3,q:"Sebuah gabus bervolume 200 cm³ dan bermassa jenis 0,25 g/cm³ terapung di air (ρ = 1 g/cm³). Volume gabus yang tercelup di dalam air adalah...",o:["150 cm³","200 cm³","25 cm³","50 cm³"],a:3,p:"Saat terapung, berat = gaya apung: ρ gabus x V = ρ air x V tercelup. V tercelup = 0,25 x 200 : 1 = 50 cm³."},
      {lv:3,q:"Sebuah batu beratnya 60 N di udara dan massa jenisnya 3.000 kg/m³. Jika batu dicelupkan seluruhnya ke dalam air (ρ = 1.000 kg/m³, g = 10 m/s²), berat batu di dalam air adalah...",o:["20 N","60 N","40 N","80 N"],a:2,p:"Massa batu 6 kg, volumenya 6 : 3.000 = 0,002 m³. Gaya apung = 1.000 x 10 x 0,002 = 20 N. Berat di air = 60 - 20 = 40 N."},
      {lv:3,q:"Sebuah balok terapung di air dengan 60% volumenya tercelup. Di dalam zat cair X, balok yang sama terapung dengan 75% volumenya tercelup. Massa jenis zat cair X adalah...",o:["800 kg/m³","1.250 kg/m³","450 kg/m³","600 kg/m³"],a:0,p:"ρ balok = 0,6 x 1.000 = 600 kg/m³. Di zat cair X: 600 = ρX x 0,75, sehingga ρX = 800 kg/m³."},
      {lv:3,q:"Alat pengangkat mobil hidrolik memiliki pengisap besar seluas 0,2 m². Mobil bermassa 1.500 kg (g = 10 m/s²) dapat terangkat dengan gaya 300 N pada pengisap kecil. Luas pengisap kecil adalah...",o:["0,004 m²","0,04 m²","10 m²","0,0004 m²"],a:0,p:"F1/A1 = F2/A2. A1 = F1 x A2 : F2 = 300 x 0,2 : 15.000 = 0,004 m²."},
      {lv:3,q:"Air naik di dalam pipa kapiler kaca, sedangkan raksa justru turun di dalam pipa kapiler kaca. Penjelasan yang tepat adalah...",o:["Kohesi air lebih besar daripada adhesinya dengan kaca","Raksa memiliki adhesi yang lebih besar terhadap kaca","Massa jenis air lebih besar daripada raksa","Adhesi air dan kaca lebih besar daripada kohesi air, sedangkan kohesi raksa lebih besar daripada adhesi raksa dan kaca"],a:3,p:"Air lebih kuat menempel pada kaca sehingga merambat naik. Partikel raksa lebih kuat saling tarik sehingga menjauhi dinding dan turun."},
      {lv:3,q:"Sebuah jarum baja dapat diletakkan perlahan-lahan hingga terapung di permukaan air. Namun, jika air ditetesi sabun, jarum segera tenggelam. Penjelasan yang tepat adalah...",o:["Sabun menambah massa jenis jarum","Sabun menurunkan tegangan permukaan air sehingga tidak mampu lagi menahan jarum","Sabun memperbesar gaya apung air","Sabun membuat air menjadi padat"],a:1,p:"Jarum ditahan oleh tegangan permukaan, bukan gaya apung. Sabun memperlemah tegangan permukaan sehingga jarum tenggelam."},
      {lv:3,q:"Balon berisi gas helium dapat naik ke udara, sedangkan balon berisi udara dari tiupan mulut jatuh ke lantai. Penjelasan yang tepat adalah...",o:["Helium memiliki gaya magnet yang menarik balon ke atas","Udara tiupan mulut lebih ringan daripada helium","Massa jenis helium jauh lebih kecil daripada udara sehingga gaya apung udara melebihi berat balon helium","Gaya apung tidak bekerja pada balon berisi udara"],a:2,p:"Udara di sekitar memberi gaya apung pada balon. Balon helium beratnya lebih kecil daripada gaya apung itu, sehingga naik."}
    ],
    "ipa-k11-1": [
      {lv:1,q:"Pada suhu 25 °C, larutan yang bersifat netral memiliki pH...",o:["7","0","14","1"],a:0,p:"Air murni pada 25 °C memiliki [H⁺] = [OH⁻] = 10⁻⁷ M, sehingga pH = 7."},
      {lv:1,q:"Menurut Arrhenius, basa adalah zat yang di dalam air...",o:["Melepaskan ion H⁺","Menerima pasangan elektron","Melepaskan ion OH⁻","Memberikan proton"],a:2,p:"Basa Arrhenius menghasilkan ion hidroksida (OH⁻) ketika dilarutkan dalam air, misalnya NaOH."},
      {lv:1,q:"Asam yang terdapat di dalam buah jeruk adalah...",o:["Asam asetat","Asam klorida","Asam sulfat","Asam sitrat"],a:3,p:"Rasa asam jeruk dan lemon berasal dari asam sitrat."},
      {lv:1,q:"Kertas lakmus biru yang dicelupkan ke dalam larutan asam akan berubah menjadi...",o:["Biru","Merah","Ungu","Kuning"],a:1,p:"Asam mengubah lakmus biru menjadi merah. Basa mengubah lakmus merah menjadi biru."},
      {lv:1,q:"Sifat umum larutan basa adalah...",o:["Berasa asam dan tidak licin","Berasa manis","Berasa pahit dan terasa licin di kulit","Selalu memiliki pH kurang dari 7"],a:2,p:"Basa berasa pahit, licin seperti sabun, dan memiliki pH lebih dari 7."},
      {lv:1,q:"Cuka dapur mengandung asam...",o:["Asetat (CH₃COOH)","Klorida (HCl)","Sulfat (H₂SO₄)","Nitrat (HNO₃)"],a:0,p:"Cuka adalah larutan encer asam asetat atau asam cuka."},
      {lv:2,q:"Larutan A memiliki pH 4 dan larutan B memiliki pH 6. Konsentrasi ion H⁺ pada larutan A dibandingkan larutan B adalah...",o:["2 kali lebih besar","100 kali lebih besar","10 kali lebih besar","1.000 kali lebih besar"],a:1,p:"[H⁺] A = 10⁻⁴ M dan [H⁺] B = 10⁻⁶ M. Perbandingannya 10⁻⁴ : 10⁻⁶ = 100."},
      {lv:2,q:"Menurut teori Brønsted-Lowry, basa konjugasi dari H₂SO₄ adalah...",o:["SO₄²⁻","H₃SO₄⁺","H₂O","HSO₄⁻"],a:3,p:"Basa konjugasi terbentuk setelah asam melepas satu proton (H⁺): H₂SO₄ menjadi HSO₄⁻."},
      {lv:2,q:"Indikator metil jingga berwarna merah pada pH di bawah 3,1 dan kuning pada pH di atas 4,4. Jika diteteskan ke larutan ber-pH 2, warna larutan menjadi...",o:["Kuning","Jingga","Tidak berwarna","Merah"],a:3,p:"pH 2 berada di bawah 3,1, sehingga metil jingga menunjukkan warna merah."},
      {lv:2,q:"pH larutan NaOH 0,001 M (basa kuat) pada suhu 25 °C adalah...",o:["3","11","10","13"],a:1,p:"[OH⁻] = 10⁻³ M, sehingga pOH = 3. pH = 14 - 3 = 11."},
      {lv:2,q:"Tanah pertanian yang terlalu asam dapat diperbaiki dengan cara...",o:["Menaburkan kapur pertanian (kapur dolomit)","Menyiramkan cuka","Menambahkan pupuk yang bersifat asam","Menyiramkan air aki"],a:0,p:"Kapur pertanian bersifat basa sehingga menetralkan keasaman tanah dan menaikkan pH-nya."},
      {lv:2,q:"Obat maag (antasida) biasanya mengandung magnesium hidroksida atau aluminium hidroksida. Fungsi zat tersebut adalah...",o:["Menambah asam lambung","Membunuh semua bakteri di usus","Menetralkan kelebihan asam lambung","Mencerna protein di lambung"],a:2,p:"Hidroksida logam bersifat basa dan bereaksi dengan HCl lambung membentuk garam dan air (netralisasi)."},
      {lv:3,q:"pH larutan H₂SO₄ 0,005 M (dianggap terionisasi sempurna) adalah...",o:["2,3","2","3","1,7"],a:1,p:"Setiap H₂SO₄ melepaskan 2 ion H⁺. [H⁺] = 2 x 0,005 = 0,01 M = 10⁻², sehingga pH = 2."},
      {lv:3,q:"Sebanyak 50 mL HCl 0,2 M dicampur dengan 50 mL NaOH 0,1 M. pH larutan campuran adalah... (log 5 = 0,7)",o:["7","2","12,7","1,3"],a:3,p:"mmol HCl = 10, mmol NaOH = 5. Sisa H⁺ = 5 mmol dalam 100 mL, [H⁺] = 0,05 M = 5 x 10⁻². pH = 2 - log 5 = 1,3."},
      {lv:3,q:"Sebanyak 25 mL larutan HCl dititrasi dengan NaOH 0,1 M. Titik ekuivalen tercapai setelah 20 mL NaOH ditambahkan. Konsentrasi HCl adalah...",o:["0,125 M","0,1 M","0,08 M","0,2 M"],a:2,p:"Pada titik ekuivalen, mol HCl = mol NaOH. M x 25 = 0,1 x 20, sehingga M = 2 : 25 = 0,08 M."},
      {lv:3,q:"pH larutan asam asetat 0,1 M jika Ka = 1 x 10⁻⁵ adalah...",o:["3","1","5","6"],a:0,p:"Untuk asam lemah, [H⁺] = √(Ka x M) = √(10⁻⁵ x 10⁻¹) = √10⁻⁶ = 10⁻³ M. pH = 3."},
      {lv:3,q:"Pada reaksi BF₃ + NH₃ → F₃B-NH₃, menurut teori Lewis, BF₃ berperan sebagai...",o:["Asam, karena menerima pasangan elektron bebas dari NH₃","Basa, karena memberikan pasangan elektron","Asam, karena melepaskan ion H⁺","Basa, karena melepaskan ion OH⁻"],a:0,p:"Atom B pada BF₃ kekurangan elektron dan menerima pasangan elektron bebas dari N pada NH₃. Penerima pasangan elektron adalah asam Lewis."},
      {lv:3,q:"Spesi berikut yang bersifat amfiprotik, yaitu dapat memberikan maupun menerima proton, adalah...",o:["Cl⁻","Na⁺","NH₄⁺","HCO₃⁻"],a:3,p:"HCO₃⁻ dapat melepas H⁺ menjadi CO₃²⁻ atau menerima H⁺ menjadi H₂CO₃. Cl⁻ hanya bisa menerima, NH₄⁺ hanya bisa memberi, Na⁺ tidak keduanya."},
      {lv:3,q:"pH larutan amonia (NH₃) 0,1 M jika Kb = 1 x 10⁻⁵ pada suhu 25 °C adalah...",o:["3","11","13","9"],a:1,p:"[OH⁻] = √(Kb x M) = √(10⁻⁵ x 10⁻¹) = 10⁻³ M. pOH = 3, sehingga pH = 14 - 3 = 11."},
      {lv:3,q:"Gas SO₂ dan NO₂ dari pembakaran bahan bakar dapat menyebabkan hujan asam. Dampak hujan asam terhadap patung atau bangunan dari marmer (CaCO₃) adalah...",o:["Marmer menjadi lebih kuat karena dinetralkan","Marmer berubah menjadi logam","Marmer terkikis karena CaCO₃ bereaksi dengan asam","Marmer tidak terpengaruh karena bersifat asam"],a:2,p:"CaCO₃ bersifat basa dan bereaksi dengan asam membentuk garam yang larut, air, dan gas CO₂. Akibatnya permukaan marmer rusak."}
    ],
    "ipa-k11-2": [
      {lv:1,q:"Ilmuwan yang pertama kali mengamati dan memberi nama sel saat melihat sayatan gabus dengan mikroskop adalah...",o:["Robert Hooke","Matthias Schleiden","Rudolf Virchow","Robert Brown"],a:0,p:"Pada tahun 1665, Robert Hooke melihat ruang-ruang kecil pada gabus dan menyebutnya cell (sel)."},
      {lv:1,q:"Organel yang mengandung enzim pencerna dan berperan dalam pencernaan di dalam sel adalah...",o:["Ribosom","Kloroplas","Lisosom","Vakuola kontraktil"],a:2,p:"Lisosom berisi enzim hidrolitik untuk mencerna zat atau organel yang sudah rusak."},
      {lv:1,q:"Organel yang berperan dalam pembelahan sel hewan dengan membentuk benang spindel adalah...",o:["Lisosom","Badan Golgi","Kloroplas","Sentriol"],a:3,p:"Sentriol (di dalam sentrosom) membentuk benang spindel yang menarik kromosom saat pembelahan sel hewan."},
      {lv:1,q:"Cairan di dalam sel tempat organel-organel berada disebut...",o:["Nukleolus","Sitoplasma","Plasma darah","Dinding sel"],a:1,p:"Sitoplasma adalah cairan sel di antara membran sel dan inti, tempat organel melayang."},
      {lv:1,q:"Vakuola yang besar pada sel tumbuhan berfungsi untuk...",o:["Membuat protein","Menghasilkan energi melalui respirasi","Menyimpan air, cadangan makanan, dan sisa metabolisme serta menjaga tekanan turgor","Membentuk benang spindel"],a:2,p:"Vakuola tumbuhan berisi getah sel. Saat penuh air, vakuola menekan dinding sel sehingga sel tetap kaku."},
      {lv:1,q:"Perpindahan zat dari daerah berkonsentrasi tinggi ke daerah berkonsentrasi rendah tanpa memerlukan energi disebut...",o:["Difusi","Transpor aktif","Endositosis","Eksositosis"],a:0,p:"Difusi terjadi secara alami mengikuti perbedaan konsentrasi sehingga tidak memerlukan ATP."},
      {lv:2,q:"Osmosis adalah perpindahan...",o:["Zat terlarut dari larutan encer ke larutan pekat dengan bantuan ATP","Air melalui membran selektif permeabel dari larutan encer ke larutan pekat","Air dari larutan pekat ke larutan encer","Protein besar melalui membran dengan pembentukan vesikel"],a:1,p:"Pada osmosis, air bergerak dari larutan berkonsentrasi zat terlarut rendah (hipotonik) ke larutan berkonsentrasi tinggi (hipertonik)."},
      {lv:2,q:"Sel daun Rhoeo discolor ditetesi larutan garam pekat. Di bawah mikroskop, membran sel tampak terlepas dari dinding sel. Peristiwa ini disebut...",o:["Hemolisis","Krenasi","Turgor","Plasmolisis"],a:3,p:"Air keluar dari sel ke larutan yang hipertonik, sehingga sitoplasma menyusut dan membran terlepas dari dinding sel."},
      {lv:2,q:"Sel otot jantung mengandung mitokondria dalam jumlah sangat banyak. Hal ini berkaitan dengan...",o:["Kebutuhan untuk berfotosintesis","Fungsi sel jantung sebagai penyimpan lemak","Fungsi sel jantung dalam membuat enzim pencernaan","Kebutuhan energi yang sangat besar untuk berkontraksi terus-menerus"],a:3,p:"Mitokondria menghasilkan ATP. Jantung bekerja tanpa henti sehingga membutuhkan banyak ATP."},
      {lv:2,q:"Organel yang mengandung enzim katalase untuk menguraikan hidrogen peroksida (H₂O₂) yang beracun bagi sel adalah...",o:["Lisosom","Peroksisom","Ribosom","Badan Golgi"],a:1,p:"Peroksisom menguraikan H₂O₂ menjadi air dan oksigen dengan enzim katalase. Peroksisom banyak terdapat di sel hati."},
      {lv:2,q:"Pernyataan omnis cellula e cellula yang berarti setiap sel berasal dari sel sebelumnya dikemukakan oleh...",o:["Rudolf Virchow","Robert Hooke","Antonie van Leeuwenhoek","Robert Brown"],a:0,p:"Virchow menyatakan sel baru hanya terbentuk dari pembelahan sel yang sudah ada."},
      {lv:2,q:"Retikulum endoplasma halus (tanpa ribosom) berfungsi untuk...",o:["Menyintesis protein","Melakukan fotosintesis","Menyintesis lipid dan menetralkan racun","Menghasilkan ATP melalui respirasi"],a:2,p:"RE halus membuat lemak, fosfolipid, dan steroid, serta membantu detoksifikasi obat dan racun."},
      {lv:3,q:"Sel-sel hati berperan menetralkan racun dan sisa obat di dalam tubuh. Organel yang diperkirakan sangat berkembang di dalam sel hati adalah...",o:["Kloroplas","Retikulum endoplasma halus","Dinding sel","Sentriol"],a:1,p:"Detoksifikasi zat beracun dilakukan oleh enzim-enzim di RE halus, sehingga organel ini sangat banyak di sel hati."},
      {lv:3,q:"Sel darah putih menangkap bakteri dengan cara menjulurkan membran selnya hingga bakteri terbungkus dalam vesikel, lalu dicerna. Proses ini disebut...",o:["Eksositosis","Osmosis","Difusi terbantu","Fagositosis (endositosis)"],a:3,p:"Fagositosis adalah endositosis partikel padat. Vesikel berisi bakteri kemudian bergabung dengan lisosom untuk dicerna."},
      {lv:3,q:"Potongan wortel yang direndam dalam larutan garam pekat menjadi lembek, sedangkan potongan yang direndam dalam air tawar menjadi keras. Penjelasan yang tepat adalah...",o:["Dalam larutan garam air masuk ke sel sehingga sel pecah","Garam masuk ke sel dan membuat dinding sel larut","Dalam larutan garam air keluar dari sel sehingga sel kehilangan turgor, sedangkan dalam air tawar air masuk ke sel sehingga sel menegang","Dalam air tawar sel kehilangan air sehingga mengeras"],a:2,p:"Larutan garam hipertonik menarik air keluar (plasmolisis). Air tawar hipotonik membuat air masuk dan sel menjadi turgid."},
      {lv:3,q:"Konsentrasi ion K⁺ di dalam sel saraf jauh lebih tinggi daripada di luar sel, tetapi ion K⁺ tetap terus dipindahkan ke dalam sel. Mekanisme yang memungkinkan hal ini adalah...",o:["Transpor aktif oleh pompa natrium-kalium yang memakai ATP","Difusi sederhana","Osmosis","Difusi terbantu tanpa energi"],a:0,p:"Memindahkan zat melawan perbedaan konsentrasi memerlukan energi. Pompa Na⁺-K⁺ memakai ATP untuk memasukkan 2 K⁺ dan mengeluarkan 3 Na⁺."},
      {lv:3,q:"Mitokondria dan kloroplas memiliki DNA sendiri, ribosom sendiri, dan membran ganda. Fakta ini menjadi dasar teori yang menyatakan bahwa kedua organel tersebut...",o:["Berasal dari sel prokariot yang hidup bersimbiosis di dalam sel lain (teori endosimbiosis)","Berasal dari pecahan inti sel","Terbentuk dari badan Golgi","Merupakan virus yang menginfeksi sel"],a:0,p:"Kemiripan dengan bakteri (DNA melingkar, ribosom, membran ganda) mendukung teori endosimbiosis."},
      {lv:3,q:"Jika membran lisosom di dalam sel rusak sehingga enzimnya keluar ke sitoplasma, akibat yang paling mungkin terjadi adalah...",o:["Sel melakukan fotosintesis lebih cepat","Sel menghasilkan lebih banyak protein","Sel membelah menjadi dua","Sel mencerna dirinya sendiri (autolisis)"],a:3,p:"Enzim lisosom dapat menguraikan berbagai zat. Jika bocor, enzim tersebut merusak komponen sel itu sendiri."},
      {lv:3,q:"Hasil pengamatan mikroskop menunjukkan sel berbentuk tetap seperti segi empat, memiliki vakuola besar di tengah, terdapat butir-butir hijau, dan tidak tampak sentriol. Sel tersebut adalah...",o:["Sel hewan","Sel tumbuhan (sel daun)","Sel bakteri","Sel darah merah"],a:1,p:"Dinding sel memberi bentuk tetap, vakuola besar dan kloroplas (butir hijau) adalah ciri sel tumbuhan. Sel tumbuhan tingkat tinggi juga umumnya tidak memiliki sentriol."},
      {lv:3,q:"Suatu zat racun menghambat kerja mitokondria di dalam sel. Proses yang paling langsung terganggu adalah...",o:["Fotosintesis di kloroplas","Pembentukan dinding sel","Pembentukan ATP sehingga kegiatan sel yang memerlukan energi, seperti transpor aktif, terhambat","Difusi oksigen melalui membran"],a:2,p:"Mitokondria adalah tempat respirasi sel penghasil ATP. Tanpa ATP, proses yang membutuhkan energi tidak dapat berlangsung."}
    ],
    "ipa-k12-0": [
      {lv:1,q:"Hukum II Kirchhoff menyatakan bahwa dalam suatu rangkaian tertutup (loop)...",o:["Jumlah aljabar GGL dan penurunan tegangan sama dengan nol","Jumlah arus yang masuk sama dengan jumlah arus yang keluar","Hambatan total selalu sama dengan nol","Arus listrik selalu bertambah besar"],a:0,p:"Hukum II Kirchhoff: ΣE + Σ(I x R) = 0 untuk satu loop tertutup."},
      {lv:1,q:"Hukum II Kirchhoff merupakan penerapan dari hukum kekekalan...",o:["Muatan","Massa","Energi","Momentum"],a:2,p:"Energi yang diberikan sumber dalam satu loop sama dengan energi yang dipakai pada hambatan. Hukum I Kirchhoff berdasar kekekalan muatan."},
      {lv:1,q:"Rumus hambatan sebuah kawat penghantar yang panjangnya L, luas penampangnya A, dan hambatan jenisnya ρ adalah...",o:["R = ρ x A : L","R = L : (ρ x A)","R = ρ x L x A","R = ρ x L : A"],a:3,p:"Hambatan sebanding dengan panjang dan hambatan jenis, serta berbanding terbalik dengan luas penampang."},
      {lv:1,q:"Gaya gerak listrik (GGL) suatu baterai adalah...",o:["Beda potensial antara kutub baterai saat mengalirkan arus besar","Beda potensial antara kutub baterai saat tidak mengalirkan arus","Kuat arus yang dihasilkan baterai","Hambatan di dalam baterai"],a:1,p:"GGL diukur saat rangkaian terbuka. Saat ada arus, tegangan kutub (tegangan jepit) lebih kecil karena ada hambatan dalam."},
      {lv:1,q:"Satuan daya listrik adalah...",o:["Joule","Volt","Watt","Coulomb"],a:2,p:"Daya adalah energi per waktu. 1 watt = 1 joule per sekon."},
      {lv:1,q:"Alat yang digunakan untuk mengukur hambatan listrik secara langsung adalah...",o:["Ohmmeter","Voltmeter","Amperemeter","Galvanometer"],a:0,p:"Ohmmeter digunakan untuk mengukur besar hambatan dalam satuan ohm."},
      {lv:2,q:"Dua baterai identik, masing-masing ber-GGL 1,5 V dan berhambatan dalam 0,5 Ω, disusun seri lalu dihubungkan ke hambatan luar 2 Ω. Kuat arus dalam rangkaian adalah...",o:["1,5 A","1 A","0,75 A","3 A"],a:1,p:"GGL total = 3 V, hambatan dalam total = 1 Ω. I = 3 : (2 + 1) = 1 A."},
      {lv:2,q:"Dua baterai identik, masing-masing ber-GGL 6 V dan berhambatan dalam 1 Ω, disusun paralel lalu dihubungkan ke hambatan luar 2,5 Ω. Kuat arus yang mengalir pada hambatan luar adalah...",o:["4 A","1,71 A","2,4 A","2 A"],a:3,p:"Susunan paralel: GGL tetap 6 V, hambatan dalam = 1 : 2 = 0,5 Ω. I = 6 : (2,5 + 0,5) = 2 A."},
      {lv:2,q:"Hambatan 10 Ω dialiri arus 2 A. Daya listrik yang diserap hambatan adalah...",o:["20 W","5 W","200 W","40 W"],a:3,p:"P = I² x R = 2² x 10 = 40 W."},
      {lv:2,q:"Sebuah kawat tembaga panjangnya 2 m, luas penampangnya 1 mm², dan hambatan jenisnya 1,7 x 10⁻⁸ Ωm. Hambatan kawat tersebut adalah...",o:["3,4 Ω","0,034 Ω","0,0085 Ω","34 Ω"],a:1,p:"A = 1 mm² = 10⁻⁶ m². R = ρL/A = 1,7 x 10⁻⁸ x 2 : 10⁻⁶ = 3,4 x 10⁻² = 0,034 Ω."},
      {lv:2,q:"Pada suatu titik cabang, arus 3 A dan 4 A masuk, sedangkan arus 2 A dan I keluar. Besar arus I adalah...",o:["5 A","9 A","1 A","3 A"],a:0,p:"Hukum I Kirchhoff: Σ masuk = Σ keluar. 3 + 4 = 2 + I, sehingga I = 5 A."},
      {lv:2,q:"Sebuah pemanas listrik berdaya 500 W dinyalakan selama 10 menit. Energi kalor yang dihasilkan adalah...",o:["5.000 J","50.000 J","300.000 J","3.000 J"],a:2,p:"W = P x t = 500 W x 600 s = 300.000 J."},
      {lv:3,q:"Di antara titik A dan B terdapat tiga cabang paralel: cabang 1 berisi baterai 12 V yang diseri hambatan 2 Ω, cabang 2 berisi baterai 3 V yang diseri hambatan 2 Ω, dan cabang 3 hanya berisi hambatan 2 Ω. Kutub positif kedua baterai menghadap titik A dan hambatan dalam diabaikan. Kuat arus pada cabang 3 adalah...",o:["3 A","2,5 A","7,5 A","1,5 A"],a:1,p:"Misalkan tegangan A terhadap B = V. Hukum I Kirchhoff: (12 - V)/2 + (3 - V)/2 = V/2, sehingga 15 - 2V = V dan V = 5 V. Arus cabang 3 = 5 : 2 = 2,5 A."},
      {lv:3,q:"Sebuah baterai menghasilkan arus 2 A ketika dihubungkan ke hambatan 4 Ω, dan arus 1 A ketika dihubungkan ke hambatan 9 Ω. GGL dan hambatan dalam baterai berturut-turut adalah...",o:["9 V dan 0 Ω","8 V dan 2 Ω","12 V dan 2 Ω","10 V dan 1 Ω"],a:3,p:"E = I(R + r). 2(4 + r) = 1(9 + r), sehingga 8 + 2r = 9 + r dan r = 1 Ω. E = 2 x (4 + 1) = 10 V."},
      {lv:3,q:"Pada rangkaian jembatan Wheatstone, galvanometer menunjukkan angka nol. Hambatan pada lengan-lengannya adalah R1 = 4 Ω, R2 = 6 Ω, R3 = 8 Ω, dan Rx, dengan syarat setimbang R1 : R2 = R3 : Rx. Nilai Rx adalah...",o:["3 Ω","5,3 Ω","12 Ω","2 Ω"],a:2,p:"Saat setimbang, R1 x Rx = R2 x R3. Rx = 6 x 8 : 4 = 12 Ω."},
      {lv:3,q:"Sebuah baterai memiliki GGL 12 V dan hambatan dalam 2 Ω. Daya maksimum yang dapat diberikan baterai kepada hambatan luar adalah...",o:["18 W","72 W","36 W","12 W"],a:0,p:"Daya pada hambatan luar maksimum jika R = r = 2 Ω. I = 12 : 4 = 3 A. P = 3² x 2 = 18 W."},
      {lv:3,q:"Sebuah lampu bertuliskan 6 V / 3 W akan dinyalakan normal menggunakan sumber 9 V. Agar lampu tidak rusak, lampu harus diseri dengan hambatan sebesar...",o:["6 Ω","12 Ω","18 Ω","3 Ω"],a:0,p:"Arus normal lampu I = P/V = 3 : 6 = 0,5 A. Hambatan seri harus menanggung 9 - 6 = 3 V, sehingga R = 3 : 0,5 = 6 Ω."},
      {lv:3,q:"Pemanas air 1.000 W digunakan untuk memanaskan 2 kg air dari 25 °C hingga 100 °C (kalor jenis air 4.200 J/kg°C). Jika semua energi listrik berubah menjadi kalor, waktu yang dibutuhkan adalah...",o:["6,3 menit","105 menit","1,05 menit","10,5 menit"],a:3,p:"Q = m c ΔT = 2 x 4.200 x 75 = 630.000 J. t = Q : P = 630.000 : 1.000 = 630 s = 10,5 menit."},
      {lv:3,q:"Sebuah amperemeter memiliki batas ukur 1 A dan hambatan dalam 0,9 Ω. Agar dapat mengukur arus hingga 10 A, amperemeter tersebut harus dipasangi hambatan shunt...",o:["0,1 Ω secara seri","0,1 Ω secara paralel","8,1 Ω secara paralel","9 Ω secara seri"],a:1,p:"Shunt dipasang paralel dan dilalui 9 A, sedangkan amperemeter 1 A. Tegangannya sama: 1 x 0,9 = 9 x Rsh, sehingga Rsh = 0,1 Ω."},
      {lv:3,q:"Tersedia tiga hambatan identik masing-masing 6 Ω. Agar diperoleh hambatan pengganti 9 Ω, ketiganya harus disusun dengan cara...",o:["Ketiganya disusun seri","Ketiganya disusun paralel","Satu hambatan diseri dengan dua hambatan lain yang disusun paralel","Dua hambatan disusun seri, lalu diparalel dengan hambatan ketiga"],a:2,p:"Dua 6 Ω paralel menjadi 3 Ω, ditambah 6 Ω seri = 9 Ω. Seri semua 18 Ω, paralel semua 2 Ω, dan (6 + 6) paralel 6 = 4 Ω."}
    ],
    "ipa-k12-1": [
      {lv:1,q:"Menurut konsep pengikatan dan pelepasan oksigen, oksidasi adalah...",o:["Peristiwa pengikatan oksigen","Peristiwa pelepasan oksigen","Peristiwa penerimaan elektron","Peristiwa penurunan bilangan oksidasi"],a:0,p:"Contohnya besi yang bereaksi dengan oksigen membentuk karat. Konsep ini adalah konsep redoks paling awal."},
      {lv:1,q:"Zat yang mengalami reduksi dan menyebabkan zat lain teroksidasi disebut...",o:["Reduktor","Katalis","Oksidator","Hasil oksidasi"],a:2,p:"Oksidator menerima elektron (tereduksi), sehingga zat lain kehilangan elektron (teroksidasi)."},
      {lv:1,q:"Bilangan oksidasi hidrogen dalam senyawa hidrida logam seperti NaH adalah...",o:["+1","0","+2","-1"],a:3,p:"Umumnya biloks H adalah +1, tetapi dalam hidrida logam H lebih elektronegatif daripada logam sehingga biloksnya -1."},
      {lv:1,q:"Bilangan oksidasi besi pada ion Fe³⁺ adalah...",o:["-3","+3","0","+2"],a:1,p:"Biloks ion monoatomik sama dengan muatannya, yaitu +3."},
      {lv:1,q:"Jumlah bilangan oksidasi semua atom dalam senyawa netral adalah...",o:["+1","-1","0","Sama dengan jumlah atomnya"],a:2,p:"Senyawa netral tidak bermuatan, sehingga jumlah biloks seluruh atomnya nol."},
      {lv:1,q:"Bilangan oksidasi unsur golongan IA (seperti Na dan K) di dalam senyawanya adalah...",o:["+1","+2","-1","0"],a:0,p:"Logam golongan IA mudah melepas satu elektron, sehingga biloksnya dalam senyawa selalu +1."},
      {lv:2,q:"Bilangan oksidasi Cl dalam KClO₃ adalah...",o:["+3","+5","+7","-1"],a:1,p:"K = +1, O = -2. +1 + Cl + 3(-2) = 0, sehingga Cl = +5."},
      {lv:2,q:"Bilangan oksidasi C dalam ion CO₃²⁻ adalah...",o:["+2","+6","-2","+4"],a:3,p:"C + 3(-2) = -2, sehingga C = -2 + 6 = +4."},
      {lv:2,q:"Bilangan oksidasi P dalam H₃PO₄ adalah...",o:["+3","+4","-3","+5"],a:3,p:"3(+1) + P + 4(-2) = 0, sehingga P = 8 - 3 = +5."},
      {lv:2,q:"Pada reaksi 2Mg + O₂ → 2MgO, magnesium mengalami...",o:["Reduksi, karena biloksnya turun dari +2 menjadi 0","Oksidasi, karena biloksnya naik dari 0 menjadi +2","Oksidasi, karena biloksnya turun dari 0 menjadi -2","Bukan oksidasi maupun reduksi"],a:1,p:"Mg sebagai unsur bebas berbiloks 0, dan dalam MgO berbiloks +2. Kenaikan biloks berarti oksidasi."},
      {lv:2,q:"Pada reaksi CuO + H₂ → Cu + H₂O, zat hasil reduksi adalah...",o:["Cu","H₂O","CuO","H₂"],a:0,p:"Biloks Cu turun dari +2 (dalam CuO) menjadi 0 (Cu). Zat yang terbentuk dari proses reduksi adalah Cu."},
      {lv:2,q:"Bilangan oksidasi O dalam hidrogen peroksida (H₂O₂) adalah...",o:["-2","+1","-1","0"],a:2,p:"2(+1) + 2(O) = 0, sehingga O = -1. Peroksida adalah pengecualian dari biloks O = -2."},
      {lv:3,q:"Reaksi MnO₄⁻ + Fe²⁺ → Mn²⁺ + Fe³⁺ berlangsung dalam suasana asam. Setelah disetarakan, koefisien Fe²⁺ untuk setiap 1 ion MnO₄⁻ adalah...",o:["1","5","2","8"],a:1,p:"Mn turun dari +7 ke +2 (menerima 5 elektron). Fe naik dari +2 ke +3 (melepas 1 elektron). Agar elektron setara, dibutuhkan 5 Fe²⁺."},
      {lv:3,q:"Reaksi 2H₂S + SO₂ → 3S + 2H₂O disebut reaksi konproporsionasi karena...",o:["Satu zat mengalami oksidasi dan reduksi sekaligus","Tidak ada perubahan bilangan oksidasi","Oksigen bertindak sebagai reduktor","Hasil oksidasi dan hasil reduksinya adalah zat yang sama, yaitu S"],a:3,p:"S dalam H₂S (-2) naik menjadi 0, dan S dalam SO₂ (+4) turun menjadi 0. Keduanya menghasilkan S."},
      {lv:3,q:"Dalam suasana asam, ion Cr₂O₇²⁻ direduksi menjadi Cr³⁺. Jumlah elektron yang diterima oleh setiap ion Cr₂O₇²⁻ adalah...",o:["3","2","6","12"],a:2,p:"Biloks Cr turun dari +6 ke +3, yaitu 3 elektron per atom Cr. Satu ion memiliki 2 atom Cr, sehingga 2 x 3 = 6 elektron."},
      {lv:3,q:"Pipa besi yang ditanam di dalam tanah dihubungkan dengan batangan logam magnesium agar tidak berkarat. Alasan yang tepat adalah...",o:["Magnesium lebih mudah teroksidasi daripada besi sehingga magnesium yang terkorosi, bukan besi","Magnesium lebih sukar teroksidasi daripada besi","Magnesium membuat besi menjadi oksidator kuat","Magnesium menyerap semua air di dalam tanah"],a:0,p:"Potensial reduksi Mg lebih negatif daripada Fe. Mg bertindak sebagai anode korban (perlindungan katodik)."},
      {lv:3,q:"Pada reaksi 2KMnO₄ + 16HCl → 2KCl + 2MnCl₂ + 5Cl₂ + 8H₂O, zat yang merupakan hasil oksidasi adalah...",o:["Cl₂","MnCl₂","KCl","H₂O"],a:0,p:"Cl dalam HCl (-1) naik menjadi 0 dalam Cl₂. Jadi Cl₂ adalah hasil oksidasi, sedangkan MnCl₂ hasil reduksi."},
      {lv:3,q:"Bilangan oksidasi S dalam natrium tiosulfat (Na₂S₂O₃) adalah...",o:["+4","+6","-2","+2"],a:3,p:"2(+1) + 2S + 3(-2) = 0, sehingga 2S = 4 dan S = +2 (nilai rata-rata)."},
      {lv:3,q:"Pada reaksi 3Cu + 8HNO₃ → 3Cu(NO₃)₂ + 2NO + 4H₂O, perubahan bilangan oksidasi N pada zat yang tereduksi adalah...",o:["Dari +5 menjadi +5","Dari +5 menjadi +2","Dari +2 menjadi +5","Dari -3 menjadi +2"],a:1,p:"N dalam HNO₃ berbiloks +5. Sebagian N berubah menjadi NO dengan biloks +2, sedangkan N dalam Cu(NO₃)₂ tetap +5."},
      {lv:3,q:"Hidrogen peroksida (H₂O₂) dapat bertindak sebagai oksidator maupun reduktor. Penjelasan yang tepat adalah...",o:["Biloks O dalam H₂O₂ adalah -2 sehingga hanya bisa naik","Biloks H dalam H₂O₂ adalah 0","Biloks O dalam H₂O₂ adalah -1, berada di antara -2 dan 0, sehingga dapat turun maupun naik","H₂O₂ tidak memiliki bilangan oksidasi"],a:2,p:"Jika O turun ke -2 (menjadi H₂O), H₂O₂ menjadi oksidator. Jika O naik ke 0 (menjadi O₂), H₂O₂ menjadi reduktor."}
    ],
    "ipa-k12-2": [
      {lv:1,q:"Faktor berikut yang termasuk faktor eksternal (dari luar) yang memengaruhi pertumbuhan tumbuhan adalah...",o:["Cahaya matahari","Gen","Hormon auksin","Hormon giberelin"],a:0,p:"Faktor eksternal berasal dari lingkungan, seperti cahaya, suhu, air, dan nutrisi. Gen dan hormon adalah faktor internal."},
      {lv:1,q:"Hormon tumbuhan yang memacu perkecambahan biji dan pemanjangan batang secara berlebihan sehingga tanaman menjadi raksasa adalah...",o:["Etilen","Asam absisat","Giberelin","Kalin"],a:2,p:"Giberelin pertama kali ditemukan dari jamur Gibberella yang membuat tanaman padi tumbuh sangat tinggi."},
      {lv:1,q:"Hormon kalin jenis rizokalin berfungsi memacu pembentukan...",o:["Daun","Bunga","Batang","Akar"],a:3,p:"Kalin adalah hormon pembentuk organ. Rizokalin membentuk akar, kaulokalin batang, filokalin daun, dan antokalin bunga."},
      {lv:1,q:"Jaringan muda yang terus membelah di ujung akar dan ujung batang disebut...",o:["Kambium","Meristem apikal","Epidermis","Korteks"],a:1,p:"Meristem apikal terletak di ujung akar dan batang, dan menyebabkan tumbuhan bertambah panjang."},
      {lv:1,q:"Tipe perkecambahan yang kotiledonnya terangkat ke atas permukaan tanah disebut...",o:["Hipogeal","Vivipari","Epigeal","Dormansi"],a:2,p:"Pada epigeal, bagian di bawah kotiledon (hipokotil) memanjang sehingga kotiledon terangkat ke atas tanah."},
      {lv:1,q:"Hormon yang memacu terjadinya metamorfosis pada katak adalah...",o:["Tiroksin","Insulin","Adrenalin","Estrogen"],a:0,p:"Tiroksin dari kelenjar tiroid memicu perubahan berudu menjadi katak dewasa."},
      {lv:2,q:"Contoh tumbuhan yang mengalami perkecambahan hipogeal, yaitu kotiledonnya tetap berada di dalam tanah, adalah...",o:["Kacang hijau","Jagung","Kacang tanah","Jarak"],a:1,p:"Pada jagung, epikotil yang memanjang sehingga kotiledon tetap di dalam tanah. Kacang hijau, kacang tanah, dan jarak tergolong epigeal."},
      {lv:2,q:"Pada kurva pertumbuhan berbentuk S (sigmoid), fase yang memiliki laju pertumbuhan paling tinggi adalah...",o:["Fase awal (lag)","Fase stasioner","Fase penuaan","Fase eksponensial (logaritmik)"],a:3,p:"Pada fase eksponensial, sel membelah dan membesar dengan sangat cepat, sehingga kurva naik paling curam."},
      {lv:2,q:"Pertumbuhan primer pada tumbuhan menyebabkan...",o:["Batang bertambah besar (lebar)","Daun berguguran","Terbentuknya lingkaran tahun","Akar dan batang bertambah panjang"],a:3,p:"Pertumbuhan primer oleh meristem apikal memperpanjang akar dan batang. Pertambahan lebar adalah pertumbuhan sekunder."},
      {lv:2,q:"Tanaman yang kekurangan unsur nitrogen biasanya menunjukkan gejala...",o:["Daun menjadi hijau tua mengilap","Daun menguning (klorosis), dimulai dari daun yang tua","Batang tumbuh sangat tinggi","Bunga muncul lebih cepat"],a:1,p:"Nitrogen diperlukan untuk membentuk klorofil dan protein. Kekurangannya membuat daun pucat kekuningan."},
      {lv:2,q:"Respons tumbuhan dalam berbunga terhadap panjang pendeknya waktu penyinaran dalam sehari disebut...",o:["Fotoperiodisme","Fototropisme","Etiolasi","Dormansi"],a:0,p:"Fotoperiodisme adalah tanggapan terhadap lama penyinaran. Ada tumbuhan hari pendek, hari panjang, dan hari netral."},
      {lv:2,q:"Pada awal perkecambahan, sebelum daun pertama dapat berfotosintesis, kecambah memperoleh makanan dari...",o:["Hasil fotosintesis akar","Hormon auksin","Cadangan makanan di kotiledon atau endosperma","Air hujan saja"],a:2,p:"Kotiledon dan endosperma menyimpan cadangan makanan yang dipakai embrio untuk tumbuh sampai mampu berfotosintesis."},
      {lv:3,q:"Siswa menanam dua kelompok kecambah kacang. Kelompok A disemprot larutan giberelin, kelompok B hanya disemprot air. Kondisi lain dibuat sama. Variabel bebas pada percobaan ini adalah...",o:["Tinggi kecambah","Pemberian giberelin","Jenis kacang","Jumlah air yang disiramkan"],a:1,p:"Variabel bebas adalah faktor yang sengaja dibedakan. Tinggi kecambah adalah variabel terikat, dan kondisi lain adalah variabel kontrol."},
      {lv:3,q:"Petani teh secara rutin memangkas pucuk tanaman agar tumbuh banyak cabang dan daun baru. Penjelasan yang tepat adalah...",o:["Pemangkasan menambah kadar auksin di pucuk","Pemangkasan membuat tanaman berhenti tumbuh","Pemangkasan meningkatkan kadar asam absisat sehingga tunas tumbuh","Pemangkasan menghilangkan dominansi apikal, karena auksin dari pucuk yang menghambat tunas samping berkurang"],a:3,p:"Auksin dari ujung batang menghambat tunas lateral. Jika pucuk dipotong, hambatan hilang sehingga tunas samping tumbuh menjadi cabang."},
      {lv:3,q:"Pedagang menyimpan pisang mentah bersama beberapa buah yang sudah matang di dalam wadah tertutup agar pisang cepat matang. Penjelasan yang tepat adalah...",o:["Buah matang menyerap gas etilen dari pisang mentah","Wadah tertutup mencegah terbentuknya etilen","Buah matang melepaskan gas etilen yang mempercepat pematangan buah lain","Buah matang menghasilkan giberelin yang membuat pisang membesar"],a:2,p:"Etilen berwujud gas. Dalam wadah tertutup, etilen dari buah matang terkumpul dan memacu pematangan pisang."},
      {lv:3,q:"Biji yang baru dipanen sering tidak segera berkecambah walaupun air, suhu, dan oksigen sudah cukup. Penyebab yang paling tepat adalah...",o:["Biji sedang mengalami dormansi, antara lain karena kadar asam absisat yang tinggi atau kulit biji yang keras","Biji tidak memiliki embrio sama sekali","Biji terlalu banyak mengandung giberelin","Biji membutuhkan cahaya bulan untuk berkecambah"],a:0,p:"Asam absisat menghambat perkecambahan. Dormansi berakhir saat kadar asam absisat turun dan giberelin meningkat, atau kulit biji melunak."},
      {lv:3,q:"Tinggi sebuah tanaman 4 cm pada hari ke-2 dan 16 cm pada hari ke-6. Laju pertumbuhan rata-rata tanaman pada selang waktu tersebut adalah...",o:["3 cm/hari","4 cm/hari","2,7 cm/hari","16 cm/hari"],a:0,p:"Laju rata-rata = perubahan tinggi : selang waktu = (16 - 4) : (6 - 2) = 12 : 4 = 3 cm/hari."},
      {lv:3,q:"Pada kultur jaringan, jika media mengandung sitokinin dengan kadar lebih tinggi daripada auksin, eksplan cenderung membentuk...",o:["Akar","Biji","Bunga","Tunas"],a:3,p:"Perbandingan sitokinin lebih tinggi memacu pembentukan tunas, sedangkan auksin lebih tinggi memacu pembentukan akar."},
      {lv:3,q:"Berudu yang hidup di kolam dengan air yang sangat kekurangan iodium tidak kunjung berubah menjadi katak. Penjelasan yang tepat adalah...",o:["Iodium menghambat kerja hormon tiroksin","Iodium diperlukan untuk membentuk hormon tiroksin yang memicu metamorfosis","Berudu memerlukan iodium sebagai pengganti oksigen","Kekurangan iodium membuat berudu tumbuh lebih cepat"],a:1,p:"Tiroksin mengandung iodium. Tanpa cukup iodium, tiroksin sedikit terbentuk sehingga metamorfosis terhambat."},
      {lv:3,q:"Kelebihan hormon pertumbuhan (somatotropin) pada masa kanak-kanak, ketika tulang masih tumbuh memanjang, dapat menyebabkan...",o:["Kretinisme","Akromegali","Gigantisme","Kekerdilan"],a:2,p:"Pada anak, lempeng pertumbuhan tulang masih aktif sehingga kelebihan hormon membuat tubuh sangat tinggi. Akromegali terjadi bila kelebihan muncul setelah dewasa."}
    ]
  };
  for (const kelas of Object.values(window.BANK?.ipa || {}))
    for (const t of kelas) if (TAMBAHAN[t.id]) t.soal.push(...TAMBAHAN[t.id]);
})();
